/**
 * ספר שמות - ביאור הפשט בלשון פשוטה ובהירה
 * כולל את כל 11 פרשות חומש שמות וכל 1,209 הפסוקים (פרקים א - מ)
 */
window.PeshatShemot = {
  "1_1": "אלה שמותיהם של בני ישראל שהגיעו למצרים יחד עם יעקב אביהם, כאשר כל איש הגיע עם משפחתו:",
  "1_2": "ראובן, שמעון, לוי ויהודה.",
  "1_3": "יששכר, זבולון ובנימין.",
  "1_4": "דן ונפתלי, גד ואשר.",
  "1_5": "כל צאצאיו הישירים של יעקב מנו שבעים נפשות, ויוסף כבר היה במצרים.",
  "1_6": "במשך הזמן מתו יוסף, כל אחיו וכל בני אותו הדור.",
  "1_7": "ובני ישראל נולדו במספרים גדולים, התרבו והפכו לעם עצום וחזק מאוד, עד שארץ מצרים התמלאה בהם.",
  "1_8": "במצרים עלה לשלטון מלך חדש, שלא הכיר את יוסף ולא זכר את מה שעשה למען מצרים.",
  "1_9": "המלך אמר לבני עמו: 'ראו, העם של בני ישראל הפך לרב ועצום יותר מאיתנו'.",
  "1_10": "'בואו נפעל נגדם בחוכמה ובערמומיות כדי שלא ימשיכו להתרבות, כי אם תפרוץ מלחמה הם עלולים להצטרף לאויבים שלנו, להילחם נגדנו ולעזוב את הארץ'.",
  "1_11": "המצרים מינו עליהם מפקדי עבודה כדי לדכא אותם בעבודות כפייה קשות, ובני ישראל בנו לפרעה ערי מחסנים ואספקה: את פיתום ואת רעמסס.",
  "1_12": "אך ככל שהמצרים עינו אותם – כך בני ישראל המשיכו להתרבות ולהתפשט, והמצרים הרגישו מועקה וחרדה מפניהם.",
  "1_13": "המצרים העבידו את בני ישראל בעבודת פרך אכזרית ומפרכת.",
  "1_14": "הם מיררו את חייהם בעבודה קשה בהכנת טיט ולבנים, ובכל סוגי העבודות החקלאיות בשדה; את כל העבודות האלו הם הטילו עליהם באכזריות רבה.",
  "1_15": "מלך מצרים פנה למיילדות העבריות, ששם אחת מהן היה שפרה ושם השנייה פועה,",
  "1_16": "ואמר להן: 'כשאתן מיילדות את הנשים העבריות ורואות את התינוק על מושב הלידה – אם מדובר בבן זכר, תהרגו אותו, ואם מדובר בבת, השאירו אותה בחיים'.",
  "1_17": "אך המיילדות כיבדו ויראו את אלוהים, ולא עשו את מה שציווה עליהן מלך מצרים, אלא השאירו את התינוקות הזכרים בחיים.",
  "1_18": "מלך מצרים קרא למיילדות ושאל אותן: 'מדוע עשיתן זאת והשארתן את הילדים בחיים?!'.",
  "1_19": "המיילדות ענו לפרעה: 'הנשים העבריות אינן כמו הנשים המצריות; הן חזקות ומיומנות, ועוד לפני שהמיילדת מספיקה להגיע אליהן – הן כבר יולדות בעצמן'.",
  "1_20": "אלוהים גמל בטוב למיילדות, והעם המשיך להתרבות ולהתעצם מאוד.",
  "1_21": "ומכיוון שהמיילדות יראו את אלוהים, הוא העניק להן משפחות ושושלות מבורכות.",
  "1_22": "אז ציווה פרעה פקודה לכל עמו: 'כל תינוק זכר שנולד אצל העברים – השליכו אותו לנהר הנילוס, ורק את הבנות השאירו בחיים'.",
  "2_1": "איש משבט לוי הלך ונשא לאישה אישה משבט לוי.",
  "2_2": "האישה הרתה וילדה בן. כשראתה שהוא תינוק יפה ובריא במיוחד, היא החביאה אותו במשך שלושה חודשים.",
  "2_3": "כשלא יכלה עוד להסתיר אותו, לקחה עבורו תיבה עשויה מצמחי גומא, מרחה אותה בחימר ובזפת כדי למנוע כניסת מים, שמה בתוכה את הילד והניחה אותה בין קני הסוף על שפת הנילוס.",
  "2_4": "אחותו של התינוק נעמדה במרחק כדי לראות מה יקרה לו.",
  "2_5": "בתו של פרעה ירדה להתרחץ בנילוס, בזמן שמשרתותיה טיילו על גדת הנהר. היא ראתה את התיבה בין קני הסוף ושלחה את שפחתה להביא אותה.",
  "2_6": "כשפתחה את התיבה, ראתה את הילד והנה הוא בוכה; היא התמלאה ברחמים עליו ואמרה: 'זהו אחד מילדי העברים'.",
  "2_7": "אז אמרה אחותו של הילד לבת פרעה: 'האם תרצי שאלך ואקרא לך אישה מינקת מבין העבריות, כדי שתניק עבורך את הילד?'.",
  "2_8": "בת פרעה ענתה לה: 'לכי'. הנערה הלכה וקראה לאמו של הילד.",
  "2_9": "בת פרעה אמרה לה: 'קחי את הילד הזה והניקי אותו עבורי, ואני אשלם לך את שכרך'. האישה לקחה את בנה והניקה אותו.",
  "2_10": "כשהילד גדל, היא הביאה אותו לבת פרעה, שאימצה אותו לבן. היא קראה לו משה, והסבירה: 'כי מתוך המים משכתי אותו'.",
  "2_11": "באותם ימים, לאחר שמשה כבר גדל, הוא יצא אל בני עמו וראה את סבלם ועבודת הכפייה שלהם; הוא ראה איש מצרי מכה איש עברי מאחיו.",
  "2_12": "משה הביט לכל עבר וראה שאין איש רואה; הוא היכה את המצרי למוות והטמין את גופתו בחול.",
  "2_13": "למחרת הוא יצא שוב, וראה שני אנשים עברים רבים זה עם זה. הוא אמר לתוקף: 'מדוע אתה מכה את חברך?'.",
  "2_14": "האיש ענה לו: 'מי מינה אותך להיות מנהיג ושופט עלינו? האם אתה מתכוון להרוג אותי כמו שהרגת את המצרי?' משה נבהל וחשב: 'אם כך, המעשה שעשיתי כבר נודע!'.",
  "2_15": "פרעה שמע על המקרה וביקש להוציא את משה להורג, אך משה ברח מפני פרעה והגיע לארץ מדין, ושם התיישב ליד באר מים.",
  "2_16": "לכהן מדין היו שבע בנות; הן באו אל הבאר, שאבו מים ומילאו את השוקתות כדי להשקות את צאן אביהן.",
  "2_17": "רועים אחרים הגיעו וגירשו אותן, אך משה קם להגנתן, עזר להן והשקה את הצאן שלהן.",
  "2_18": "כשהן חזרו לרעואל אביהן, הוא שאל: 'מדוע חזרתן היום כל כך מהר?'.",
  "2_19": "הן ענו: 'איש מצרי הציל אותנו מידי הרועים, וגם שאב מים עבורנו והשקה את הצאן'.",
  "2_20": "הוא אמר לבנותיו: 'ואיפה הוא? מדוע עזבתן את האיש? קראו לו שיבוא לאכול לחם'.",
  "2_21": "משה הסכים להישאר ולגור עם האיש, ורעואל נתן למשה את בתו ציפורה לאישה.",
  "2_22": "ציפורה ילדה בן, ומשה קרא לו גרשום, כי אמר: 'הייתי גר וזר בארץ זרה'.",
  "2_23": "במהלך אותם ימים רבים מת מלך מצרים, ובני ישראל נאנחו מרוב עבודת הפרך וזעקו לעזרה; זעקתם עלתה אל אלוהים מתוך סבלם.",
  "2_24": "אלוהים שמע את נאקתם, ונזכר בברית שכרת עם אברהם, יצחק ויעקב.",
  "2_25": "אלוהים ראה את מצבם של בני ישראל והחליט להתערב ולגאול אותם.",
  "3_1": "משה רעה את צאן יתרו חותנו, כהן מדין; הוא הוביל את הצאן עמוק אל תוך המדבר, והגיע אל הר האלוהים, הר חורב.",
  "3_2": "מלאך ה' נגלה אליו בלהבת אש מתוך שיח קוצני (סנה); משה הביט וראה שהסנה בוער באש, אך אינו נשרף או מתכלה.",
  "3_3": "משה אמר לעצמו: 'אגש לשם ואראה את המראה המופלא הזה – מדוע הסנה אינו נשרף?'.",
  "3_4": "כאשר ה' ראה שמשה סוטה מדרכו כדי להביט, הוא קרא אליו מתוך הסנה: 'משה, משה!', ומשה ענה: 'הנני, אני מקשיב'.",
  "3_5": "אלוהים אמר: 'אל תתקרב לכאן; חלוץ את נעליך מעל רגליך, כי המקום שבו אתה עומד הוא אדמת קודש'.",
  "3_6": "הוא הוסיף ואמר: 'אני אלוהי אביך – אלוהי אברהם, אלוהי יצחק ואלוהי יעקב'. משה הסתיר את פניו כי חשש להביט לעבר האלוהים.",
  "3_7": "ה' אמר: 'ראיתי בבירור את סבלו של עמי שבמצרים, שמעתי את זעקתם בגלל מפקדי העבודה שלהם, ואני מכיר היטב את מכאוביהם'.",
  "3_8": "'ירדתי כדי להציל אותם מידי המצרים, ולהעלות אותם מאותה ארץ אל ארץ טובה ורחבה, ארץ שופעת חלב ודבש – מקומם של הכנעני, החיתי, האמורי, הפריזי, החיווי והיבוסי'.",
  "3_9": "'ועכשיו, זעקתם של בני ישראל הגיעה אליי, וגם ראיתי את הלחץ והדיכוי שהמצרים מפעילים עליהם'.",
  "3_10": "'לכן עכשיו צא לדרך: אני שולח אותך אל פרעה, כדי שתוציא את עמי, בני ישראל, ממצרים'.",
  "3_11": "אך משה אמר לאלוהים: 'מי אני שאגש אל פרעה ואוציא את בני ישראל ממצרים? אינני מתאים למשימה כזו!'.",
  "3_12": "אלוהים הבטיח לו: 'אני אהיה איתך, וזה יהיה האות לכך שאני הוא ששלחתי אותך: כאשר תוציא את העם ממצרים, אתם תעבדו את האלוהים כאן על ההר הזה'.",
  "3_13": "משה אמר לאלוהים: 'הנה, אבוא אל בני ישראל ואומר להם: אלוהי אבותיכם שלח אותי אליכם, והם ישאלו אותי: מה שמו? מה אגיד להם?'.",
  "3_14": "אלוהים ענה למשה: 'אהיה אשר אהיה' (אני קיים תמיד והווה לעד). והוסיף: 'כך תאמר לבני ישראל: ה' הנצחי שלח אותי אליכם'.",
  "3_15": "אלוהים אמר עוד למשה: 'כך תגיד לבני ישראל: ה' אלוהי אבותיכם, אלוהי אברהם, אלוהי יצחק ואלוהי יעקב, שלח אותי אליכם; זהו שמי לתמיד, וכך יזכרו אותי מדור לדור'.",
  "3_16": "'לך ואסוף את זקני ומנהיגי ישראל, ואמור להם: ה' אלוהי אבותיכם, אלוהי אברהם, יצחק ויעקב, נגלה אליי ואמר: זכרתי אתכם וראיתי את כל מה שנעשה לכם במצרים'.",
  "3_17": "'והבטחתי: אעלה אתכם מתוך הסבל והדיכוי שבמצרים אל ארץ הכנעני, החיתי, האמורי, הפריזי, החיווי והיבוסי – אל ארץ שופעת חלב ודבש'.",
  "3_18": "'הם יקשיבו לדבריך; אז תבוא אתה וזקני ישראל אל מלך מצרים ותאמרו לו: ה' אלוהי העברים נגלה אלינו, וכעת אנא הרשה לנו ללכת מרחק של שלושה ימי הליכה במדבר, כדי שנקריב קרבנות לה' אלוהינו'.",
  "3_19": "'אני יודע מראש שמלך מצרים לא ירשה לכם ללכת, אלא אם כן ייכפה עליו הדבר ביד חזקה'.",
  "3_20": "'אז אושיט את ידי ואכה את מצרים בכל המופתים והנפלאות שאעשה בקרבה, ורק אחרי כן הוא ישלח אתכם'.",
  "3_21": "'אגרום לכך שהעם ימצא חן בעיני המצרים, וכאשר תצאו – לא תצאו בידיים ריקות'.",
  "3_22": "'כל אישה תבקש משכנתה ומדיירת ביתה כלי כסף, כלי זהב ובגדים; תשימו אותם על בניכם ועל בנותיכם, וכך תיקחו רכוש רב ממצרים כפיצוי על שנות העבדות'.",
  "4_1": "משה השיב ואמר: 'והרי הם לא יאמינו לי ולא ישמעו בקולי, אלא יגידו: ה' בכלל לא נגלה אליך!'.",
  "4_2": "ה' שאל אותו: 'מה זה שבידך?', ומשה ענה: 'מקל רועים'.",
  "4_3": "ה' אמר: 'השלך אותו לארץ'. משה השליך אותו ארצה, והמקל הפך לנחש; משה נבהל וברח מפניו.",
  "4_4": "אז אמר ה' למשה: 'הושט את ידך ותפוס אותו בזנבו'. משה הושיט את ידו, תפס אותו, והנחש חזר להיות מקל בידו.",
  "4_5": "'עשה זאת כדי שיאמינו שה' אלוהי אבותיהם – אלוהי אברהם, אלוהי יצחק ואלוהי יעקב – אכן נגלה אליך'.",
  "4_6": "ה' אמר לו עוד: 'הכנס עכשיו את ידך אל תוך חיקך'. משה הכניס את ידו, וכשהוציא אותה – הנה ידו מכוסה בצרעת לבנה כמו שלג.",
  "4_7": "ה' אמר: 'החזר את ידך אל חיקך'. הוא החזיר את ידו, וכשהוציא אותה שוב מחיקו – הנה היא חזרה להיות בריאה כמו שאר גופו.",
  "4_8": "'אם הם לא יאמינו לך ולא ישתכנעו מהאות הראשון – הם יאמינו בעקבות האות השני'.",
  "4_9": "'ואם לא יאמינו אפילו לשני האותות האלה ולא ישמעו בקולך, קח מים מנהר הנילוס ושפוך אותם על היבשה; המים שתיקח מן הנהר יהפכו לדם על האדמה'.",
  "4_10": "משה אמר לה': 'בבקשה אדוני, אינני איש של מילים – לא בעבר וגם לא מאז שהתחלת לדבר איתי; אני מתקשה בדיבור וכבד פה ולשון'.",
  "4_11": "ה' ענה לו: 'מי העניק לאדם פה? מי עושה אדם לאילם, חירש, רואה או עיוור? האם לא אני, ה'?!'.",
  "4_12": "'לכן עכשיו צא לדרך; אני אהיה עם פיך ואדריך אותך מה עליך לומר'.",
  "4_13": "אך משה אמר: 'אנא אדוני, שלח בבקשה מישהו אחר שראוי יותר לשליחות זו!'.",
  "4_14": "ה' כעס על משה ואמר: 'הרי יש לך את אהרן אחיך משבט לוי! אני יודע שהוא מדבר ברהיטות ובכישרון; יתרה מזאת, הנה הוא כבר יוצא לקראתך, וכאשר יראה אותך ישמח מאוד בליבו'.",
  "4_15": "'אתה תדבר אליו ותשים את הדברים בפיו; אני אהיה עם פיך ועם פיו, ואלמד אתכם מה עליכם לעשות'.",
  "4_16": "'הוא ידבר אל העם במקומך; הוא יהיה לך לפה ודובר, ואתה תהיה לו למנהיג המקבל את דברי האלוהים'.",
  "4_17": "'ואת המקל הזה קח בידך, כי בעזרתו תעשה את האותות והמופתים'.",
  "4_18": "משה חזר אל יתרו חותנו ואמר לו: 'אני מבקש לחזור אל אחיי שבמצרים, כדי לראות אם הם עדיין בחיים'. יתרו אמר למשה: 'לך לשלום'.",
  "4_19": "ה' אמר למשה במדין: 'לך, חזור למצרים, כי מתו כל האנשים שרצו להרוג אותך'.",
  "4_20": "משה לקח את אשתו ואת בניו, הרכיב אותם על חמור וחזר לארץ מצרים; ומשה לקח את מקל האלוהים בידו.",
  "4_21": "ה' אמר למשה: 'כאשר תחזור למצרים, שים לב לעשות לפני פרעה את כל המופתים שנתתי בידך; אך אני אחזק את לבו והוא יסרב לשלח את העם'.",
  "4_22": "'אז תאמר לפרעה: כה אמר ה': עם ישראל הוא בני הבכור'.",
  "4_23": "'ואמרתי לך: שלח את בני כדי שיעבוד אותי, אך סירבת לשלח אותו; לכן הנה אני הולך להרוג את בנך הבכור!'.",
  "4_24": "במהלך הדרך, במקום שבו שהו במלון, פגש בו מלאך ה' וביקש להמית אותו (כי התעכב במילת בנו).",
  "4_25": "ציפורה לקחה מיד אבן צור חדה, חתכה את עורלת בנה, נגעה בה לרגליו ואמרה: 'הצלת חיי בני באמצעות ברית הדם קשרה אותנו מחדש!'.",
  "4_26": "אז הרפה ממנו המלאך; והיא אמרה: 'חתן דמים למילות' על ברית המילה.",
  "4_27": "ה' אמר לאהרן: 'צא לקראת משה אל המדבר'. אהרן הלך, פגש אותו בהר האלוהים ונישק לו באהבה.",
  "4_28": "משה סיפר לאהרן את כל דברי ה' ששלח אותו, ואת כל האותות והמופתים שציווה עליו לבצע.",
  "4_29": "משה ואהרן הלכו ואספו את כל זקני ומנהיגי בני ישראל.",
  "4_30": "אהרן אמר להם את כל הדברים שה' אמר למשה, ומשה ביצע את האותות לעיני כל העם.",
  "4_31": "העם האמין; וכאשר שמעו שה' זכר את בני ישראל וראה את סבלם, הם הרכינו ראש והשתחוו בהודיה.",
  "5_1": "לאחר מכן באו משה ואהרן אל פרעה ואמרו לו: 'כה אמר ה' אלוהי ישראל: שלח את עמי כדי שיחגגו לי חג במדבר'.",
  "5_2": "פרעה ענה: 'מי זה ה' שאשמע בקולו לשלח את ישראל? אינני מכיר את ה', וגם לא אשלח את ישראל!'.",
  "5_3": "הם אמרו: 'אלוהי העברים נגלה אלינו; אנא הרשה לנו ללכת מרחק שלושה ימי הליכה במדבר ולהקריב קרבנות לה' אלוהינו, כדי שלא יפגע בנו במגפה או במלחמה'.",
  "5_4": "מלך מצרים אמר להם: 'משה ואהרן, למה אתם מפריעים לעם מעבודתו? לכו מיד חזרה לעבודות הכפייה שלכם!'.",
  "5_5": "פרעה הוסיף ואמר: 'הרי בני עמכם רבים כעת בארץ, ואתם מנסים להשבית אותם מעבודתם הקשה?!'.",
  "5_6": "באותו יום ציווה פרעה על מפקדי העבודה המצריים ועל השוטרים העבריים הממונים על העם:",
  "5_7": "'אל תתנו עוד תבן וקש לעם כדי להכין לבנים כפי שעשיתם עד עכשיו; שהם ילכו בעצמם ויאספו לעצמם קש!'.",
  "5_8": "'אך את כמות הלבנים המדויקת שהם הכינו עד היום תמשיכו לדרוש מהם במלואה, אל תפחיתו ממנה כלל! הם עצלנים, ובגלל זה הם צועקים: בואו נלך לזבוח לאלוהינו'.",
  "5_9": "'יש להכביד עוד יותר את העבודה על האנשים כדי שיהיו שקועים בה לחלוטין, ולא ישעו לדברי שקר והבל'.",
  "5_10": "מפקדי העבודה והשוטרים יצאו ואמרו לעם: 'כך הורה פרעה: אינני נותן לכם תבן עוד'.",
  "5_11": "'לכו בעצמכם וקחו לכם קש מכל מקום שתוכלו למצוא, אך מכסת העבודה שלכם לא תופחת אפילו במעט!'.",
  "5_12": "העם התפזר בכל רחבי מצרים כדי ללקט קש יבש שישמש כתבן לייצור הלבנים.",
  "5_13": "מפקדי העבודה לחצו עליהם ללא הרף ואמרו: 'השלימו את מכסת העבודה היומית שלכם בדיוק כמו בימים שקיבלתם תבן מוכן!'.",
  "5_14": "והשוטרים מבני ישראל, שמונו עליהם בידי מפקדי פרעה, הוכו פיזית וננזפו: 'מדוע לא השלמתם את מכסת הלבנים הקבועה לכם כמו קודם, לא אתמול ולא היום?!'.",
  "5_15": "שוטרי בני ישראל באו וזעקו אל פרעה בתלונה: 'למה אתה מתנהג כך לעבדיך?'.",
  "5_16": "'תבן לא נותנים לעבדיך, ולבנים אומרים לנו: עשו! והנה משרתיך מוכים, בזמן שהאשמה היא של אנשיך שלך!'.",
  "5_17": "פרעה ענה להם: 'עצלנים אתם, פשוט עצלנים! לכן אתם אומרים: נלך ונזבח לה''.",
  "5_18": "'ועכשיו לכו לעבוד! תבן לא תקבלו, ואת מכסת הלבנים המלאה תספקו בכל יום!'.",
  "5_19": "שוטרי בני ישראל ראו שהם שקועים בצרה גדולה, לאחר שנאמר להם: 'אל תפחיתו כלל ממכסת הלבנים היומית שלכם'.",
  "5_20": "כשיצאו מלפני פרעה, הם פגשו את משה ואת אהרן שעמדו וחיכו להם.",
  "5_21": "השוטרים אמרו למשה ולאהרן: 'הלוואי שה' ישפוט אתכם ויראה מה עוללתם! הבאשתם את שמנו בעיני פרעה ובעיני שריו, ושמתם חרב בידם כדי להרוג אותנו!'.",
  "5_22": "משה פנה אל ה' בכאב ושאל: 'אדוני, למה גרמת רעה כזאת לעם הזה? למה בכלל שלחת אותי?'.",
  "5_23": "'הרי מאז שבאתי אל פרעה לדבר בשמך, מצבו של העם רק הוחמר, ואתה כלל לא הצלת את עמך!'.",
  "6_1": "ה' ענה למשה: 'עכשיו אתה תראה מה אעשה לפרעה; ביד חזקה הוא ישלח אותם, וביד חזקה הוא אף יגרש אותם מארצו!'.",
  "6_2": "אלוהים דיבר אל משה ואמר לו: 'אני ה''.",
  "6_3": "'נגליתי לאברהם, ליצחק וליעקב בשם 'אל שדי' (בהבטחות לעתיד), אך את שמי המפורש 'ה'' – המבטא את מימוש ונאמנות ההבטחות בפועל – לא הראיתי להם במלואו'.",
  "6_4": "'גם כרתתי איתם ברית לתת להם את ארץ כנען, הארץ שבה הם גרו כתושבים זרים'.",
  "6_5": "'ועכשיו, שמעתי את זעקתם ונאקתם של בני ישראל שהמצרים מעבידים אותם בפרך, ואני זוכר את בריתי'.",
  "6_6": "'לכן אמור לבני ישראל: אני ה'! אני אוציא אתכם מעבודות הכפייה והסבל של מצרים, אציל אתכם מהשעבוד שלהם, ואגאל אתכם בכוח עצום ובמשפטים כבדים שאביא על המצרים'.",
  "6_7": "'אקח אתכם להיות לי לעם, ואהיה לכם לאלוהים; אתם תדעו שאני ה' אלוהיכם, אשר מוציא אתכם מסבלות מצרים'.",
  "6_8": "'אביא אתכם אל הארץ שנשבעתי לתת לאברהם, ליצחק וליעקב, ואתן אותה לכם כירושה קבועה לדורות; אני ה''.'",
  "6_9": "משה מסר את הדברים המנחמים האלה לבני ישראל, אך הם לא היו מסוגלים להקשיב לו מרוב ייאוש, קוצר רוח והעבודה המפרכת שהתישה אותם.",
  "6_10": "ה' פנה שוב אל משה ואמר:",
  "6_11": "'בוא ודבר אל פרעה מלך מצרים, שישלח את בני ישראל מארצו'.",
  "6_12": "אך משה טען לפני ה': 'הרי אפילו בני ישראל לא הקשיבו לי, אז איך יקשיב לי פרעה, במיוחד כשאני מתקשה בדיבור ומגמגם?!'.",
  "6_13": "ה' דיבר אל משה ואל אהרן וציווה עליהם להנהיג את בני ישראל בסבלנות, ולהתייצב בפני פרעה מלך מצרים כדי להוציא את בני ישראל מארץ מצרים.",
  "6_14": "אלה ראשי המשפחות שלהם: בני ראובן, בכורו של ישראל – חנוך, פלוא, חצרון וכרמי; אלה משפחות שבט ראובן.",
  "6_15": "ובני שמעון – ימואל, ימין, אוהד, יכין, צוחר, ושאול בן הכנענית; אלה משפחות שבט שמעון.",
  "6_16": "ואלה שמות בני לוי לפי תולדותיהם: גרשון, קהת ומררי; לוי חי מאה שלושים ושבע שנים.",
  "6_17": "בני גרשון – לבני ושמעי, למשפחותיהם.",
  "6_18": "בני קהת – עמרם, יצהר, חברון ועוזיאל; קהת חי מאה שלושים ושלוש שנים.",
  "6_19": "ובני מררי – מחלי ומושי; אלה הן משפחות שבט לוי לפי סדר תולדותיהם.",
  "6_20": "עמרם נשא לאישה את יוכבד דודתו, והיא ילדה לו את אהרן ואת משה; עמרם חי מאה שלושים ושבע שנים.",
  "6_21": "בני יצהר – קורח, נפג וזכרי.",
  "6_22": "ובני עוזיאל – מישאל, אלצפן וסתרי.",
  "6_23": "אהרן נשא לאישה את אלישבע בת עמינדב, אחות נחשון (נשיא שבט יהודה), והיא ילדה לו את נדב, אביהוא, אלעזר ואיתמר.",
  "6_24": "ובני קורח – אסיר, אלקנה ואביאסף; אלה משפחות הקורחי.",
  "6_25": "אלעזר בן אהרן נשא לאישה אחת מבנות פוטיאל, והיא ילדה לו את פינחס; אלה ראשי אבות שבט לוי למשפחותיהם.",
  "6_26": "אלה הם אותם אהרן ומשה שה' ציווה עליהם: 'הוציאו את בני ישראל מארץ מצרים לפי מחנותיהם'.",
  "6_27": "הם אלה שדיברו אל פרעה מלך מצרים כדי להוציא את בני ישראל ממצרים – הם משה ואהרן.",
  "6_28": "וביום שבו דיבר ה' אל משה בארץ מצרים,",
  "6_29": "ה' אמר למשה: 'אני ה'! אמור לפרעה מלך מצרים את כל הדברים שאני אומר לך'.",
  "6_30": "ומשה שב וטען לפני ה': 'הרי אני מתקשה בדיבור, אז מדוע שפרעה יקשיב לי?!'.",
  "7_1": "ה' ענה למשה: 'ראה, נתתי לך מעמד של שופט וסמכות עליונה מול פרעה, ואהרן אחיך ישמש כנביא וכדובר שלך'.",
  "7_2": "'אתה תאמר לאהרן את כל מה שאצווה עליך, ואהרן אחיך ידבר אל פרעה כדי שישלח את בני ישראל מארצו'.",
  "7_3": "'אך אני אחזק ואקשה את עקשנותו של פרעה, וכך אוכל להרבות את האותות והמופתים שלי בארץ מצרים'.",
  "7_4": "'פרעה לא יקשיב לכם, ואז אני אנחית מכות קשות על מצרים ואוציא את מחנות עמי, בני ישראל, מארץ מצרים בעונשים גדולים'.",
  "7_5": "'והמצרים יבינו שאני ה' כאשר אפגין את כוחי עליהם ואוציא את בני ישראל מתוכם'.",
  "7_6": "משה ואהרן עשו בדיוק את מה שה' ציווה עליהם.",
  "7_7": "משה היה בן שמונים שנה ואהרן בן שמונים ושלוש שנה כאשר דיברו אל פרעה.",
  "7_8": "ה' אמר למשה ולאהרן:",
  "7_9": "'אם פרעה יגיד לכם: הציגו מופת שיוכיח את שליחותכם, אמור לאהרן: קח את המקל שלך והשלך אותו לפני פרעה, והוא יהפוך לנחש גדול'.",
  "7_10": "משה ואהרן באו אל פרעה ועשו בדיוק כפי שה' ציווה: אהרן השליך את מקלו לפני פרעה ולפני יועציו, והוא הפך לנחש גדול.",
  "7_11": "פרעה הזעיק גם הוא את חכמי מצרים והמכשפים שלו, וחרטומי מצרים ביצעו מעשה דומה באמצעות קסמיהם ולחשיהם:",
  "7_12": "כל אחד מהם השליך את מקלו והמקלות הפכו לנחשים, אך מקלו של אהרן בלע את המקלות שלהם.",
  "7_13": "למרות זאת לבו של פרעה התקשה והוא לא הקשיב להם, בדיוק כפי שה' חזה מראש.",
  "7_14": "ה' אמר למשה: 'לבו של פרעה אטום ועקשן; הוא מסרב לשלח את העם'.",
  "7_15": "'לך אל פרעה מחר בבוקר כשהוא יוצא אל נהר הנילוס, והתייצב מולו על שפת הנהר; קח בידך את המקל שהפך לנחש'.",
  "7_16": "'ואמור לו: ה' אלוהי העברים שלח אותי אליך לומר: שלח את עמי כדי שיעבדו אותי במדבר, והנה עד עכשיו סירבת להקשיב'.",
  "7_17": "'כה אמר ה': בדרך זו תדע שאני ה': הנה אני מכה במקל שבידי על מי הנילוס, והם יהפכו כולם לדם'.",
  "7_18": "'הדגים שבנהר ימותו, הנהר יעלה צחנה נוראה, והמצרים יתקשו וייגעו למצוא מים ראויים לשתייה מן הנילוס'.",
  "7_19": "ה' אמר למשה: 'אמור לאהרן: קח את מקלך והושט את ידך מעל מקורות המים של מצרים – מעל הנהרות, התעלות, האגמים וכל מאגרי המים שלהם – וכולם יהפכו לדם; דם יהיה בכל ארץ מצרים, אפילו בתוך כלי עץ וכלי אבן'.",
  "7_20": "משה ואהרן עשו בדיוק כפי שה' ציווה: אהרן הרים את המקל והיכה במי הנילוס לעיני פרעה ולעיני שריו ועבדיו, וכל מי הנהר הפכו מיד לדם.",
  "7_21": "הדגים שבנהר מתו, הנהר הסריח קשות, והמצרים לא יכלו לשתות ממימיו; דם היה בכל רחבי מצרים.",
  "7_22": "אך חרטומי מצרים עשו דבר דומה בעזרת לחשי הקסם שלהם, ולכן לבו של פרעה התקשה והוא לא שמע להם, כפי שה' אמר.",
  "7_23": "פרעה הסתובב באדישות, נכנס אל ארמונו ולא ייחס חשיבות גם למכה הזו.",
  "7_24": "כל המצרים חפרו סביב הנילוס בניסיון למצוא מי תהום לשתייה, כי לא יכלו לשתות ממי הנהר.",
  "7_25": "כך עברו שבעה ימים שלמים מאז שה' היכה את מי הנילוס.",
  "7_26": "ה' אמר למשה: 'בוא אל פרעה ואמור לו: כה אמר ה': שלח את עמי כדי שיעבדו אותי'.",
  "7_27": "'ואם תמשיך לסרב לשלח אותם – הנה אני עומד להכות את כל ארצך במכת צפרדעים'.",
  "7_28": "'הנילוס ישרוץ צפרדעים בהמוניהן, והן יעלו וייכנסו אל ביתך, אל חדר השינה שלך, על מיטתך, לתוך בתי שריך ועמך, ואפילו לתוך תנורי האפייה וקערות הבצק שלך'.",
  "7_29": "'הצפרדעים יטפסו עליך, על עמך ועל כל משרתיך'.",
  "8_1": "ה' אמר למשה: 'אמור לאהרן: הושט את ידך עם מקלך מעל הנהרות, התעלות והאגמים, והעלה את הצפרדעים על כל ארץ מצרים'.",
  "8_2": "אהרן הושיט את ידו מעל מימי מצרים, והמוני צפרדעים עלו וכיסו את כל ארץ מצרים.",
  "8_3": "החרטומים עשו מעשה דומה באמצעות כשפיהם, והעלו גם הם צפרדעים על ארץ מצרים.",
  "8_4": "אז קרא פרעה למשה ולאהרן ואמר: 'התפללו אל ה' שיסיר את הצפרדעים ממני ומעמי, ואני אשלח את העם להקריב קרבנות לה''.'",
  "8_5": "משה אמר לפרעה: 'אני משאיר לך את הכבוד לקבוע את הזמן: לאיזה מועד תרצה שאתפלל עבורך, עבור שריך ועמך, כדי שהצפרדעים ייעלמו מבתיכם ויישארו רק בנילוס?'.",
  "8_6": "פרעה ענה: 'למחר'. משה השיב: 'יהיה כדבריך, כדי שתדע שאין עוד אל כמו ה' אלוהינו'.",
  "8_7": "'הצפרדעים ייעלמו ממך, מבתיך, מיועציך ומעמך, ורק בנהר הנילוס הן יישארו'.",
  "8_8": "משה ואהרן יצאו מלפני פרעה, ומשה זעק והתפלל אל ה' בעניין הצפרדעים שהביא על פרעה.",
  "8_9": "ה' נענה לבקשת משה, והצפרדעים מתו בתוך הבתים, בחצרות ובשדות.",
  "8_10": "המצרים אספו אותן בערימות ענקיות, וכל הארץ הסריחה מהן.",
  "8_11": "אך כשפרעה ראה שיש הקלה והרווחה, הוא שוב הכביד את לבו וסירב להקשיב להם, בדיוק כפי שה' צפה מראש.",
  "8_12": "ה' אמר למשה: 'אמור לאהרן: הושט את מקלך והכה בעפר הארץ, והוא יהפוך לכינים בכל ארץ מצרים'.",
  "8_13": "הם עשו כך: אהרן הושיט את ידו עם מקלו והיכה בעפר הארץ, וכינים פשטו על בני האדם ועל בעלי החיים; כל עפר הארץ הפך לכינים בכל מצרים.",
  "8_14": "החרטומים ניסו גם הם לייצר כינים בעזרת כשפיהם, אך לא הצליחו; והכינים המשיכו להציק לבני האדם ולבעלי החיים.",
  "8_15": "אז אמרו החרטומים לפרעה: 'זוהי התערבות אלוהית ישירה (אצבע אלוהים)!'; אך לבו של פרעה נותר קשה ועקשן והוא לא הקשיב להם, כפי שה' אמר.",
  "8_16": "ה' אמר למשה: 'השכם בבוקר והתייצב מול פרעה כשהוא יוצא אל המים, ואמור לו: כה אמר ה': שלח את עמי כדי שיעבדו אותי'.",
  "8_17": "'כי אם לא תשלח את עמי, הנה אני משלח בך, ביועציך, בעמך ובבתיך להקות ענקיות של חיות טרף ומזיקים (ערוב); בתי מצרים והאדמה שעליה הם עומדים יתמלאו בהם'.",
  "8_18": "'אך באותו יום אני אבדיל ואפלה לטובה את חבל גושן שבו יושב עמי, כך שלא תהיה שם שום חיית טרף, כדי שתדע שאני ה' הפועל ושולט בתוך הארץ'.",
  "8_19": "'אשים הבדלה ברורה בין עמי לבין עמך; מחר יתרחש האות הזה'.",
  "8_20": "ה' עשה כך: נחילי מזיקים וחיות טרף כבדים פשטו על ארמון פרעה, על בתי שריו ועל כל ארץ מצרים, והארץ כולה הושחתה ונהרסה מפניהם.",
  "8_21": "פרעה קרא למשה ולאהרן ואמר: 'לכו והקריבו קרבנות לאלוהיכם כאן בתוך גבולות הארץ'.",
  "8_22": "אך משה ענה: 'לא ראוי לעשות כך, כי אנו נקריב לה' את בעלי החיים שהמצרים מחשיבים כקדושים (הטלה); אם נקריב את אלילי מצרים לעיניהם, הם יסקלו אותנו באבנים!'.",
  "8_23": "'עלינו ללכת מרחק של שלושה ימי הליכה אל תוך המדבר, ולהקריב לה' אלוהינו כפי שיצווה עלינו'.",
  "8_24": "פרעה אמר: 'אני אאפשר לכם לצאת ולהקריב קרבנות לה' אלוהיכם במדבר, בתנאי שלא תתרחקו יותר מדי; התפללו עכשיו עבורי!'.",
  "8_25": "משה השיב: 'הנה אני יוצא מכאן ומתפלל אל ה', ומחר ייעלם הערוב מפרעה, משריו ומעמו; רק שפרעה לא יחזור לרמות ולא ימנע שוב מן העם לצאת ולהקריב לה''.'",
  "8_26": "משה יצא מלפני פרעה והתפלל אל ה'.",
  "8_27": "ה' נענה לתפילת משה והסיר את הערוב מפרעה, משריו ומעמו; לא נותר אפילו מזיק אחד.",
  "8_28": "אך פרעה הכביד את לבו גם הפעם הזו, ושוב סירב לשלח את העם.",
  "9_1": "ה' אמר למשה: 'בוא אל פרעה ואמור לו: כה אמר ה' אלוהי העברים: שלח את עמי כדי שיעבדו אותי'.",
  "9_2": "'כי אם אתה עדיין מסרב לשלח אותם וממשיך להחזיק בהם בכוח',",
  "9_3": "'הנה ידו של ה' תפגע בכל העדרים שלך שבשדה – בסוסים, בחמורים, בגמלים, בבקר ובצאן – במגפת דבר קשה וקטלנית'.",
  "9_4": "'וה' יבדיל בבירור בין מקנה ישראל לבין מקנה מצרים, ושום בעל חיים השייך לבני ישראל לא ימות'.",
  "9_5": "ה' קבע מועד מדויק ואמר: 'מחר יעשה ה' את המעשה הזה בארץ'.",
  "9_6": "למחרת ה' עשה זאת: כל מקנה המצרים שבשדות מת במגפה, אך מכל עדרי בני ישראל לא מת אפילו בעל חיים אחד.",
  "9_7": "פרעה שלח שליחים לבדוק, והתברר שאכן מכל מקנה ישראל לא מת אפילו אחד; אך לבו של פרעה נותר אטום והוא לא שילח את העם.",
  "9_8": "ה' אמר למשה ולאהרן: 'קחו מלא חופניים פיח מכבשן האש, ומשה יזרוק אותו כלפי מעלה אל השמיים לעיני פרעה'.",
  "9_9": "'הפיח יתפזר כאבק דק על כל ארץ מצרים, ויגרום לפצעים מוגלתיים כואבים (שחין ואבעבועות) לפרוץ על גופם של בני האדם ובעלי החיים בכל רחבי מצרים'.",
  "9_10": "הם לקחו פיח כבשן ועמדו לפני פרעה, ומשה זרק אותו כלפי השמיים; מיד התפרצו פצעי שחין ואבעבועות קשים על בני האדם ועל בעלי החיים.",
  "9_11": "החרטומים אפילו לא היו מסוגלים לעמוד לפני משה בגלל השחין הכואב, כי הפצעים פגעו בחרטומים ובכל המצרים כאחד.",
  "9_12": "אך ה' חיזק את עקשנות לבו של פרעה והוא לא הקשיב להם, בדיוק כפי שה' אמר למשה מראש.",
  "9_13": "ה' אמר למשה: 'השכם בבוקר, התייצב לפני פרעה ואמור לו: כה אמר ה' אלוהי העברים: שלח את עמי כדי שיעבדו אותי'.",
  "9_14": "'כי הפעם אני עומד להנחית את כל המכות שלי ישירות אל לבך, על שריך ועל עמך, כדי שתבין שאין כמוני בכל העולם'.",
  "9_15": "'הרי כבר עכשיו יכולתי לשלוח את ידי ולהכות אותך ואת עמך במגפת דבר שתמחק אתכם מן העולם'.",
  "9_16": "'אך השארתי אותך בחיים בדיוק בשביל המטרה הזו: כדי להראות לך את כוחי העצום, וכדי ששמי יתפרסם בכל רחבי כדור הארץ'.",
  "9_17": "'האם אתה עדיין מתנשא על עמי וממשיך לסרב לשלח אותם?!'.",
  "9_18": "'הנה מחר בשעה הזו אמטיר ברד כבד ביותר, שכמוהו לא נראה מעולם במצרים מיום הקמתה ועד עכשיו'.",
  "9_19": "'לכן עכשיו שלח הוראה לאסוף מהר את כל מקנך ואת כל מה שיש לך בשדה; כל אדם ובעל חיים שיימצא בחוץ ולא יוכנס לתוך בית – ייפגע מהברד וימות!'.",
  "9_20": "מי מבין שרי ועבדי פרעה שחשש מדבר ה', מיהר להכניס את משרתיו ואת עדריו אל תוך הבתים.",
  "9_21": "אך מי שלא ייחס חשיבות לדבר ה', השאיר את משרתיו ואת עדריו בחוץ בשדה.",
  "9_22": "ה' אמר למשה: 'הושט את ידך כלפי השמיים, וברד כבד יירד על כל ארץ מצרים – על בני אדם, על בעלי חיים ועל כל הצמחייה שבשדות מצרים'.",
  "9_23": "משה הרים את מקלו כלפי השמיים, וה' המטיר רעמים אדירים וברד כבד, ואש התרוצצה ונחתה על הקרקע; ה' המטיר ברד על ארץ מצרים.",
  "9_24": "זה היה מופע מדהים של ברד ואש בוערת בתוך גושי הברד, כבד ביותר, שכמוהו לא היה מעולם בכל ארץ מצרים מאז שהפכה לאומה.",
  "9_25": "הברד פגע בכל מה שהיה בשדות בכל רחבי מצרים, מאדם ועד בהמה; הוא ריסק את כל עשבי השדה ושבר את כל עצי היער.",
  "9_26": "רק בחבל גושן, מקום מגוריהם של בני ישראל – לא נפל ברד כלל.",
  "9_27": "פרעה מיהר לקרוא למשה ולאהרן והודה בפניהם: 'הפעם חטאתי! ה' הוא הצודק, ואני ועמי אשמים ורשעים!'.",
  "9_28": "'התפללו אל ה' שיפסיק את קולות הרעמים הנוראים ואת הברד; אני אשלח אתכם מיד ולא תצטרכו להישאר כאן עוד'.",
  "9_29": "משה השיב לו: 'ברגע שאצא מהעיר אפרוש את כפיי בתפילה אל ה'; הרעמים יפסיקו והברד ייפסק לחלוטין, כדי שתדע שהעולם כולו שייך לה''.'",
  "9_30": "'אבל אני יודע היטב שאתה ושריך עדיין אינכם יראים באמת מפני ה' אלוהים, ושוב תפרו את הבטחתכם'.",
  "9_31": "יבולי הפשתה והשעורה הושמדו כליל, מכיוון שהשעורה כבר הבשילה לגבעולים והפשתה פרחה.",
  "9_32": "אך החיטה והכוסמת לא ניזוקו, כי הן מאחרות לצמוח והיו עדיין רכות ומוגנות.",
  "9_33": "משה יצא מן העיר מלפני פרעה, פרש את כפיו בתפילה אל ה', וקולות הרעמים והברד נפסקו מיד, ואף גשם לא נחת עוד על האדמה.",
  "9_34": "אך כאשר פרעה ראה שהגשם, הברד והרעמים נפסקו, הוא המשיך לחטוא ושוב הכביד והקשה את לבו, הוא ושריו.",
  "9_35": "לבו של פרעה נשאר קשה ואטום והוא לא שילח את בני ישראל, בדיוק כפי שה' אמר מראש דרך משה.",
  "10_1": "ה' אמר למשה: 'בוא אל פרעה, כי אני הקשיתי את לבו ואת לב שריו כדי שאוכל להציג את האותות והמופתים האלה בקרבו'.",
  "10_2": "'וגם כדי שתוכל לספר לילדיך ולנכדיך כיצד התמודדתי בתקיפות עם המצרים ואילו מופתים עשיתי בקרבם, וכך תדעו כולכם שאני ה''.'",
  "10_3": "משה ואהרן באו אל פרעה ואמרו לו: 'כה אמר ה' אלוהי העברים: עד מתי תסרב להיכנע בפניי? שלח את עמי כדי שיעבדו אותי'.",
  "10_4": "'כי אם תמשיך לסרב לשלח את עמי – הנה מחר אביא נחילי ארבה עצומים אל תוך גבולות ארצך'.",
  "10_5": "'הארבה יכסה לחלוטין את מראה האדמה, עד שלא ניתן יהיה לראות את הקרקע כלל; הוא יאכל את כל מה ששרד ונשאר אצלכם אחרי מכת הברד, ויכרסם כל עץ שצומח בשדותיכם'.",
  "10_6": "'בתיך, בתי כל שריך ובתי כל תושבי מצרים יתמלאו בארבה, בהיקף כזה שאבותיך ואבות אבותיך לא ראו מעולם מאז שהם חיים על פני האדמה ועד היום הזה'; משה סיים את דבריו, הסתובב ויצא מלפני פרעה.",
  "10_7": "שרי פרעה פנו אליו בדאגה ואמרו: 'עד מתי האיש הזה יהיה לנו למלכודת ולאסון? שלח כבר את האנשים כדי שיעבדו את ה' אלוהיהם! האם עדיין אינך קולט שמצרים כולה נחרבת?!'.",
  "10_8": "משה ואהרן הוחזרו אל פרעה, והוא אמר להם: 'לכו ועבדו את ה' אלוהיכם; אבל מי בדיוק הם האנשים שיוצאים לדרך?'.",
  "10_9": "משה השיב: 'אנחנו נלך כולנו יחד – עם ילדינו ועם זקנינו, עם בנינו ובנותינו, וגם עם הצאן והבקר שלנו, כי זהו חג לה' עבור כולנו'.",
  "10_10": "פרעה אמר להם בזעם ובלעג: 'שה' יעזור לכם אם אאפשר לכם לקחת את הילדים הקטנים שלכם! ראו הוזהרתם, כוונותיכם רעות ומסוכנות!'.",
  "10_11": "'לא אסכים לכך! רק הגברים הבוגרים ילכו לעבוד את ה', שהרי זה מה שביקשתם בתחילה!'; ומיד גירשו אותם מנוכחותו של פרעה.",
  "10_12": "ה' אמר למשה: 'הושט את ידך מעל ארץ מצרים והבא את הארבה; הוא יעלה על כל הארץ ויאכל את כל העשב והצמחייה שהשאיר אחריו הברד'.",
  "10_13": "משה הרים את מקלו מעל ארץ מצרים, וה' ניהג רוח מזרחית חזקה שנשבה בארץ במשך כל אותו היום וכל אותו הלילה; כשהגיע הבוקר, הרוח המזרחית נשאה איתה את נחילי הארבה.",
  "10_14": "הארבה עלה על כל ארץ מצרים ונחת בכל גבולותיה במספרים עצומים וכבדים ביותר; מעולם לא היה נחיל ארבה כזה לפני כן, וגם לעולם לא יהיה עוד כמוהו.",
  "10_15": "הוא כיסה לחלוטין את פני כל האדמה עד שהשמים והארץ החשיכו, כרסם את כל עשב השדה ואת כל פירות העצים שהותיר הברד; שום צבע ירוק לא נשאר על העצים או בצמחי השדה בכל רחבי מצרים.",
  "10_16": "פרעה מיהר להזעיק אליו את משה ואת אהרן ואמר להם בבהלה: 'חטאתי לה' אלוהיכם וגם לכם'.",
  "10_17": "'ועכשיו, סלחו בבקשה לחטאי רק עוד הפעם הזו, והתפללו אל ה' אלוהיכם שיסיר מעליי לפחות את אסון המוות וההרס הנורא הזה'.",
  "10_18": "משה יצא מנוכחותו של פרעה והתפלל אל ה'.",
  "10_19": "ה' שינה את כיוון הרוח לרוח מערבית חזקה במיוחד, שנשאה את כל הארבה והשליכה אותו אל תוך ים סוף; לא נותר אפילו חגב ארבה אחד בכל גבולות מצרים.",
  "10_20": "אך ה' חיזק את עקשנותו של פרעה, והוא שוב סירב לשלח את בני ישראל.",
  "10_21": "ה' אמר למשה: 'הושט את ידך כלפי השמיים, וחושך סמיך וכבד יירד על כל ארץ מצרים – חושך כה מוחשי עד שניתן יהיה למשש אותו בידיים'.",
  "10_22": "משה הושיט את ידו כלפי השמיים, וחושך ואפלה מוחלטים שררו בכל ארץ מצרים במשך שלושה ימים.",
  "10_23": "אנשים לא יכלו לראות איש את אחיו, ואף אדם לא היה מסוגל לקום ממקומו במשך שלושה ימים; אך בכל מקומות המגורים של בני ישראל היה אור רגיל ובהיר.",
  "10_24": "פרעה קרא למשה ואמר: 'לכו ועבדו את ה', וגם הילדים שלכם יכולים להצטרף אליכם; רק הצאן והבקר שלכם יישארו כאן כערבון'.",
  "10_25": "משה השיב לו: 'לא רק זאת, אלא שאתה בעצמך תיתן לנו בהמות לזבחים ולעולות כדי שנקריב לה' אלוהינו'.",
  "10_26": "'וגם כל העדרים שלנו ילכו איתנו, לא תישאר כאן אפילו פרסה אחת, כי מהם ניקח כדי לעבוד את ה' אלוהינו; ואנו לא נדע מראש מה נצטרך להקריב עד שנגיע לשם'.",
  "10_27": "ה' חיזק את לבו העקשן של פרעה, והוא סירב בתוקף לאפשר להם ללכת.",
  "10_28": "פרעה צעק על משה בזעם: 'הסתלק מכאן! היזהר והישמר לך, אל תעז להופיע שוב לפניי, כי ביום שבו תראה את פניי תוצא להורג!'.",
  "10_29": "משה ענה בקור רוח: 'אמרת נכון; לא אבוא עוד לראות את פניך'.",
  "11_1": "ה' אמר למשה בעודו עומד בארמון: 'עוד מכה אחת ואחרונה אביא על פרעה ועל מצרים, ואחריה הוא ישלח אתכם מכאן; וכאשר ישלח, הוא לא רק ירשה לכם ללכת – אלא יגרש אתכם בחיפזון לחלוטין'.",
  "11_2": "'אמור עכשיו לבני העם, שכל גבר יבקש מחברו המצרי וכל אישה משכנתה המצרית תכשיטים וכלי כסף וכלי זהב'.",
  "11_3": "ה' גרם לכך שהמצרים ירגישו אהדה והערכה רבה כלפי עם ישראל; וגם משה בעצמו נחשב לאישיות מכובדת ודגולה ביותר בעיני שרי פרעה ובעיני כל העם המצרי.",
  "11_4": "משה אמר לפרעה: 'כה אמר ה': בדיוק בחצות הלילה אעבור בכל רחבי מצרים'.",
  "11_5": "'וכל בן בכור בארץ מצרים ימות – החל מבכורו של פרעה שיושב על כס המלוכה, דרך בכורה של השפחה הטוחנת בריחיים, ועד לכל בכור של בעלי החיים'.",
  "11_6": "'וזעקת שבר וכאב גדולה תפרוץ בכל ארץ מצרים, שכמוה לא נשמעה מעולם וכמוה לא תהיה שוב'.",
  "11_7": "'אבל אצל בני ישראל – אפילו כלב לא ינבח ולא יחרוץ לשונו כנגד שום אדם או בהמה, כדי שתבינו בבירור שה' מבדיל לחלוטין בין מצרים לבין ישראל'.",
  "11_8": "'וכל השרים והיועצים האלה שלך ירדו על ברכיהם לפניי, ישתחוו לי ויתחננו: צא מכאן מיד אתה וכל העם שהולך אחריך! ורק אז אצא!'; ומשה יצא מנוכחותו של פרעה בכעס מוצדק.",
  "11_9": "ה' אמר למשה: 'פרעה לא יקשיב לכם, וכך יתרבו המופתים והנפלאות שלי בארץ מצרים'.",
  "11_10": "משה ואהרן עשו את כל המופתים האלה לעיני פרעה, אך ה' חיזק את עקשנותו של פרעה והוא לא שילח את בני ישראל מארצו.",
  "12_1": "ה' דיבר אל משה ואל אהרן עוד בארץ מצרים ואמר להם:",
  "12_2": "'החודש הזה (חודש ניסן, חודש האביב) יהיה עבורכם הראשון בחודשים; הוא יהיה החודש הפותח את חודשי השנה'.",
  "12_3": "'דברו אל כל קהילת ישראל ואמרו: בעשירי לחודש הזה, ייקח כל בית אב שה אחד למשפחתו'.",
  "12_4": "'ואם המשפחה קטנה מכדי לאכול שה שלם, יצטרף בעל הבית עם שכנו הקרוב לפי מספר הנפשות, כך שכל אדם יחשב לפי יכולת האכילה שלו'.",
  "12_5": "'השה חייב להיות מושלם ללא שום מום גופני, זכר בן שנתו הראשונה; תוכלו לבחור אותו מבין הכבשים או מבין העיזים'.",
  "12_6": "'עליכם לשמור ולבדוק אותו עד היום הארבעה-עשר בחודש זה, ובשעות אחר הצהריים לקראת ערב ישחטו אותו כל קהל עדת ישראל'.",
  "12_7": "'הם ייקחו מן הדם וימרחו אותו על שתי המזוזות ועל המשקוף של פתחי הבתים שבהם יאכלו אותו'.",
  "12_8": "'באותו לילה יאכלו את הבשר כשהוא צלוי באש, ויאכלו אותו יחד עם מצות ועשבי מרור'.",
  "12_9": "'אל תאכלו ממנו כשהוא נא (אינו צלוי היטב) או מבושל במים, אלא אך ורק צלוי באש בשלמותו – ראשו יחד עם כרעיו ואיבריו הפנימיים'.",
  "12_10": "'אל תשאירו שום חלק ממנו לבוקר; ואם יישאר ממנו משהו עד הבוקר – שרפו אותו באש'.",
  "12_11": "'וכך עליכם לאכול אותו: כשחגורתכם חגורה סביב מותניכם, נעליכם לרגליכם ומקל ההליכה שלכם בידכם; תאכלו אותו במהירות ובדריכות לקראת יציאה, כי זהו קרבן פסח לה''.'",
  "12_12": "'באותו לילה אעבור בארץ מצרים ואכה כל בכור בארץ, מאדם ועד בהמה; ובכל אלילי מצרים אעשה משפט ודין, אני ה''.'",
  "12_13": "'הדם על המשקופים יהיה עבורכם לסימן מגן על הבתים שבהם אתם נמצאים; אראה את הדם ואפסח (אדלג ברחמים) מעל בתיכם, ושום מגפה משמידה לא תפגע בכם כאשר אכה את ארץ מצרים'.",
  "12_14": "'היום הזה יהיה עבורכם ליום זיכרון, ותחגגו אותו כחג לה' לכל הדורות; זו תהיה חוקה נצחית שתשמרו תמיד'.",
  "12_15": "'במשך שבעה ימים תאכלו אך ורק מצות; כבר ביום הראשון תשביתו ותבערו את השאור מבתיכם, כי כל מי שיאכל חמץ מהיום הראשון ועד היום השביעי – ייכרת וייפרד מעם ישראל'.",
  "12_16": "'ביום הראשון וביום השביעי תערכו כינוס קדוש וחגיגי; שום מלאכת עבודה לא תיעשה בהם, מלבד הכנת אוכל הנחוץ לכל אדם – רק זאת מותר לכם לעשות'.",
  "12_17": "'שמרו על מצוות המצות ועל הכנתן בקפידה, כי בדיוק ביום הזה הוצאתי את כל מחנותיכם מארץ מצרים; לכן שמרו את היום הזה כחוק עולם לכל הדורות'.",
  "12_18": "'בחודש הראשון, מהערב של היום הארבעה-עשר בחודש ועד הערב של היום העשרים ואחד – תאכלו מצות בלבד'.",
  "12_19": "'במשך שבעת הימים האלה אסור שיימצא שום שאור או חמץ בבתיכם; כל מי שיאכל דבר שהחמיץ ייכרת מקהילת ישראל, בין אם הוא גר שהצטרף לעם ובין אם הוא אזרח שנולד בארץ'.",
  "12_20": "'שום דבר מחומץ לא תאכלו; בכל מקומות מגוריכם תאכלו רק מצות'.",
  "12_21": "משה כינס את כל זקני ישראל ואמר להם: 'משכו וקחו לכם צאן לפי משפחותיכם, ושחטו את שה הפסח'.",
  "12_22": "'קחו אגודה של ענפי אזוב, טבלו אותה בדם שבכלי, ומרחו מהדם על המשקוף ועל שתי המזוזות; ואף אחד מכם אל ייצא מפתח ביתו עד הבוקר'.",
  "12_23": "'כי ה' יעבור כדי להכות את מצרים, וכשיראה את הדם על המשקוף ועל שתי המזוזות, הוא יפסח על הפתח ולא ייתן למשחית להיכנס לתוך בתיכם להכות בכם'.",
  "12_24": "'שמרו את המנהג והמצווה הזו כחוק קבוע עבורכם ועבור בניכם לתמיד'.",
  "12_25": "'וכאשר תגיעו אל הארץ שה' ייתן לכם כפי שהבטיח, הקפידו להמשיך לקיים את הטקס והעבודה הזו'.",
  "12_26": "'וכאשר ילדיכם ישאלו אתכם בעתיד: מה המשמעות של הטקס הזה עבורכם?'",
  "12_27": "'תענו להם: זהו זבח פסח לה', אשר פסח ודילג מעל בתי בני ישראל במצרים כאשר הכה את המצרים, ואת בתינו הציל והותיר בחיים!'; והעם הרכין ראש והשתחווה בהתרגשות ובהודיה.",
  "12_28": "בני ישראל הלכו וביצעו את הכל במדויק; כפי שה' ציווה את משה ואת אהרן – כך הם עשו.",
  "12_29": "בחצות הלילה הכה ה' כל בן בכור בארץ מצרים – החל מבכורו של פרעה היושב על כסאו, ועד לבכורו של האסיר היושב בבית הכלא, וכן כל בכור בקרב בעלי החיים.",
  "12_30": "פרעה התעורר באמצע הלילה, הוא וכל שריו וכל תושבי מצרים, וצעקת שבר מחרישת אוזניים קמה במצרים – כי לא היה אף בית שלא היה בו מת.",
  "12_31": "פרעה קרא למשה ולאהרן עוד באותו הלילה וקרא: 'קומו וצאו מיד מתוך עמי, גם אתם וגם כל בני ישראל! לכו ועבדו את ה' כפי שביקשתם!'.",
  "12_32": "'קחו איתכם גם את צאנכם וגם את בקרכם כפי שאמרתם ולכו, והתפללו שגם עליי תבוא ברכה ולא מכה!'.",
  "12_33": "והמצרים לחצו על העם ודחקו בהם למהר ולעזוב את הארץ, כי אמרו בפחד: 'כולנו עומדים למות!'.",
  "12_34": "בני העם נשאו את בצקם על שכמם עוד לפני שהספיק לתפוח ולהחמיץ, כשקערות הבצק שלהם צרורות בבגדיהם על כתפיהם.",
  "12_35": "ובני ישראל פעלו על פי הנחיית משה: הם ביקשו מן השכנים המצריים כלי כסף, תכשיטי זהב ובגדים יקרים.",
  "12_36": "וה' גרם למצרים לחבב את העם ולהיענות ברצון לבקשתם, והם נתנו להם רכוש רב; כך יצאו בני ישראל עם פיצוי ושכר על עבודתם.",
  "12_37": "בני ישראל יצאו למסעם מרעמסס לכיוון סוכות; הם מנו כ-600,000 גברים בוגרים שהלכו ברגל, מלבד הילדים והנשים.",
  "12_38": "וגם קבוצה גדולה של אנשים מעמים שונים (ערב רב) הצטרפה אליהם, יחד עם עדרים גדולים מאוד של צאן ובקר.",
  "12_39": "הם אפו את הבצק שהוציאו איתם ממצרים ועשו ממנו עוגות מצות שטוחות כי הוא לא הספיק להחמיץ, מכיוון שגורשו ממצרים בחיפזון ולא יכלו להתמהמה, וגם לא הספיקו להכין לעצמם צידה אחרת לדרך.",
  "12_40": "תקופת הישיבה של בני ישראל והאבות מיום הברית ועד היציאה ממצרים מנתה 430 שנה.",
  "12_41": "בדיוק בתום 430 השנים האלו, באותו יום ממש, יצאו כל מחנות ה' מארץ מצרים.",
  "12_42": "זהו לילה שבו ה' שמר והשגיח עליהם כדי להוציאם ממצרים; לכן הלילה הזה מוקדש לה' כליל שימורים וזיכרון לכל בני ישראל לאורך כל דורותיהם.",
  "12_43": "ה' אמר למשה ולאהרן: 'אלה הם דיני קרבן הפסח: שום אדם נכרי ועובד אלילים לא יאכל ממנו'.",
  "12_44": "'אבל כל עבד שנרכש בכסף ומל את עורלתו – רשאי לאכול ממנו'.",
  "12_45": "'תושב זר ושכיר יום נכרי לא יאכלו ממנו'.",
  "12_46": "'הקרבן ייאכל בתוך בית אחד; אסור להוציא מן הבשר אל מחוץ לבית, ואסור לשבור בו שום עצם'.",
  "12_47": "'כל קהילת ישראל מחויבת להשתתף ולקיים את הפסח'.",
  "12_48": "'ואם גר ירצה להצטרף אליכם ולחגוג את הפסח לה', עליו למול קודם את כל הגברים שבביתו; רק אז יוכל לגשת ולעשותו וייחשב כאזרח מלידה, אך שום אדם ערל לא יאכל ממנו'.",
  "12_49": "'חוק ותורה אחת יהיו לאזרח שנולד בעם ולגר שמתגורר בתוככם'.",
  "12_50": "כל בני ישראל עשו בדיוק כפי שה' ציווה את משה ואת אהרן; כך עשו.",
  "12_51": "ובדיוק באותו יום הוציא ה' את בני ישראל מארץ מצרים לפי מחנותיהם וצבאותיהם.",
  "13_1": "ה' דיבר אל משה ואמר:",
  "13_2": "'הקדש עבורי כל בכור הפותח רחם בקרב בני ישראל – הן בבני אדם והן בבעלי חיים; כולם שייכים לי'.",
  "13_3": "משה אמר לעם: 'זכרו תמיד את היום הזה שבו יצאתם ממצרים מבית עבדים, כי בכוח עצום וביד חזקה הוציא אתכם ה' משם; לכן אסור לאכול חמץ'.",
  "13_4": "'היום הזה אתם יוצאים לחופשי, בחודש האביב'.",
  "13_5": "'וכאשר ה' יביא אותך אל ארץ הכנעני, החיתי, האמורי, החיווי והיבוסי שנשבע לאבותיך לתת לך – ארץ שופעת חלב ודבש – עליך לקיים את הטקס הזה בחודש זה'.",
  "13_6": "'שבעה ימים תאכל מצות, וביום השביעי יהיה חג לה''.'",
  "13_7": "'רק מצות ייאכלו במשך שבעת הימים האלה; שום חמץ או שאור לא ייראו ברשותך בכל רחבי ארצך'.",
  "13_8": "'וספר לילדך באותו יום: בגלל המצוות האלה (כמו אכילת מצה ופסח) עשה ה' נפלאות למעני כשיצאתי ממצרים'.",
  "13_9": "'והדבר יהיה עבורך כמו אות זיכרון על זרוע ידך וכסימן בין עיניך, כדי שתורת ה' תהיה שגורה בפיך, שהרי ביד חזקה הוציא אותך ה' ממצרים'.",
  "13_10": "'ושמור את החוק והמצווה הזו במועדה הקבוע משנה לשנה'.",
  "13_11": "'וכאשר ה' יביא אותך אל ארץ כנען כפי שנשבע לך ולאבותיך, וייתן אותה לרשותך',",
  "13_12": "'תקדיש לה' כל בכור שנולד ראשון; וכל ולד בכור זכר שנולד מבין בעלי החיים שלך – שייך לה''.'",
  "13_13": "'כל חמור בכור תפדה בעזרת שה שתקריב במקומו, ואם אינך פודה אותו – ערוף את מפרקתו; וכל בן אדם בכור מבין בניך – תפדה אותו בכסף'.",
  "13_14": "'וכאשר בנך ישאל אותך בעתיד: מה פשר המנהג הזה?, תענה לו: ביד חזקה הוציא אותנו ה' ממצרים מבית עבדים'.",
  "13_15": "'וכאשר פרעה התעקש וסירב לשלח אותנו, ה' המית כל בכור בארץ מצרים, מבכור אדם ועד בכור בהמה; לכן אני זובח לה' כל ולד זכר בכור של בהמה טהורה, ואת כל בכורי בניי אני פודה'.",
  "13_16": "'והדבר יהיה כסימן ואות על זרועך (תפילין של יד) וכזיכרון בין עיניך (תפילין של ראש), כי ביד חזקה ובעוצמה רבה הוציא אותנו ה' ממצרים'.",
  "13_17": "כאשר פרעה שילח את העם, אלוהים לא הוביל אותם דרך ארץ פלשתים למרות שהיא הייתה הדרך הקצרה והקרובה ביותר; כי אלוהים אמר: 'העם עלול להתחרט ולהיבהל אם יראה מלחמה מול הפלשתים, ויחזור למצרים'.",
  "13_18": "לכן סובב אלוהים את העם והוליך אותם דרך המדבר לכיוון ים סוף; ובני ישראל עלו ממצרים כשהם מאורגנים ומצוידים כהלכה.",
  "13_19": "משה לקח איתו את עצמות יוסף, מכיוון שיוסף השביע נמרצות את בני ישראל ואמר להם: 'אלוהים בוודאי יזכור אתכם ויגאל אתכם, וכשתצאו – העלו את עצמותיי מכאן איתכם'.",
  "13_20": "בני ישראל נסעו מסוכות, וחנו באיתם שבקצה המדבר.",
  "13_21": "וה' צעד לפניהם: ביום הוא הנחה אותם בעמוד ענן שהראה להם את הדרך, ובלילה הוא האיר להם בעמוד אש, כך שיכלו ללכת בביטחון ביום ובלילה.",
  "13_22": "עמוד הענן ביום ועמוד האש בלילה לא משו ולא עזבו את העם אף פעם.",
  "14_1": "ה' אמר למשה:",
  "14_2": "'הורה לבני ישראל לחזור על עקבותיהם ולחנות מול פי החירות, בין מגדול לבין הים, ממול לבעל צפון; חנו שם ממש על שפת הים'.",
  "14_3": "'כך פרעה יחשוב על בני ישראל: הם מבולבלים ותועים בארץ, המדבר סגר עליהם ואין להם לאן לברוח'.",
  "14_4": "'אני אחזק את עקשנות לבו של פרעה והוא ירדוף אחריהם; אז אפגין את כבודי וכוחי בניצחון על פרעה ועל כל צבאו, והמצרים ידעו שאני ה''; ובני ישראל עשו בדיוק כך.",
  "14_5": "למלך מצרים נודע שהעם ברח ולא התכוון לחזור; אז פרעה ושריו שינו לחלוטין את גישתם כלפי העם ואמרו: 'מה עשינו?! איך שחררנו את ישראל משירותנו ומעבודתנו?!'.",
  "14_6": "פרעה רתם בעצמו את מרכבת המלחמה שלו, וגייס את כל צבאו לצאת איתו.",
  "14_7": "הוא לקח שש מאות מרכבות קרב מובחרות ביותר, וכן את כל שאר המרכבות של מצרים, כשעל כולן מפקדים ולוחמים מאומנים.",
  "14_8": "ה' חיזק את לבו של פרעה מלך מצרים והוא רדף אחרי בני ישראל, בעוד בני ישראל צועדים בביטחון ובגאווה.",
  "14_9": "המצרים רדפו אחריהם והשיגו אותם כשהם חונים על שפת הים – כל סוסי מרכבות פרעה, פרשיו וכל צבאו – ליד פי החירות מול בעל צפון.",
  "14_10": "כאשר פרעה התקרב, נשאו בני ישראל את עיניהם וראו לפתע את צבא מצרים דולק אחריהם; הם נתקפו בפחד נורא, וזעקו אל ה' לעזרה.",
  "14_11": "הם פנו אל משה בייאוש ואמרו: 'האם בגלל שאין מספיק קברים במצרים לקחת אותנו למות במדבר?! מה עשית לנו כשהוצאת אותנו ממצרים?!'.",
  "14_12": "'הרי זה בדיוק מה שאמרנו לך עוד במצרים: עזוב אותנו ונמשיך לעבוד את המצרים! עדיף היה לנו להיות עבדים במצרים מאשר למות במדבר הזה!'.",
  "14_13": "משה הרגיע את העם ואמר: 'אל תפחדו! התייצבו וראו את הישועה הגדולה שה' יעשה למענכם היום; כי את המצרים שאתם רואים היום – לא תראו עוד לעולם!'.",
  "14_14": "'ה' יילחם עבורכם, ואתם פשוט תשתקו ותבטחו בו'.",
  "14_15": "ה' אמר למשה: 'למה אתה צועק אליי? הורה לבני ישראל שימשיכו לצעוד קדימה לתוך הים!'.",
  "14_16": "'ואתה הרם את מקלך, הושט את ידך מעל הים ובקע אותו לשניים; ובני ישראל ייכנסו אל תוך הים על אדמה יבשה'.",
  "14_17": "'ואני אחזק את לב המצרים והם ייכנסו אחריהם לתוך הים; אז אפגין את כבודי וכוחי בניצחון על פרעה, על כל צבאו, על מרכבותיו ועל פרשיו'.",
  "14_18": "'وהמצרים יבינו שאני ה', כאשר אנצח את פרעה, את מרכבותיו ואת פרשיו'.",
  "14_19": "מלאך האלוהים, שהלך עד כה לפני מחנה ישראל, עבר והתייצב מאחוריהם; וגם עמוד הענן זז מלפניהם והתייצב מאחוריהם כדי לחצוץ בינם לבין המצרים.",
  "14_20": "עמוד הענן עמד בין מחנה מצרים לבין מחנה ישראל; בצד המצרי הוא יצר חושך וערפל כבד, ואילו בצד הישראלי הוא האיר את הלילה, כך ששני המחנות לא התקרבו זה לזה במשך כל אותו הלילה.",
  "14_21": "משה הושיט את ידו מעל הים, וה' הניע את מי הים ברוח מזרחית עזה שנשבה במשך כל הלילה; הים הפך לאדמה חרבה והמים נבקעו.",
  "14_22": "בני ישראל נכנסו אל תוך הים על אדמה יבשה, כאשר המים עומדים כחומה מוצקה מימינם ומשמאלם.",
  "14_23": "המצרים רדפו אחריהם ונכנסו בעקבותיהם אל תוך הים – כל סוסי פרעה, מרכבותיו ופרשיו.",
  "14_24": "לפנות בוקר, באשמורת הבוקר, השקיף ה' אל מחנה מצרים מבעד לעמוד האש והענן, והטיל מהומה ואימה גדולה בתוך המחנה המצרי.",
  "14_25": "הוא פירק את גלגלי המרכבות שלהם והם נעו בכבדות ובקושי; אז צעקו המצרים בבהלה: 'בואו נברח מפני ישראל, כי ה' נלחם למענם נגד מצרים!'.",
  "14_26": "ה' אמר למשה: 'הושט את ידך מעל הים, והמים יחזרו ויציפו את המצרים, את מרכבותיהם ואת פרשיהם'.",
  "14_27": "משה הושיט את ידו מעל הים, ולפנות בוקר חזר הים לעוצמתו המקורית; המצרים שניסו לברוח נסחפו ישירות לתוך הגלים, וה' ניער והטביע את המצרים בתוך הים.",
  "14_28": "המים שחזרו כיסו את המרכבות ואת הפרשים של כל צבא פרעה שנכנסו אחריהם לים; אף לוחם מצרי אחד לא שרד.",
  "14_29": "ובני ישראל הלכו ביבשה בתוך הים, והמים עמדו עבורם כחומה מימינם ומשמאלם.",
  "14_30": "באותו יום הציל ה' את ישראל מיד מצרים, וישראל ראו את המצרים מתים על שפת הים.",
  "14_31": "ישראל ראו את הכוח והעוצמה האדירה שהפעיל ה' נגד מצרים; העם התמלא ביראה ובכבוד כלפי ה', והם האמינו בה' ובמשה עבדו.",
  "15_1": "אז שרו משה ובני ישראל את שירת ההודיה הזו לה', ואמרו: 'אשיר לה' כי הוכיח את גבורתו העליונה; סוסים ורוכביהם השליך לתוך הים'.",
  "15_2": "'ה' הוא מקור כוחי ושירתי, והוא היה לי לישועה; זהו אלי ואשבח אותו, אלוהי אבותיי וארומם את שמו'.",
  "15_3": "'ה' הוא גיבור מלחמה מנצח; ה' הוא שמו'.",
  "15_4": "'את מרכבות פרעה ואת כל צבאו הוא הטיל לים; מיטב קציניו ולוחמיו טבעו בים סוף'.",
  "15_5": "'מעמקי הים כיסו אותם; הם שקעו במצולות כמו אבן כבדה'.",
  "15_6": "'יד ימינך ה' נשגבת בעוצמתה; יד ימינך ה' מרסקת את האויב'.",
  "15_7": "'ברוב גדלותך אתה מוחץ את הקמים נגדך; זעמך משמיד אותם כמו אש האוכלת קש יבש'.",
  "15_8": "'ברוח אפך נערמו המים; הגלים הנוזלים נעמדו כחומה זקופה, ומעמקי הים קפאו והתקשו בלב ים'.",
  "15_9": "'האויב התרברב ואמר: ארדוף, אשיג, אחלק שלל, אשביע את תאוותי, אשלוף את חרבי וידי תשמיד אותם!'.",
  "15_10": "'נשפת ברוחך והים כיסה אותם; הם שקעו כעופרת במים אדירים'.",
  "15_11": "'מי כמוך בין האלים ה'? מי כמוך אדיר בקדושה, מעורר הערצה בתהילות ועושה ניסים ונפלאות?!'.",
  "15_12": "'הושטת את יד ימינך – והאדמה בלעה אותם'.",
  "15_13": "'בחסדך הובלת והדרכת את העם הזה שגאלת; הנהגת אותם בעוצמתך אל משכן קודשך'.",
  "15_14": "'העמים שמעו על כך ורעדו מפחד; חרדה גדולה אחזה בתושבי פלשת'.",
  "15_15": "'אז נבהלו מנהיגי אדום, רעדה אחזה בשליטי מואב, וכל יושבי כנען נמסו מרוב אימה'.",
  "15_16": "'פחד ואימה ייפלו עליהם; מול עוצמת זרועך הם ישתתקו ויידמו כאבן, עד שיעבור עמך ה', עד שיעבור העם שרכשת לעצמך'.",
  "15_17": "'תביא אותם ותיטע אותם בהר נחלתך – במקום שבחרת למשכנך ה', במקדש שכוננו ידיך'.",
  "15_18": "'ה' ימלוך לעולם ועד!'.",
  "15_19": "כי סוסי פרעה, מרכבותיו ופרשיו נכנסו אל תוך הים, וה' השיב עליהם את מי הים, בעוד בני ישראל צעדו על קרקע יבשה בתוך הים.",
  "15_20": "מרים הנביאה, אחות אהרן, לקחה תוף בידה, וכל הנשים יצאו בעקבותיה בתופים ובריקודים.",
  "15_21": "מרים פצחה בשירה מולן: 'שירו לה' כי הפגין גבורה עליונה; סוס ורוכבו השליך לים!'.",
  "15_22": "משה הוביל את ישראל ממסעם בים סוף והם יצאו אל מדבר שור; הם הלכו שלושה ימים במדבר ולא מצאו מקור מים.",
  "15_23": "הם הגיעו למקום שנקרא מָרָה, אך לא יכלו לשתות מהמים שבו כי הם היו מרים; לכן קראו למקום מרה.",
  "15_24": "העם התלונן נגד משה ושאל: 'מה נשתה?!'.",
  "15_25": "משה זעק אל ה', וה' הראה לו עץ מסוים; משה השליך את העץ אל המים והמים הפכו למתוקים וטובים לשתייה; שם קבע ה' לעם חוקים ומשפטים, ושם העמיד אותם במבחן.",
  "15_26": "ה' אמר: 'אם תקשיבו היטב לקול ה' אלוהיכם, תעשו את הישר בעיניו, תאזינו למצוותיו ותשמרו את כל חוקיו – אף אחת מהמחלות שהבאתי על מצרים לא אביא עליכם, כי אני ה' הרופא שלכם'.",
  "15_27": "הם הגיעו לאֵילִים, ושם מצאו שנים עשר מעיינות מים ושבעים עצי תמר; הם חנו שם ליד המים.",
  "16_1": "כל עדת בני ישראל נסעו מאילים והגיעו למדבר סין, שנמצא בין אילים לבין סיני, ביום החמישה-עשר בחודש השני (חודש אייר) לצאתם ממצרים.",
  "16_2": "כל קהילת בני ישראל התלוננה נגד משה ונגד אהרן במדבר (מכיוון שאזל מלאי המזון שהביאו ממצרים).",
  "16_3": "בני ישראל אמרו להם: 'הלוואי שהיינו מתים בידי ה' בארץ מצרים, כשישבנו ליד סירי בשר ואכלנו לחם לשובע! כי הוצאתם אותנו אל המדבר הזה כדי להמית את כל הקהל הזה ברעב!'.",
  "16_4": "ה' אמר למשה: 'הנה אני עומד להמטיר לכם לחם מן השמיים; העם ייצא וילקט בכל יום בדיוק את הכמות הנחוצה לאותו יום, כדי שאבחן האם הם שומרים את הוראותיי אם לא'.",
  "16_5": "'וביום שישי, כאשר יכינו את מה שהביאו הביתה, יתברר שהכמות כפולה מזו שליקטו בכל יום רגיל'.",
  "16_6": "משה ואהרן אמרו לכל בני ישראל: 'הערב תדעו שה' הוא זה שהוציא אתכם מארץ מצרים'.",
  "16_7": "'ובבוקר תראו את כבוד ה', לאחר ששמע את תלונותיכם נגדו; וכי מה אנחנו שתתלוננו נגדנו?!'.",
  "16_8": "משה הוסיף: 'בערב ה' ייתן לכם בשר לאכול ובבוקר לחם לשובע, כי ה' שמע את תלונותיכם שאתם מפנים כלפיו; ומה אנחנו בסך הכל? תלונותיכם אינן מכוונות נגדנו, אלא נגד ה'!'.",
  "16_9": "משה אמר לאהרן: 'אמור לכל עדת בני ישראל: התקרבו ועמדו לפני ה', כי הוא שמע את תלונותיכם'.",
  "16_10": "בזמן שאהרן דיבר אל כל עדת בני ישראל, הם הביטו לעבר המדבר, והנה כבוד ה' נראה מתוך הענן.",
  "16_11": "ה' דיבר אל משה ואמר:",
  "16_12": "'שמעתי את תלונות בני ישראל; דבר אליהם ואמור: לקראת ערב תאכלו בשר ובבוקר תשבעו מלחם, וכך תדעו שאני ה' אלוהיכם'.",
  "16_13": "בערב עלו עופות שליו רבים וכיסו את כל המחנה, ובבוקר הייתה שכבת טל סביב המחנה.",
  "16_14": "כששכבת הטל התאיידה, הנה על פני האדמה במדבר נותר חומר דק ומחוספס, עדין כמו כפור על הקרקע.",
  "16_15": "בני ישראל ראו זאת ושאלו איש את רעהו: 'מן הוא?' (כלומר: מה זה הדבר הזה?), כי לא ידעו מה זה; משה אמר להם: 'זהו הלחם שה' נתן לכם למאכל'.",
  "16_16": "'זוהי ההנחיה שה' ציווה: לקטו ממנו כל איש לפי כמות האוכל הנחוצה לו – מידת עומר אחת לכל נפש, לפי מספר האנשים שנמצאים באוהל שלכם'.",
  "16_17": "בני ישראל עשו כך; חלק מהאנשים ליקטו כמות גדולה יותר וחלק ליקטו כמות קטנה יותר.",
  "16_18": "אך כשמדדו את הכמות בכלי מידת העומר – התברר שמי שליקט הרבה לא נשאר לו עודף, ומי שליקט מעט לא היה חסר לו; כל אדם אסף בדיוק לפי כמות המזון שהיה צריך.",
  "16_19": "משה הורה להם: 'שאף אחד לא ישאיר ממנו שום חלק עד הבוקר'.",
  "16_20": "אך היו אנשים שלא הקשיבו למשה והשאירו ממנו לבוקר; המן התמלא בתולעים והסריח, ומשה כעס עליהם.",
  "16_21": "הם ליקטו את המן בכל בוקר ובוקר, כל איש לפי צרכו; וכאשר השמש התחממה, המן שנשאר בשדה נמס ונעלם.",
  "16_22": "ביום שישי הם גילו שליקטו כמות כפולה של מזון – שני עומרים לכל אדם; ראשי הקהילה באו ודיווחו על כך למשה.",
  "16_23": "משה הסביר להם: 'זה בדיוק מה שה' אמר: מחר יום מנוחה, שבת קודש לה'! את מה שאתם רוצים לאפות אפו היום, ואת מה שאתם רוצים לבשל בשלו היום; ואת כל האוכל העודף שמרו לכם עד הבוקר'.",
  "16_24": "הם הניחו את האוכל עד לבוקר כפי שציווה משה, והוא לא הסריח ולא הופיעה בו שום תולעת.",
  "16_25": "משה אמר: 'אכלו אותו היום, כי היום שבת לה'; היום לא תמצאו מן בשדה'.",
  "16_26": "'במשך שישה ימים תלקטו אותו, אך ביום השביעי שבת – ביום זה לא יהיה מן בשדה'.",
  "16_27": "למרות זאת, ביום השביעי יצאו כמה אנשים מן העם כדי ללקט, אך לא מצאו דבר.",
  "16_28": "ה' אמר למשה: 'עד מתי תסרבו לשמור את מצוותיי ואת הוראותיי?!'.",
  "16_29": "'הבינו שה' נתן לכם את יום השבת, ולכן הוא נותן לכם ביום שישי מנת לחם המספיקה ליומיים; הישארו כל אחד במקומו, ואל ייצא איש מאזור מגוריו ביום השביעי'.",
  "16_30": "אז שבת העם מכל מלאכה ביום השביעי.",
  "16_31": "עם ישראל קרא למזון הזה 'מָן'; הוא נראה כמו זרע גד לבן ועגול, וטעמו היה מתוק כמו עוגיות דבש.",
  "16_32": "משה אמר: 'זה הדבר שה' ציווה: מִלאו מידת עומר אחת של מן ושמרו אותה למשמרת לדורות הבאים, כדי שיראו את הלחם שהאכלתי אתכם במדבר כשהוצאתי אתכם מארץ מצרים'.",
  "16_33": "משה אמר לאהרן: 'קח צנצנת אחת, שים בתוכה עומר שלם של מן, והנח אותה לפני ה' למשמרת לדורות הבאים'.",
  "16_34": "אהרן עשה כפי שה' ציווה את משה, והניח את הצנצנת לפני ארון העדות לשמירה.",
  "16_35": "ובני ישראל אכלו את המן במשך ארבעים שנה עד שהגיעו לארץ מיושבת; הם אכלו את המן עד שהגיעו לגבול ארץ כנען.",
  "16_36": "ומידת העומר היא עשירית ממידת האיפה.",
  "17_1": "כל עדת בני ישראל נסעו ממדבר סין בתחנותיהם על פי הוראת ה', וחנו ברפידים; ושם לא היו מים לשתייה עבור העם.",
  "17_2": "העם בא בטענות קשות ורב עם משה ואמר: 'תנו לנו מים כדי שנשתה!'; משה ענה להם: 'למה אתם רבים איתי? למה אתם מנסים ומעמידים במבחן את סבלנותו של ה'?!'.",
  "17_3": "העם היה צמא מאוד למים והתלונן נגד משה: 'למה העלית אותנו ממצרים? האם כדי להמית אותי, את ילדיי ואת עדרי בצמא?!'.",
  "17_4": "משה זעק אל ה' בתפילה: 'מה אעשה עם העם הזה? עוד מעט והם ירגמו אותי באבנים!'.",
  "17_5": "ה' ענה למשה: 'עבור לפני העם וקח איתך כמה מזקני ישראל; וקח בידך את המקל שבו הכית את נהר הנילוס, וצעד קדימה'.",
  "17_6": "'הנה אני עומד לפניך שם על הסלע בחורב; הכה בסלע, ומים יפרצו ממנו והעם יוכל לשתות'; משה עשה כך לעיני זקני ישראל.",
  "17_7": "משה קרא למקום ההוא 'מַסָּה וּמְרִיבָה' (ניסיון וריב), בגלל הריב של בני ישראל ובגלל שהעמידו את ה' במבחן כששאלו: 'האם ה' נמצא בקרבנו או לא?!'.",
  "17_8": "אז הגיעו לוחמי עמלק ותקפו את ישראל ברפידים ללא שום התגרות מצידם.",
  "17_9": "משה אמר ליהושע: 'בחר עבורנו לוחמים וצא להילחם בעמלק; מחר אתייצב על ראש הגבעה כשמקל האלוהים בידי'.",
  "17_10": "יהושע פעל כפי שהורה לו משה ויצא להילחם בעמלק; ומשה, אהרן וחור עלו לראש הגבעה.",
  "17_11": "בכל זמן שמשה הרים את ידיו בתפילה כלפי מעלה – ישראל גברו בקרב, וכאשר הוריד את ידיו – עמלק גבר.",
  "17_12": "ידיו של משה התעייפו וכבדו; הם לקחו אבן, שמו תחתיו והוא ישב עליה, ואהרן וחור תמכו בידיו – אחד מכל צד – וכך נשארו ידיו יציבות ומכוונות בתפילה עד שקיעת השמש.",
  "17_13": "יהושע הכריע והביס את עמלק ואת צבאו בקרב חרבות.",
  "17_14": "ה' אמר למשה: 'כתוב את האירוע הזה כזיכרון בספר והשמע אותו באוזני יהושע, כי אני אמחה לחלוטין את זכר עמלק מתחת לשמיים'.",
  "17_15": "משה בנה מזבח להודיה, וקרא לו 'ה' נִסִּי' (ה' הוא הנס והדגל שלי).",
  "17_16": "הוא הכריז: 'הושבעה שבועה על כסא ה' – מלחמה תהיה לה' בעמלק מדור לדור!'.",
  "18_1": "יתרו, כהן מדין וחותנו של משה, שמע על כל הנפלאות שעשה אלוהים למשה ולישראל עמו – ועל כך שה' הוציא את ישראל ממצרים.",
  "18_2": "יתרו חותן משה לקח איתו את ציפורה, אשתו של משה (לאחר שמשה שלח אותה בחזרה לבית אביה בזמן שליחותו במצרים),",
  "18_3": "ואת שני בניה; שם האחד היה גרשום, כי משה אמר: 'הייתי תושב זר בארץ זרה',",
  "18_4": "ושם השני היה אליעזר, כי אמר: 'אלוהי אבי עזר לי והציל אותי מחרבו של פרעה'.",
  "18_5": "יתרו חותן משה, יחד עם בניו ואשתו של משה, בא אל משה למדבר שבו חנה סמוך להר האלוהים (הר סיני).",
  "18_6": "הוא שלח הודעה למשה: 'אני חותנך יתרו מגיע אליך, יחד עם אשתך ושני בניה'.",
  "18_7": "משה יצא בכבוד רב לקראת חותנו, השתחווה לפניו ונישק לו; הם דרשו איש בשלום רעהו ונכנסו יחד אל האוהל.",
  "18_8": "משה סיפר לחותנו בפירוט את כל מה שעשה ה' לפרעה ולמצרים למען ישראל, את כל התלאות והקשיים שעברו בדרך, וכיצד ה' הציל אותם מכולם.",
  "18_9": "יתרו שמח והתרגש מאוד מכל הטוב שה' עשה לישראל כשהציל אותם מיד מצרים.",
  "18_10": "יתרו אמר: 'ברוך ה' אשר הציל אתכם מידי מצרים ומידי פרעה, והציל את העם מעול השעבוד המצרי!'.",
  "18_11": "'עכשיו אני יודע בבירור שה' גדול מכל האלים האחרים, כי דווקא בדבר שבו המצרים זממו להרע לישראל – שם פגע בהם עונשם'.",
  "18_12": "יתרו חותן משה הביא קרבן עולה וזבחים לאלוהים; אהרן וכל זקני ישראל באו לאכול סעודה יחד עם חותן משה לפני האלוהים.",
  "18_13": "למחרת ישב משה לשפוט את העם וליישב סכסוכים, והעם עמד סביב משה מן הבוקר ועד הערב.",
  "18_14": "חותן משה ראה את כל הטרחה שהוא משקיע עבור העם ושאל: 'מה זה הדבר שאתה עושה לעם? מדוע אתה יושב לבדך כשופט וכל העם עומד עליך מבוקר ועד ערב?!'.",
  "18_15": "משה השיב לחותנו: 'כי העם בא אליי כדי לבקש את דבר האלוהים והדרכתו'.",
  "18_16": "'כאשר יש להם סכסוך, הם באים אליי ואני שופט בין הצדדים, ומלמד אותם את חוקי האלוהים ואת הוראותיו'.",
  "18_17": "חותן משה אמר לו: 'הדרך שבה אתה פועל אינה נכונה ואינה יעילה'.",
  "18_18": "'אתה תישחק ותתעייף לחלוטין – גם אתה וגם העם הזה שנמצא איתך; העומס כבד מדי עבורך, ולא תוכל לשאת אותו לבדך'.",
  "18_19": "'עכשיו הקשב לעצתי, ואלוהים יהיה איתך: אתה תייצג את העם מול האלוהים, ותביא את השאלות המורכבות והעקרוניות אל האלוהים'.",
  "18_20": "'אתה תלמד ותזהיר אותם על החוקים וההוראות, ותסביר להם את הדרך הנכונה שבה עליהם ללכת ואת המעשים הראויים שעליהם לעשות'.",
  "18_21": "'ומצד שני, בחר מתוך כל העם אנשים מוכשרים, יראי אלוהים, אנשי אמת ששונאים בצע ושוחד; מנה אותם למנהיגים ולשופטים – שרי אלפים, שרי מאות, שרי חמישים ושרי עשרות'.",
  "18_22": "'הם ישפטו את העם בכל זמן שגרה; כל מקרה מסובך וגדול הם יביאו אליך, ואת כל התיקים הקטנים והיומיומיים ישפטו בעצמם; כך יוקל ממך העומס והם יישאו באחריות יחד איתך'.",
  "18_23": "'אם תפעל כך ואלוהים יאשר זאת – תוכל להחזיק מעמד לאורך זמן, וגם כל העם יחזור לביתו מרוצה ובשלום'.",
  "18_24": "משה הקשיב בענווה לעצת חותנו, ועשה את כל מה שהציע.",
  "18_25": "משה בחר אנשים מוכשרים מכל ישראל, ומינה אותם לראשי העם: שרי אלפים, שרי מאות, שרי חמישים ושרי עשרות.",
  "18_26": "הם שפטו את העם בכל עת; את הבעיות הקשות הביאו לפני משה, ואת כל הדינים הקטנים חרצו בעצמם.",
  "18_27": "משה ליווה את חותנו בברכה, ויתרו חזר אל ארצו.",
  "19_1": "בחודש השלישי (חודש סיוון) לאחר יציאת בני ישראל ממצרים, בדיוק בראש החודש, הם הגיעו למדבר סיני.",
  "19_2": "הם נסעו מרפידים, הגיעו למדבר סיני וחנו שם במדבר; ישראל חנה שם מול ההר באחדות מלאה, כאיש אחד בלב אחד.",
  "19_3": "משה עלה אל הר האלוהים, וה' קרא אליו מן ההר ואמר: 'כך תאמר לבית יעקב (לנשים) ותסביר לבני ישראל (לגברים):'",
  "19_4": "'אתם ראיתם בעצמכם מה עשיתי למצרים, וכיצד נשאתי אתכם כמו על כנפי נשרים והבאתי אתכם אליי'.",
  "19_5": "'ועכשיו, אם תשמעו בקולי ותשמרו את בריתי – תהיו עבורי אוצר יקר ואהוב מכל העמים, שהרי כל העולם כולו שייך לי'.",
  "19_6": "'ואתם תהיו לי ממלכה של משרתי קודש ועם קדוש ומיוחד; אלה הדברים שעליך למסור לבני ישראל'.",
  "19_7": "משה ירד, קרא לזקני העם, והציג לפניהם את כל הדברים האלה שה' ציווה עליו.",
  "19_8": "כל העם ענה יחד בקול אחד ואמר: 'את כל מה שה' אמר – נעשה!'; משה מסר את תשובת העם אל ה'.",
  "19_9": "ה' אמר למשה: 'הנה אני בא אליך בתוך ענן כבד, כדי שהעם ישמע במו אוזניו כשאדבר איתך, וכך יאמינו בך ובשליחותך לתמיד'; ומשה סיפר לה' את דברי העם.",
  "19_10": "ה' אמר למשה: 'לך אל העם והכן וקדש אותם היום ומחר; שהם יכבסו את בגדיהם ויטהרו את עצמם'.",
  "19_11": "'ויהיו מוכנים לקראת היום השלישי, כי ביום השלישי יירד ה' לעיני כל העם על הר סיני'.",
  "19_12": "'וקבע גבול מסביב להר ואמור לעם: היזהרו מאוד שלא לעלות על ההר ואפילו לא לגעת בקצהו; כל מי שייגע בהר – דינו מוות'.",
  "19_13": "'אף אדם לא ייגע בו ביד (כי ההר קדוש), אלא מי שיפר את האיסור ייסקל באבנים או ייורה בחצים מרחוק; בין אם מדובר באדם ובין אם בבהמה – לא יחיה; רק כאשר יישמע קול שופר ארוך המסמן את סיום המעמד – רק אז יהיה מותר לעלות להר'.",
  "19_14": "משה ירד מן ההר אל העם, קידש וטיהר אותם, והם כיבסו את בגדיהם.",
  "19_15": "הוא אמר לעם: 'היו מוכנים לקראת היום השלישי; הימנעו מיחסי אישות בימים אלה כדי לשמור על טהרה מלאה'.",
  "19_16": "ביום השלישי בבוקר נשמעו קולות רעמים חזקים, נראו ברקים עזים, ענן כבד כיסה את ההר, ונשמע קול שופר חזק ועוצמתי במיוחד; כל העם שבמחנה רעד מפחד ומיראה.",
  "19_17": "משה הוציא את העם מתוך המחנה לקראת המפגש עם האלוהים, והם התייצבו לרגלי ההר.",
  "19_18": "והר סיני כולו התמלא עשן כי ה' ירד עליו באש; עשנו עלה כמו עשן מכבשן לוהט, וההר כולו רעד בעוצמה רבה.",
  "19_19": "וקול השופר הלך והתחזק מאוד; משה דיבר, והאלוהים ענה לו בקול רם וברור.",
  "19_20": "ה' ירד על הר סיני אל ראש ההר; ה' קרא למשה לעלות אל ראש ההר, ומשה עלה.",
  "19_21": "ה' אמר למשה: 'רד מיד והזהר את העם, כדי שלא יפרצו את הגבול לנסות לראות את כבוד ה', ואז רבים מהם ימותו'.",
  "19_22": "'וגם הכהנים והבכירים שניגשים לשרת לפני ה' צריכים להתקדש, כדי שה' לא יפגע בהם'.",
  "19_23": "משה ענה לה': 'העם לא יכול לעלות אל הר סיני, כי אתה כבר הזהרת אותנו במפורש לקבוע גבול סביב ההר ולקדש אותו'.",
  "19_24": "ה' השיב לו: 'רד עכשיו, ואחר כך תעלה שוב אתה ואהרן איתך; אך הכהנים והעם אל יהרסו לעלות אל ה', פן יפגע בהם'.",
  "19_25": "משה ירד אל העם והזהיר אותם על כל הדברים הללו.",
  "20_1": "אלוהים השמיע את כל הדברים האלה ואמר:",
  "20_2": "'אני ה' אלוהיך, אשר הוצאתי אותך מארץ מצרים, מבית עבדים'.",
  "20_3": "'לא יהיו לך שום אלים אחרים מלבדי'.",
  "20_4": "'לא תעשה לעצמך שום פסל או תמונה של דבר שנמצא בשמיים למעלה, בארץ למטה או במים מתחת לאדמה'.",
  "20_5": "'לא תשתחווה להם ולא תעבוד אותם, כי אני ה' אלוהיך אל קנא, שאינו סובל בגידה; אני זוכר את עוון האבות גם לילדיהם עד דור שלישי ורביעי – למי שממשיכים לשנוא אותי'.",
  "20_6": "'אך אני גומל חסד ואהבה לאלפי דורות – למי שאוהבים אותי ושומרים את מצוותיי'.",
  "20_7": "'לא תישבע בשם ה' אלוהיך לשווא או לשקר, כי ה' לא ינקה מאשמה את מי שנושא את שמו לשווא'.",
  "20_8": "'זכור את יום השבת כדי לשמור על קדושתו'.",
  "20_9": "'במשך שישה ימים תעבוד ותעשה את כל מלאכתך'.",
  "20_10": "'אך היום השביעי הוא שבת מנוחה המוקדש לה' אלוהיך; לא תעשה בו שום מלאכה – לא אתה, לא בנך ובתך, לא עבדך ושפחתך, לא בהמתך, וגם לא הגר והאורח שגר ביישוביך'.",
  "20_11": "'כי בשישה ימים ברא ה' את השמיים, את הארץ, את הים ואת כל מה שיש בהם, ונח ביום השביעי; לכן בירך ה' את יום השבת וקידש אותו'.",
  "20_12": "'כבד את אביך ואת אמך, כדי שיתארכו ימי חייך על האדמה שה' אלוהיך נותן לך'.",
  "20_13": "'לא תרצח! לא תנאף! לא תגנוב (חטיפת אדם)! לא תעיד עדות שקר נגד חברך!'.",
  "20_14": "'לא תחמוד ותרצה לעצמך את ביתו של רעך; לא תחמוד את אשת רעך, את עבדו, שפחתו, שורו, חמורו או כל דבר ששייך לחברך'.",
  "20_15": "וכל העם חוו וראו את קולות הרעמים, את הלפידים, את קול השופר ואת ההר המעשן; העם ראה זאת, נחרד, נרתע לאחור ועמד מרחוק.",
  "20_16": "הם פנו אל משה ואמרו לו: 'דבר אתה איתנו ואנחנו נקשיב, אבל שאלוהים לא ידבר ישירות איתנו, כדי שלא נמות מעוצמת המעמד!'.",
  "20_17": "משה הרגיע את העם ואמר: 'אל תפחדו! אלוהים הגיע כדי לרומם ולבחון אתכם, וכדי שיראתו וכבודו יהיו מול עיניכם כך שלא תחטאו'.",
  "20_18": "העם המשיך לעמוד במרחק, ומשה ניגש לבדו אל הערפל הסמיך שבו נמצאת שכינת האלוהים.",
  "20_19": "ה' אמר למשה: 'כך תאמר לבני ישראל: אתם ראיתם בעצמכם שמן השמיים דיברתי איתכם'.",
  "20_20": "'אל תעשו לכם שום אלילים לצידי – אלילי כסף ואלילי זהב לא תעשו לעצמכם'.",
  "20_21": "'מזבח אדמה פשוט תעשה עבורי, ועליו תקריב את עולותיך ואת שלמיך, את צאנך ואת בקרך; בכל מקום שבו אזכיר את שמי אבוא אליך ואברך אותך'.",
  "20_22": "'ואם תבנה עבורי מזבח מאבנים – אל תבנה אותו מאבנים שנחצבו ומסותתו בכלי ברזל, כי אם הנפת עליו את כלי הברזל (המשמש גם לנשק) – חיללת אותו; ולא תעלה במדרגות אל מזבחי, כדי שלא ייחשף גופך בצורה לא צנועה עליו'.",
  "21_1": "אלה הם החוקים והמשפטים האזרחיים שעליך להציג לפניהם (בפני שופטים ודיינים מוסמכים):",
  "21_2": "אם תקנה עבד עברי (שנמכר בגלל גניבה או עוני קיצוני) – שש שנים הוא יעבוד, ובשנה השביעית ייצא לחופשי לחלוטין ללא שום תשלום.",
  "21_3": "אם הוא נכנס לעבדות כרווק בודד – הוא ייצא לבדו; ואם היה נשוי כבר – אשתו תשתחרר ותצא יחד איתו.",
  "21_4": "אם אדוניו נתן לו שפחה כנענית והיא ילדה לו בנים או בנות – האישה וילדיה יישארו ברשות האדון, והוא ייצא לחופשי לבדו.",
  "21_5": "אך אם העבד יצהיר במפורש: 'אני אוהב את אדוני, את אשתי ואת ילדיי, ואינני רוצה לצאת לחופשי',",
  "21_6": "אז יביא אותו אדוניו אל בית הדין, יקרב אותו אל הדלת או אל מזוזת הפתח, וינקב את תנוך אוזנו במרצע; והוא יישאר עבדו לתקופה ממושכת (עד שנת היובל).",
  "21_7": "אם אדם מוכר את בתו הקטנה לאמה – היא לא תשתחרר כמו עבדים רגילים (אלא בעלת זכויות מיוחדות להשתחרר בבגרותה או להינשא לאדון או לבנו).",
  "21_8": "אם היא אינה מוצאת חן בעיני אדוניה שייעד אותה לעצמו – עליו לאפשר למשפחתה לפדות אותה; אין לו שום זכות למכור אותה לאנשים זרים לאחר שהפר את ההבטחה כלפיה.",
  "21_9": "ואם הוא מייעד אותה לבנו – עליו לנהוג בה בכבוד ובזכויות המלאות המגיעות לכל בת ישראל.",
  "21_10": "ואם הוא ייקח לעצמו אישה נוספת – אסור לו לקפח את האישה הראשונה: את מזונותיה, את בגדיה ואת חיי הנישואין שלה לא יגרע.",
  "21_11": "ואם לא יקיים כלפיה את שלוש החובות הללו – היא תצא לחופשי מיד ללא שום תשלום כספי.",
  "21_12": "מי שמכה אדם בכוונה תחילה וגורם למותו – דינו מוות.",
  "21_13": "אך מי שלא התכוון ולא ארב לו, אלא שהדבר קרה בשגגה או בתאונה – אקבע עבורך מקום מקלט שאליו יוכל לברוח מפני גואל הדם.",
  "21_14": "אך אם אדם פעל בזדון ורצח את חברו בעורמה ובכוונה תחילה – אפילו אם יימלט אל מזבחי, עליך לקחת אותו משם כדי להוציאו להורג.",
  "21_15": "מי שמכה את אביו או את אמו ופוצע אותם – דינו מוות.",
  "21_16": "מי שחוטף אדם ומוכר אותו, או שנמצא החטוף ברשותו – דינו מוות.",
  "21_17": "מי שמקלל ומחרף את אביו או את אמו בשם ה' – דינו מוות.",
  "21_18": "אם שני אנשים רבים, ואחד מהם מכה את חברו באבן או באגרוף, והמוכה לא מת אך נפל למשכב רתוק למיטתו,",
  "21_19": "אם יקום מאוחר יותר ויוכל להתהלך בחוץ בעזרת מקל הליכה – המכה פטור מעונש מוות; אך הוא חייב לפצות אותו על ימי השבתה מעבודה, ולשלם את כל הוצאות הריפוי והטיפול הרפואי עד שיבריא לחלוטין.",
  "21_20": "אם אדם מכה את עבדו או את שפחתו במקל והם מתים מיד תחת ידו – המעשה ייענש בידי בית דין.",
  "21_21": "אך אם העבד שרד יום או יומיים לאחר המכה ורק אז מת – האדון לא ייענש במיתה, כי העבד הוא רכושו הכספי.",
  "21_22": "אם גברים רבים ביניהם ופוגעים בטעות באישה הרה וגורמים לה להפיל את עובריה, אך לא נגרם אסון מוות לאישה – הפוגע ישלם פיצוי כספי כפי שידרוש בעל האישה, בהתאם לקביעת השופטים.",
  "21_23": "אך אם נגרם אסון מוות לאישה – ייגזר עונש של חיים תחת חיים (נפש תחת נפש).",
  "21_24": "פיצוי כספי על עין תחת עין, שן תחת שן, יד תחת יד, רגל תחת רגל (לפי ערך הנזק הפיזי שנגרם);",
  "21_25": "פיצוי על כווייה תחת כווייה, פצע תחת פצע, וחבלה תחת חבלה (דמי כאב, ריפוי, נזק ושבת).",
  "21_26": "אם אדם מכה את עין עבדו או את עין שפחתו ומשחית אותה – עליו לשחרר אותו לחופשי כפיצוי על אובדן עינו.",
  "21_27": "ואם הוא מפיל את שן עבדו או שפחתו – עליו לשחרר אותו לחופשי כפיצוי על שינו.",
  "21_28": "אם שור נוגח גבר או אישה והם מתים – יש לסקול את השור באבנים ואסור לאכול מבשרו, אך בעל השור פטור מפיצוי (אם השור לא היה מועד).",
  "21_29": "אך אם השור היה רגיל לנגוח בעבר, ובעליו הוזהר על כך מראש אך לא שמר עליו כראוי, והשור המית אדם – השור ייסקל וגם בעליו ייענש בידי שמיים.",
  "21_30": "ואם יוטל עליו תשלום כופר נפש – עליו לשלם את מלוא הסכום שייקבע עליו כדי לפדות את עצמו.",
  "21_31": "אותו דין בדיוק יחול אם השור נגח ילד קטן או ילדה.",
  "21_32": "אם השור נגח עבד או שפחה – בעל השור ישלם לאדונם שלושים שקלי כסף, והשור ייסקל.",
  "21_33": "אם אדם פותח בור או חופר בור ברשות הרבים ולא מכסה אותו כראוי, ושור או חמור נופל לתוכו,",
  "21_34": "בעל הבור חייב לשלם פיצוי מלא: הוא ישיב כסף לבעל הבהמה, והנבלה המתה תישאר ברשותו.",
  "21_35": "אם שור של אדם נוגח למוות את השור של שכנו – הם ימכרו את השור החי ויחלקו ביניהם את הכסף, וגם את ערך הנבלה של השור המת יחלקו שווה בשווה (אם מדובר בשור תם).",
  "21_36": "אך אם היה ידוע שהשור נהג לנגוח בעבר ובעליו לא שמר עליו – עליו לשלם שור חי שלם במקום השור המת, והנבלה תישאר אצלו.",
  "21_37": "אם אדם גונב שור או שה, ושוחט אותו או מוכר אותו לאחרים – עליו לפצות ולשלם פי חמישה עבור השור, ופי ארבעה עבור השה.",
  "22_1": "אם פורץ נתפס בשעת פריצה מחתרתית לתוך בית והוכה למוות – הריגתו אינה נחשבת לרצח, כי הפורץ הגיע בחזקת סכנת נפשות לבעל הבית.",
  "22_2": "אך אם ברור כשמש שהפורץ לא התכוון לפגוע בנפש – הריגתו נחשבת לשפיכות דמים; הגנב חייב לשלם את כל מה שגנב, ואם אין לו כסף – הוא יימכר לעבדות כדי לכסות את הגניבה.",
  "22_3": "אם הגניבה נמצאת אצלו כשהיא עדיין חיה – בין אם מדובר בשור, חמור או שה – עליו לשלם כפל (פי שניים מערך הגניבה).",
  "22_4": "אם אדם מאפשר לבהמותיו לרעות בשדה או בכרם של אדם אחר ומזיק ליבול – עליו לפצות ממיטב שדותיו וממיטב כרמיו.",
  "22_5": "אם פורצת אש ומתפשטת לקוצים ושורפת ערימת תבואה, קמה עומדת או את השדה כולו – מי שהבעיר את האש חייב לשלם פיצוי מלא על כל הנזק.",
  "22_6": "אם אדם מוסר לחברו כסף או חפצים לשמירה בחינם, והחפץ נגנב מבית השומר – אם הגנב ייתפס, הוא ישלם כפל.",
  "22_7": "אם הגנב לא נמצא – בעל הבית השומר יתייצב בבית הדין ויישבע שלא שלח ידו ברכוש חברו.",
  "22_8": "בכל טענת מעילה וגניבה לגבי שור, חמור, שה, בגד או כל אבידה שהאחד טוען: 'זה שלי' – יבואו שני הצדדים לפני בית הדין; מי שהשופטים ירשיעו ישלם כפל לחברו.",
  "22_9": "אם אדם מוסר לחברו חמור, שור, שה או כל בהמה לשמירה בשכר, והבהמה מתה, נפצעה או נשבתה ללא עדי ראייה,",
  "22_10": "השומר יישבע שבועת אמת לפני ה' שלא לקח את רכוש חברו; בעל הבהמה יקבל את השבועה והשומר יהיה פטור מתשלום.",
  "22_11": "אך אם הבהמה נגנבה ממנו – על שומר השכר לפצות את בעליה (כי זו אחריותו).",
  "22_12": "אם הבהמה נטרפה בידי חיית פרא – השומר יביא הוכחה או שריד לנזק, ויהיה פטור מתשלום על הטרפה.",
  "22_13": "אם אדם שואל בהמה מחברו לשימוש עצמי והיא נפצעה או מתה – אם הבעלים לא נכח איתו בעת המעשה, השואל חייב לשלם פיצוי מלא.",
  "22_14": "אך אם הבעלים היה איתו יחד בעבודה – השואל פטור; ואם הבהמה נשכרה בכסף – הפיצוי נכלל בדמי השכירות.",
  "22_15": "אם גבר מפתה נערה בתולה שאינה מאורסת ושוכב איתה – עליו לשלם את דמי המוהר המקובלים ולשאת אותה לאישה.",
  "22_16": "ואם אביה מסרב בתוקף לתת לו אותה – הגבר ישלם סכום כספי השווה למוהר הבתולות (חמישים שקלי כסף).",
  "22_17": "אסור להשאיר בחיים אדם שעוסק בכישוף (איסור מוחלט על מעשי כשפים).",
  "22_18": "כל מי שמקיים יחסי מין עם בהמה – עונשו מוות.",
  "22_19": "מי שמקריב קרבן לאלים זרים יומת ויוחרם; קרבנות יש להקריב אך ורק לה' לבדו.",
  "22_20": "אל תפגע בגר ואל תנצל אותו לרעה, כי אתם בעצמכם הייתם גרים וזרים בארץ מצרים (ויודעים מהו סבלם של חסרי מעמד).",
  "22_21": "אל תנצלו ואל תענו שום אלמנה או יתום.",
  "22_22": "כי אם תפגעו בהם והם יזעקו אליי לעזרה – אשמע מיד את צעקתם ברחמים.",
  "22_23": "זעמי יבער ואעניש אתכם במלחמה קשה, עד שנשותיכם יהיו אלמנות וילדיכם יהיו יתומים.",
  "22_24": "אם תלווה כסף לאדם עני מעמך – אל תתנהג איתו כנושה קשוח שדורש בכוח, ואל תטיל עליו שום ריבית.",
  "22_25": "אם לקחת כערבון ומשכון את בגדו של חברך – החזר לו אותו לפני שקיעת השמש.",
  "22_26": "כי זהו הבגד היחיד שלו, זהו הכיסוי המגן על עורו; במה ישכב בלילה? ואם הוא יזעק אליי, אשמע לו כי אני אל חנון ורחום.",
  "22_27": "אל תקלל שופטים ודיינים, ואל תקלל מנהיג ונשיא בעמך.",
  "22_28": "אל תתעכב מלהפריש את ביכורי תבואתך ותרומת יבוליך; ואת בכור בניך תפדה ותקדיש לי.",
  "22_29": "כך תנהג גם בבכורות הבקר והצאן שלך: שבעה ימים יישאר הוולד עם אמו, וביום השמיני תוכל להקריבו לי.",
  "22_30": "היו לי אנשים קדושים; לכן אל תאכלו בשר של בעל חיים שנטרף בשדה (טרפה), אלא השליכו אותו למאכל הכלבים.",
  "23_1": "אל תקבל ואל תפיץ שמועות שווא ושקרים; ואל תשתף פעולה עם אדם רשע כדי להעיד עדות שקר.",
  "23_2": "אל תלך בעקבות הרוב אם הוא פועל לרעה, ואל תטה את עדותך במשפט רק כדי ליישר קו עם הרוב ולעוות את הדין.",
  "23_3": "וגם לאדם עני ודל אל תפגין רחמים מוטעים כדי להטות את הדין לטובתו במשפט שלא בצדק.",
  "23_4": "אם תפגוש בדרכך שור או חמור של אדם ששונא אותך כשהוא תועה – החזר אותו אליו מיד.",
  "23_5": "אם תראה את חמורו של שונאך רובץ וקורס תחת משאו הכבד, ואתה עלול להתפתות להתעלם ממנו – חובה עליך לגשת ולעזור לו לפרוק את המשא.",
  "23_6": "אל תטה ואל תעוות את משפטו של האביון בעת ריבו.",
  "23_7": "התרחק מכל דבר שקר; ואל תגרום למותו של אדם חף מפשע, כי אני לא אצדיק אדם רשע.",
  "23_8": "אל תיקח שוחד, כי השוחד מעוור את עיניהם של אנשים פיקחים ומסלף את דבריהם של צדיקים.",
  "23_9": "אל תלחץ ואל תקפח את הגר; הרי אתם מכירים היטב את תחושת נפשו של הגר, כי אתם בעצמכם הייתם גרים בארץ מצרים.",
  "23_10": "במשך שש שנים תזרע את שדותיך ותאסוף את היבול שלך.",
  "23_11": "אך בשנה השביעית עליך להשבית את האדמה ולעזוב אותה; עניי עמך יוכלו לאכול ממה שיצמח בה, ומה שיישאר יוכלו חיות השדה לאכול; כך תעשה גם לכרמך ולמטעי הזיתים שלך.",
  "23_12": "שישה ימים תעשה את כל מלאכתך וביום השביעי תשבות, כדי שיוכלו לנוח השור והחמור שלך, ויירגעו בן שפחתך והגר המתגורר איתך.",
  "23_13": "היזהרו לשמור את כל הדברים שאמרתי לכם; אל תזכירו שמות של אלים אחרים, ושמם לא יישמע מפיכם כלל.",
  "23_14": "שלוש פעמים בשנה תחגגו לי חג.",
  "23_15": "שמור את חג המצות: שבעה ימים תאכל מצות כפי שציוויתי אותך בזמן חודש האביב, כי בו יצאת ממצרים; ואף אדם לא יבוא לבית המקדש בידיים ריקות (הביאו קרבנות חג).",
  "23_16": "וחגוג את חג הקציר (שבועות) עם ראשית יבוליך אשר תזרע בשדה; ואת חג האסיף (סוכות) בסוף השנה החקלאית, כאשר תאסוף את כל תוצרתך מן השדה.",
  "23_17": "שלוש פעמים בשנה יתייצבו כל הגברים לפני האדון ה'.",
  "23_18": "אל תשחט את דם קרבן הפסח שלי בעוד שיש אצלך חמץ, ואל תשאיר את חלקי השומן של הקרבן עד הבוקר.",
  "23_19": "את היבול המובחר ביותר מביכורי אדמתך תביא אל בית ה' אלוהיך; אל תבשל גדי בחלב של אמו (איסור בשר בחלב).",
  "23_20": "הנה אני שולח מלאך לפניך שישמור עליך בדרך ויביא אותך אל המקום שהכנתי עבורך.",
  "23_21": "היזהר בפניו ושמע בקולו, אל תמרה את פיו; כי הוא אינו מוסמך לסלוח על פשעיכם, שהרי שמי וסמכותי מצויים בקרבו.",
  "23_22": "אך אם תשמע בקולו ותעשה את כל מה שאצווה – אהיה אויב לאויביך ואצר לכל מי שמצר לך.",
  "23_23": "כי מלאכי יצעד לפניך ויביא אותך אל האמורי, החיתי, הפריזי, הכנעני, החיווי והיבוסי, ואני אכרית אותם מפניך.",
  "23_24": "אל תשתחווה לאליהם, אל תעבוד אותם ואל תחקה את מעשיהם; אלא הרוס לחלוטין את מזבחותיהם ונפץ את מצבות הפולחן שלהם.",
  "23_25": "עבדו את ה' אלוהיכם, והוא יברך את לחמכם ואת מקורות המים שלכם, ואני אסיר כל מחלה מקרבכם.",
  "23_26": "לא תהיה אישה מפילה או עקרה בארצך, ואמלא את מספר ימי חייך בבריאות ובאריכות ימים.",
  "23_27": "אשלח את חרדתי לפניך, אבלבל את כל העמים שתגיע אליהם, ואגרום לכל אויביך להפנות עורף ולברוח מפניך.",
  "23_28": "אשלח להקות צרעות לפניך, והן יגרשו את החיווי, הכנעני והחיתי מפניך.",
  "23_29": "לא אגרש אותם מפניך בתוך שנה אחת, כדי שהארץ לא תהפוך לשוממה וחיות הפרא לא יתרבו נגדך.",
  "23_30": "לאט לאט אגרש אותם מפניך, עד אשר תתרבה ותמלא את הארץ ותירש אותה.",
  "23_31": "אקבע את גבולות ארצך מים סוף ועד ים פלשתים (הים התיכון), ומן המדבר ועד נהר פרת; כי אמסור בידכם את תושבי הארץ ותגרשו אותם מפניכם.",
  "23_32": "אל תכרתו שום ברית איתם ועם אלוהיהם.",
  "23_33": "אל תאפשרו להם להמשיך לגור בארצכם פן יגרמו לכם לחטוא נגדי; כי אם תעבדו את אליהם, הדבר יהפוך לכם למלכודת קטלנית.",
  "24_1": "ואל משה אמר ה': 'עלה אל ה' – אתה, אהרן, נדב, אביהוא ושבעים מזקני ומנהיגי ישראל, והשתחוו מרחוק'.",
  "24_2": "'רק משה לבדו ייגש אל ה', והם לא יתקרבו; ושאר העם לא יעלו איתו כלל'.",
  "24_3": "משה בא ומסר לעם את כל דברי ה' ואת כל החוקים והמשפטים; כל העם ענה פה אחד ואמר: 'את כל הדברים שה' ציווה – נעשה!'.",
  "24_4": "משה כתב את כל דברי ה', השכים מוקדם בבוקר ובנה מזבח לרגלי ההר, והציב שתים עשרה מצבות כנגד שנים עשר שבטי ישראל.",
  "24_5": "הוא שלח צעירים מבני ישראל (הבכורות) והם העלו עולות וזבחו פרים כזבחי שלמים לה'.",
  "24_6": "משה לקח מחצית מן הדם ושם באגנים, ואת המחצית השנייה זרק על המזבח לכפרה.",
  "24_7": "הוא לקח את ספר הברית וקרא אותו בקול באוזני כל העם; והם הכריזו: 'כל מה שה' אמר – נעשה ונשמע בקשב רב!'.",
  "24_8": "משה לקח את הדם, התיז לכיוון העם ואמר: 'הנה זהו דם הברית שכרת ה' איתכם על פי כל הדברים האלה'.",
  "24_9": "אז עלו משה, אהרן, נדב, אביהוא ושבעים מזקני ישראל.",
  "24_10": "והם ראו במחזה נבואי את כבוד אלוהי ישראל, ותחת רגליו מראה של רצפת ספיר טהורה, זוהרת ובהירה כמו השמיים בשיא טוהPageרם.",
  "24_11": "ואלוהים לא פגע לרעה במנהיגי בני ישראל באותו מעמד; הם חזו במראה האלוהי מתוך יראה ושמחה, ואכלו ושתו מסעודת הקרבנות.",
  "24_12": "ה' אמר למשה: 'עלה אליי לראש ההר והישאר שם; ואתן לך את לוחות האבן, את התורה ואת המצווה שכתבתי כדי ללמד אותם'.",
  "24_13": "משה קם יחד עם יהושע משרתו, ומשה עלה אל הר האלוהים.",
  "24_14": "ולזקנים אמר: 'חכו לנו כאן עד שנחזור אליכם; והנה אהרן וחור נשארים איתכם, מי שיש לו סכסוך או בעיה משפטית – שיפנה אליהם'.",
  "24_15": "משה עלה אל ההר, וענן סמיך כיסה את ההר.",
  "24_16": "כבוד ה' שכן על הר סיני והענן כיסה אותו במשך שישה ימים; ביום השביעי קרא ה' אל משה מתוך הענן.",
  "24_17": "ומראה כבוד ה' נראה לעיני כל בני ישראל כמו אש לוהטת ואוכלת בראש ההר.",
  "24_18": "משה נכנס לתוך הענן ועלה עוד במעלה ההר; משה שהה על ההר ארבעים יום וארבעים לילה ללא מזון ושתייה.",
  "25_1": "ה' דיבר אל משה ואמר לו:",
  "25_2": "'דבר אל בני ישראל ואיסוף מהם תרומה והקדשה עבורי; מכל אדם שלבו מניע אותו לתרום ברצון ובנדיבות – קבלו את תרומתי'.",
  "25_3": "'ואלה החומרים והתרומות שתאספו מהם: זהב, כסף ונחושת'.",
  "25_4": "'חוטי צמר בצבע תכלת (צבוע מחלזון ימי), צמר ארגמן (סגול-אדום), צמר צבוע בשני (אדום עז), בדי פשתן מובחרים (שש), וצמר עיזים'.",
  "25_5": "'עורות אילים צבועים באדום, עורות מובחרים וחזקים (תחשים), ועצי שיטים'.",
  "25_6": "'שמן זית זך ונקי למאור, ובשמים מובחרים עבור שמן המשחה ועבור קטורת הסמים הריחנית'.",
  "25_7": "'אבני שוהם יקרות, ואבני חן מובחרות לשיבוץ באפוד ובחושן המשפט של הכהן הגדול'.",
  "25_8": "'הם יבנו עבורי מקדש, וכך אשכין את נוכחותי בתוכם'.",
  "25_9": "'בנו את המשכן ואת כל הכלים שבו בדיוק לפי הדגם המפורט שאני מראה לך כאן בהר'.",
  "25_10": "'יבנו ארון מעצי שיטים: אורכו שתיים וחצי אמות (כ-125 ס\"מ), רוחבו אמה וחצי (כ-75 ס\"מ), וגובהו אמה וחצי'.",
  "25_11": "'צפה את הארון בזהב טהור מבפנים ומבחוץ, ועשה סביבו עיטור מסגרת מוזהב (זר זהב)'.",
  "25_12": "'יצוק עבורו ארבע טבעות מזהב, וחבר אותן לארבע פינותיו: שתי טבעות בצד האחד, ושתי טבעות בצדו השני'.",
  "25_13": "'הכן מוטות נשיאה מעצי שיטים, וצפה גם אותם בזהב'.",
  "25_14": "'הכנס את המוטות לתוך הטבעות שעל צדי הארון, כדי שניתן יהיה לשאת בעזרתם את הארון ממקום למקום'.",
  "25_15": "'המוטות יישארו בתוך טבעות הארון בקביעות, ואסור להוציא אותם מהן לעולם'.",
  "25_16": "'שים בתוך הארון את לוחות העדות (לוחות הברית) שאתן לך'.",
  "25_17": "'הכן מכסה עליון לארון (כפורת) עשוי מזהב טהור בלבד: אורכו שתיים וחצי אמות, ורוחבו אמה וחצי'.",
  "25_18": "'עשה שני כרובים (דמויות מכונפות) מזהב טהור; עשה אותם במקשה אחת כחלק רציף מגוש הזהב של הכפורת, משני קצותיה'.",
  "25_19": "'דמות כרוב אחת בקצה האחד, ודמות כרוב שנייה בקצה השני; חלקו את שני הכרובים ישירות מתוך גוף הכפורת על שני צדיה'.",
  "25_20": "'הכרובים יפרשו את כנפיהם כלפי מעלה, יסוככו בכנפיהם על הכפורת, ופניהם יהיו מופנים זה מול זה בהכנעה כלפי מטה אל הכפורת'.",
  "25_21": "'הנח את מכסה הכפורת על הארון מלמעלה, ולתוך הארון תכניס את לוחות העדות שאתן לך'.",
  "25_22": "'שם אפגש איתך ואדבר איתך מעל הכפורת, מבין שני הכרובים שעל ארון הברית, ואמסור לך את כל ההנחיות והמצוות עבור בני ישראל'.",
  "25_23": "'הכן שולחן מעצי שיטים: אורכו שתי אמות, רוחבו אמה אחת, וגובהו אמה וחצי'.",
  "25_24": "'צפה אותו בזהב טהור, ועשה סביבו עיטור מסגרת מזהב'.",
  "25_25": "'הכן סביב השולחן מסגרת ברוחב טפח (כ-8 ס\"מ), ועשה עיטור זהב סביב המסגרת הזו'.",
  "25_26": "'יצוק עבורו ארבע טבעות זהב, וחבר אותן לארבע הפינות של ארבע רגליו'.",
  "25_27": "'הטבעות יותקנו בסמוך למסגרת, וישמשו כבתים להשחלת מוטות הנשיאה של השולחן'.",
  "25_28": "'הכן את המוטות מעצי שיטים וצפה אותם בזהב, ובאמצעותם יישאו את השולחן במסעות'.",
  "25_29": "'הכן גם את כלי השולחן מזהב טהור: את הקערות להנחת הלחם, את הבזיכים לקטורת הלבונה, ואת הקנים והעמודים התומכים במערכות הלחם'.",
  "25_30": "'והנח על השולחן את לחם הפנים שיהיה מונח לפניי בקביעות תמיד'.",
  "25_31": "'הכן מנורה מזהב טהור; המנורה כולה תיעשה במקשה אחת בגילוף ובחבטה מגוש זהב אחד – הבסיס שלה, הקנה המרכזי, הגביעים הדמויי כוסות, הכפתורים הדמויי תפוחים והפרחים המעוטרים – כולם יהיו חלק מגוף אחד'.",
  "25_32": "'שישה קנים ייצאו מצדי הקנה המרכזי: שלושה קנים מצדה האחד, ושלושה קנים מצדה השני'.",
  "25_33": "'על כל אחד מששת הקנים היוצאים יהיו שלושה גביעים מעוטרים בצורת פרחי שקד, יחד עם כפתור ופרח מעוצבים'.",
  "25_34": "'ובקנה המרכזי של המנורה יהיו ארבעה גביעים מעוטרים, יחד עם כפתוריו ופרחיו'.",
  "25_35": "'כפתור מעוצב יהיה מתחת לכל זוג קנים שיוצאים מן המנורה, עבור ששת הקנים כולם'.",
  "25_36": "'הכפתורים והקנים יהיו חלק בלתי נפרד מגוף המנורה; כולה תיעשה מגוש אחד רציף של זהב טהור'.",
  "25_37": "'הכן עבורה שבעה נרות (כוסיות שמן); כשידליקו את הנרות, להבותיהם יופנו לעבר הקנה המרכזי'.",
  "25_38": "'המלקחיים לסידור הפתילות והמחתות לאיסוף האפר ייעשו גם הם מזהב טהור'.",
  "25_39": "'כיכר שלמה של זהב טהור (משקל של כ-30 ק\"ג) תשמש להכנת המנורה וכל הכלים הנלווים אליה'.",
  "25_40": "'שים לב והקפד לבנות הכל בדיוק לפי התבנית והדגם שהראיתי לך על ההר'.",
  "26_1": "'את יריעות המשכן הפנימיות תעשה מעשר יריעות אריג: שזורים מפשתן מובחר, תכלת, ארגמן וחוטי שני אדומים, כשהן מעוטרות בדמויות כרובים באריגה אומנותית'.",
  "26_2": "'אורך כל יריעה עשרים ושמונה אמות (כ-14 מטרים), ורוחבה ארבע אמות (כ-2 מטרים); לכל היריעות תהיה מידה אחידה בדיוק'.",
  "26_3": "'חמש יריעות יחוברו יחד לרצועה אחת רחבה, וחמש היריעות האחרות יחוברו גם הן יחד לרצועה שנייה'.",
  "26_4": "'הכן לולאות מחוטי תכלת לאורך השפה של היריעה הקיצונית ברצועה הראשונה, וכך תעשה גם בשפת היריעה הקיצונית ברצועה השנייה'.",
  "26_5": "'עשה חמישים לולאות ברצועה האחת וחמישים לולאות ברצועה השנייה, כך שהלולאות יעמדו בדיוק זו מול זו'.",
  "26_6": "'הכן חמישים ווי קרס מזהב, וחבר בעזרתם את שתי רצועות היריעות זו לזו, כך שכל כיסוי המשכן יהיה יחידה אחת שלמה'.",
  "26_7": "'הכן יריעות משיער עיזים שישמשו כאוהל וכיסוי מגן עליון מעל המשכן; אחד עשרה יריעות כאלה תעשה'.",
  "26_8": "'אורך כל יריעת עיזים יהיה שלושים אמות, ורוחבה ארבע אמות; מידה אחידה לכל אחת עשרה היריעות'.",
  "26_9": "'חבר חמש יריעות יחד בנפרד, ואת שש היריעות האחרות חבר יחד בנפרד; ואת היריעה השישית כפול לשניים כך שתשתלשל מעל פתח האוהל'.",
  "26_10": "'עשה חמישים לולאות בשפת היריעה הקיצונית ברצועה הראשונה, וחמישים לולאות בשפת היריעה הקיצונית ברצועה השנייה'.",
  "26_11": "'הכן חמישים ווי קרס מנחושת, הכנס את הקרסים לתוך הלולאות וחבר את האוהל ליחידה אחת יציבה'.",
  "26_12": "'החלק העודף באורך יריעות האוהל – מחצית היריעה הנוספת – ישתלשל ויתלה מעבר לדופן האחורית של המשכן'.",
  "26_13": "'והאמה העודפת מכל צד באורך היריעות תשתלשל ותכסה את קירות המשכן משני צדיו להגנה'.",
  "26_14": "'עשה מכסה מגן נוסף לאוהל מעורות אילים צבועים באדום, ומעליו מכסה עליון מעורות תחשים מובחרים להגנה מפני מזג האוויר'.",
  "26_15": "'הכן את קרשי הקירות של המשכן מעצי שיטים חזקים, כשהם עומדים זקופים זה לצד זה'.",
  "26_16": "'אורכו של כל קרש עשר אמות (כ-5 מטרים), ורוחבו אמה וחצי'.",
  "26_17": "'בתחתית כל קרש יהיו שתי בליטות חיבור (יתדות), מקבילות זו לזו, כדי לחבר אותן לבסיסים; כך תעשה לכל קרשי המשכן'.",
  "26_18": "'הכן את הקרשים לקירות: עשרים קרשים עבור הדופן הדרומית'.",
  "26_19": "'הכן ארבעים בסיסי כסף כבדים (אדנים) שיונחו מתחת לעשרים הקרשים – שני בסיסים מתחת לכל קרש, אחד לכל בליטה'.",
  "26_20": "'ועבור הדופן הצפונית של המשכן הכן גם כן עשרים קרשים'.",
  "26_21": "'וארבעים בסיסי כסף תחתיהם, שני בסיסים מתחת לכל קרש'.",
  "26_22": "'ועבור הקיר המערבי האחורי של המשכן תעשה שישה קרשים'.",
  "26_23": "'ועוד שני קרשים נוספים תעשה עבור פינות המשכן בפינות האחוריות'.",
  "26_24": "'קרשי הפינות יהיו תואמים וצמודים מלמטה, ומחוברים בראשם בטבעת עליונה; כך ייעשה לשני קרשי הפינות'.",
  "26_25": "'בסך הכל יהיו בקיר המערבי שמונה קרשים ושישה עשר בסיסי כסף תחתיהם, שני בסיסים מתחת לכל קרש'.",
  "26_26": "'הכן קורות עץ לחיזוק (בריחים) מעצי שיטים: חמישה בריחים לקיר הדרומי של המשכן'.",
  "26_27": "'וחמישה בריחים לקיר הצפוני, וחמישה בריחים לקיר המערבי האחורי'.",
  "26_28": "'והבריח האמצעי יעבור דרך חללים מיוחדים בתוך עובי הקרשים, ויחבר את הקיר מקצה אחד עד הקצה השני'.",
  "26_29": "'צפה את הקרשים בזהב, התקן עליהם טבעות זהב שישמשו בתים להשחלת הבריחים, וצפה גם את הבריחים בזהב'.",
  "26_30": "'הקם את המשכן בדיוק על פי המבנה והתוכנית שהראיתי לך בהר'.",
  "26_31": "'הכן וילון הפרדה פנימי (פרוכת): ארוג מחוטי תכלת, ארגמן, שני אדום ופשתן שזור מובחר, עם דמויות כרובים באריגה אומנותית'.",
  "26_32": "'תלה את הפרוכת על ארבעה עמודי שיטים מצופים זהב בעלי ווי זהב, שמוצבים על ארבעה בסיסי כסף'.",
  "26_33": "'תלה את הפרוכת מתחת לקרסי התקרה, והכנס מאחורי הפרוכת פנימה את ארון העדות; הפרוכת תבדיל עבורכם בין החלק הקדוש (הקודש) לבין החלק הקדוש ביותר (קודש הקודשים)'.",
  "26_34": "'הנח את מכסה הכפורת על ארון העדות בתוך קודש הקודשים'.",
  "26_35": "'שים את שולחן לחם הפנים מחוץ לפרוכת בצד הצפוני, ואת המנורה שים מול השולחן בצד הדרומי של המשכן'.",
  "26_36": "'הכן וילון מסך לפתח הכניסה של המשכן: שזור מתכלת, ארגמן, שני ופשתן שזור, ברקמה אומנותית'.",
  "26_37": "'הכן עבור וילון הפתח חמישה עמודי שיטים מצופים זהב עם ווי זהב, ויצוק עבורם חמישה בסיסים מנחושת'.",
  "27_1": "'הכן את המזבח החיצוני (מזבח העולה) מעצי שיטים: מבנה מרובע באורך חמש אמות וברוחב חמש אמות, וגובהו שלוש אמות (כ-1.5 מטרים)'.",
  "27_2": "'עשה ארבע בליטות דמויות קרניים על ארבע פינותיו כחלק בלתי נפרד ממנו, וצפה את כל המזבח בנחושת'.",
  "27_3": "'הכן את כל הכלים הנלווים אליו מנחושת: סירים לאיסוף האפר, יעים לפינויו, קערות מזרק לקבלת הדם, מזלגות קלשון להפיכת הבשר, ומחתות לגחלים'.",
  "27_4": "'הכן עבורו רשת נחושת בצורת רשת חורים, וחבר ארבע טבעות נחושת לארבע פינותיה'.",
  "27_5": "'התקן את הרשת מתחת לכרכוב המזבח בחלקו התחתון, כך שהיא תגיע עד לאמצע גובהו של המזבח'.",
  "27_6": "'הכן מוטות נשיאה למזבח מעצי שיטים, וצפה אותם בנחושת'.",
  "27_7": "'השחל את המוטות לתוך הטבעות בשני צדי המזבח, כדי שניתן יהיה לשאת אותו בעזרתם במסעות'.",
  "27_8": "'עשה את המזבח חלול מלוחות עץ (שימולא באדמה בעת החניה), בדיוק כפי שהראיתי לך בהר'.",
  "27_9": "'הקם מתחם חצר סביב המשכן: עבור הצד הדרומי הכן וילונות אריג (קלעים) מפשתן שזור מובחר, באורך מאה אמות (כ-50 מטרים)'.",
  "27_10": "'והעמד עשרים עמודים שיוצבו על עשרים בסיסי נחושת, כאשר הווים של העמודים והחישוקים שלהם עשויים מכסף'.",
  "27_11": "'וכך גם עבור הצד הצפוני: וילונות באורך מאה אמות, עשרים עמודים על עשרים בסיסי נחושת, עם ווים וחישוקים מכסף'.",
  "27_12": "'ורוחב החצר בצד המערבי: וילונות באורך חמישים אמות, על גבי עשרה עמודים ועשרה בסיסי נחושת'.",
  "27_13": "'ורוחב החצר בצד המזרחי לכיוון הזריחה יהיה גם כן חמישים אמות'.",
  "27_14": "'מצד אחד של השער יהיו וילונות באורך חמש עשרה אמות, על שלושה עמודים ושלושה בסיסים'.",
  "27_15": "'וגם מהצד השני של השער יהיו וילונות באורך חמש עשרה אמות, על שלושה עמודים ושלושה בסיסים'.",
  "27_16": "'ובפתח שער החצר יהיה וילון מסך באורך עשרים אמות: ארוג ברקמה מתכלת, ארגמן, שני ופשתן שזור, על גבי ארבעה עמודים וארבעה בסיסים מנחושת'.",
  "27_17": "'כל עמודי החצר סביב יהיו מחושקים בחישוקי כסף, עם ווי כסף ובסיסי נחושת'.",
  "27_18": "'אורך מתחם החצר יהיה מאה אמות, רוחבו חמישים אמות, וגובה הווילונות חמש אמות; כולם מפשתן שזור על בסיסי נחושת'.",
  "27_19": "'כל כלי העבודה של המשכן, וכן כל יתדות האוהל ויתדות החצר לתקיעה בקרקע – יהיו עשויים מנחושת'.",
  "27_20": "ואתה תצווה את בני ישראל שיביאו אליך שמן זית טהור וזך, שנסחט מן הטיפה הראשונה של הזיתים הכתושים, כדי להדליק את נרות המנורה באופן קבוע בכל לילה.",
  "27_21": "בתוך אוהל מועד, מחוץ לווילון הפרוכת שמסתיר את ארון העדות, יסדרו אהרן ובניו את הנרות שיבערו מערב ועד בוקר לפני ה'; זהו חוק קבוע לכל הדורות מאת בני ישראל.",
  "28_1": "ואתה קרב אליך את אהרן אחיך ואת בניו יחד איתו מתוך כל בני ישראל כדי שישרתו ככהנים לפניי: את אהרן, ואת בניו נדב, אביהוא, אלעזר ואיתמר.",
  "28_2": "הכן בגדי קודש מיוחדים לאהרן אחיך, כדי לשוות לו כבוד, הדר ותפארת.",
  "28_3": "ודבר אל כל בעלי המלאכה והאומנים המוכשרים שניחנתי בכישרון וברוח חוכמה, והם יכינו את בגדי אהרן כדי להקדיש אותו לתפקיד הכהונה עבורי.",
  "28_4": "ואלה הבגדים שהם יכינו: חושן משפט, אפוד, מעיל עליון, כתונת משובצת, מצנפת ראש, ואבנט חגורה; הם יכינו בגדי קודש לאהרן אחיך ולבניו כדי שישרתו אותי ככהנים.",
  "28_5": "והם ייקחו לשם כך חוטי זהב, חוטי צמר תכלת, ארגמן, שני אדום ובדי פשתן מובחרים (שש).",
  "28_6": "הם יכינו את האפוד (מעין סינר מפואר): מחוטי זהב שזורים יחד עם תכלת, ארגמן, שני ופשתן שזור, במעשה אומנות מוקפד.",
  "28_7": "יהיו לו שתי כתפיות מחוברות בשני קצותיו, שבאמצעותן הוא ייסגר ויתחבר על הכתפיים.",
  "28_8": "וחגורת האפוד המחוברת אליו תיעשה בדיוק מאותם החומרים והצבעים: מזהב, תכלת, ארגמן, שני ופשתן שזור.",
  "28_9": "קח שתי אבני שוהם יקרות, וחרוט עליהן את שמות שנים עשר שבטי ישראל.",
  "28_10": "שישה שמות על האבן האחת, ואת ששת השמות הנותרים על האבן השנייה, לפי סדר לידתם.",
  "28_11": "בחריטה אומנותית ומדויקת כמו חותם תחרות את שמות שבטי ישראל על שתי האבנים, ותשבץ אותן בתוך מסגרות זהב מעוטרות.",
  "28_12": "חבר את שתי האבנים המשובצות על כתפיות האפוד, כאבני זיכרון לבני ישראל; ואהרן יישא את שמותיהם על שתי כתפיו לפני ה' לזיכרון טוב תמיד.",
  "28_13": "הכן מסגרות שיבוץ מזהב טהור.",
  "28_14": "והכן שתי שרשראות מזהב טהור, קלועות כחבלים מפותלים, וחבר את השרשראות אל מסגרות הזהב.",
  "28_15": "הכן חושן משפט (לוח חזה מפואר) באותה אריגה מובחרת כמו האפוד: מזהב, תכלת, ארגמן, שני ופשתן שזור.",
  "28_16": "החושן יהיה מרובע ומקופל לשניים ככיס: אורכו זרת (כ-25 ס\"מ) ורוחבו זרת.",
  "28_17": "שבץ בו ארבעה טורים של אבני חן יקרות: הטור הראשון – אבן אודם, פטדה וברקת.",
  "28_18": "הטור השני – אבן נופך, ספיר ויהלום.",
  "28_19": "הטור השלישי – אבן לשם, שבו ואחלמה.",
  "28_20": "והטור הרביעי – אבן תרשיש, שוהם וישפה; כולן יהיו משובצות בזהב בתוך מסגרותיהן.",
  "28_21": "האבנים יהיו כנגד שמות שנים עשר בני ישראל; על כל אבן ייחרט שמו של שבט אחד כמו בחותם.",
  "28_22": "הכן עבור החושן שרשראות קלועות מזהב טהור.",
  "28_23": "עשה שתי טבעות זהב לחלקו העליון של החושן, וחבר אותן לשתי פינותיו העליונות.",
  "28_24": "השחל את שתי שרשראות הזהב לתוך שתי הטבעות שבקצוות החושן.",
  "28_25": "ואת שני קצוות השרשראות חבר לשתי מסגרות השיבוץ שעל כתפיות האפוד מקדימה.",
  "28_26": "הכן עוד שתי טבעות זהב, ושם אותן בשני קצוותיו התחתונים של החושן, בצדו הפנימי הפונה לעבר האפוד.",
  "28_27": "ועשה עוד שתי טבעות זהב בתחתית שתי כתפיות האפוד מקדימה, מעל מקום החיבור של החגורה.",
  "28_28": "וקשרו את טבעות החושן אל טבעות האפוד בחוט תכלת חזק, כך שהחושן יישב בצמוד מעל חגורת האפוד ולא יזוז ממקומו.",
  "28_29": "כך יישא אהרן את שמות בני ישראל בחושן המשפט על לבו בכל פעם שייכנס אל הקודש, לזיכרון לפני ה' תמיד.",
  "28_30": "שים בתוך כיס חושן המשפט את ה'אורים והתומים' (שמות קדושים שהאירו את אותיות התשובה), והם יהיו על לב אהרן בבואו לפני ה'; כך יישא אהרן את משפט ישראל על לבו תמיד.",
  "28_31": "הכן את מעיל האפוד שכולו עשוי אך ורק מחוטי צמר תכלת.",
  "28_32": "פתח הצוואר שלו יהיה באמצעו, עם שפת בד כפולה ושזורה מסביב כדי שלא ייקרע כלל.",
  "28_33": "לאורך שולי המעיל התחתונים עשה רימוני נוי קטנים מחוטי תכלת, ארגמן ושני, וביניהם שלב פעמוני זהב טהור מסביב.",
  "28_34": "פעמון זהב ורימון, פעמון זהב ורימון, לסירוגין סביב כל שולי המעיל.",
  "28_35": "אהרן ילבש אותו בעת שירותו בקודש, וקול צלצול הפעמונים יישמע כאשר ייכנס אל המקדש לפני ה' וכאשר ייצא, כדי שיפעל ביראת כבוד ולא יפגע.",
  "28_36": "הכן לוחית זהב טהורה (ציץ) למצח, וחרוט עליה כמו בחותם: 'קודש לה''.",
  "28_37": "חבר את הלוחית בעזרת שרוך תכלת למצנפת, כך שהיא תהיה מונחת במרכז מצחו של אהרן.",
  "28_38": "הציץ יהיה תמיד על מצחו של אהרן כדי לרצות ולכפר על שגגות בענייני קרבנות הקודש של בני ישראל, לרצון טוב עבורם לפני ה'.",
  "28_39": "ארוג את הכתונת ממשבצות פשתן מובחר, הכן מצנפת מפשתן, ועשה אבנט חגורה ברקמה אומנותית.",
  "28_40": "ולבני אהרן (הכהנים ההדיוטות) תכין כותנות, אבנטים ומגבעות ראש – למען כבוד והדר.",
  "28_41": "הלבש את הבגדים האלה את אהרן אחיך ואת בניו יחד איתו, משח אותם בשמן המשחה, קדש והסמך אותם לתפקידם כדי שישרתו אותי ככהנים.",
  "28_42": "הכן להם גם מכנסי פשתן לצניעות כדי לכסות את הגוף מן המותניים ועד הירכיים.",
  "28_43": "אהרן ובניו ילבשו אותם בכל עת שייכנסו לאוהל מועד או שייגשו למזבח לשרת בקודש, כדי שלא יישאו עוון וימותו; זהו חוק עולם לו ולצאצאיו אחריו.",
  "29_1": "וזה הטקס שעליך לעשות כדי להקדיש אותם לכהן לי: קח פר צעיר אחד ושני אילים בריאים לחלוטין ללא שום מום.",
  "29_2": "ולחמי מצות רגילים, חלות מצה בלולות בשמן, ורקיקי מצה מרוחים בשמן – כולם מסולת חיטים משובחת.",
  "29_3": "שים את כל המאפים בסל אחד, והבא אותם בסל יחד עם הפר ושני האילים.",
  "29_4": "הבא את אהרן ואת בניו אל פתח אוהל מועד, ורחץ אותם במים במקווה טהרה.",
  "29_5": "קח את הבגדים והלבש את אהרן את הכתונת, את מעיל התכלת, את האפוד ואת החושן, והדק עליו את חגורת האפוד.",
  "29_6": "חבוש את המצנפת על ראשו, וחבר את לוחית הזהב הקדושה (הציץ) על גבי המצנפת.",
  "29_7": "קח את שמן המשחה הקדוש, יצוק אותו על ראשו ומשח אותו להקדשה.",
  "29_8": "לאחר מכן קרב את בניו והלבש אותם בכותנות שלהם.",
  "29_9": "חגור אותם באבנטים וחבוש לראשיהם את המגבעות; והכהונה תהיה עבורם לזכות ולחוק נצחי; כך תסמיך ותקדש את אהרן ואת בניו לתפקידם.",
  "29_10": "הבא את הפר לפני אוהל מועד, ואהרן ובניו יניחו ויסמכו את ידיהם על ראש הפר.",
  "29_11": "שחט את הפר לפני ה' בפתח אוהל מועד.",
  "29_12": "קח מדמו של הפר ומרח באצבעך על ארבע קרנות המזבח, ואת כל שאר הדם שפוך בבסיס המזבח.",
  "29_13": "קח את כל השומן הפנימי העוטף את הקרביים, את יותרת הכבד, את שתי הכליות ואת השומן שעליהן, והקטר אותם על המזבח.",
  "29_14": "אך את בשר הפר, עורו והפרש שלו תשרוף באש מחוץ למחנה, כי זהו קרבן חטאת.",
  "29_15": "קח את האיל הראשון, ואהרן ובניו יסמכו את ידיהם על ראש האיל.",
  "29_16": "שחט את האיל, קח את דמו וזרוק אותו סביב על דפנות המזבח.",
  "29_17": "חתוך את האיל לנתחיו, רחץ את קרביו ורגליו במים, והנח אותם יחד עם נתחיו וראשו.",
  "29_18": "הקטר את כל חלקי האיל על המזבח; זהו קרבן עולה שלם לה', ריח ניחוח המתקבל ברצון לפני ה'.",
  "29_19": "קח את האיל השני (איל המילואים וההסמכה), ואהרן ובניו יסמכו את ידיהם על ראשו.",
  "29_20": "שחט את האיל, קח מדמו ושים על תנוך אוזנם הימנית של אהרן ובניו, על בוהן ידם הימנית ועל בוהן רגלם הימנית; ואת שאר הדם זרוק סביב על המזבח.",
  "29_21": "קח מן הדם שעל המזבח ומשמן המשחה, והזה על אהרן ובגדיו ועל בניו ובגדיהם; וכך יתקדשו הוא ובגדיו ובניו ובגדיהם יחד איתו.",
  "29_22": "קח מן האיל את חלקי השומן הנבחרים, את האליה (הזנב השמן), את השומן הפנימי, יותרת הכבד, שתי הכליות, שומנן ואת שוק הימין – כי זהו איל הסמכה מיוחד.",
  "29_23": "והוסף כיכר לחם אחת, חלת מצה משוחה בשמן אחת, ורקיק מצה אחד מתוך הסל שלפני ה'.",
  "29_24": "שים את כל החלקים האלה על כפות ידיהם של אהרן ובניו, והנף אותם בתנועת תנופה קדימה ואחורה, מעלה ומטה לפני ה'.",
  "29_25": "קח את החלקים מידיהם והקטר אותם על המזבח יחד עם העולה, לריח ניחוח המתקבל ברצון לה'.",
  "29_26": "קח את חזה איל המילואים של אהרן והנף אותו בתנופה לפני ה'; והחלק הזה יינתן לך (למשה) כמנת חלקך בימי ההסמכה.",
  "29_27": "וקדש לעתיד את חזה התנופה ואת שוק התרומה מכל קרבנות השלמים של בני ישראל, שיינתנו לאהרן ולבניו.",
  "29_28": "זו תהיה זכותם הקבועה של אהרן ושל בניו מאת בני ישראל לכל הדורות, מתוך קרבנות השלמים שהם מביאים לה'.",
  "29_29": "ובגדי הקודש של אהרן יעברו לצאצאיו אחריו, כדי שיימשחו ויוסמכו בהם בעת שייכנסו לתפקיד.",
  "29_30": "במשך שבעה ימים ילבש אותם הכהן הגדול החדש מבין בניו, אשר יבוא אל אוהל מועד לשרת בקודש.",
  "29_31": "ואת בשר איל ההסמכה תיקח ותבשל במקום קדוש בחצר המשכן.",
  "29_32": "אהרן ובניו יאכלו את בשר האיל ואת הלחם שבסל בפתח אוהל מועד.",
  "29_33": "הם יאכלו את הקרבנות שבאמצעותם כופר עליהם והוסמכו לקדושה; אך שום אדם זר שאינו כהן לא יאכל מהם, כי הם קודש.",
  "29_34": "ואם יישאר משהו מבשר ההסמכה או מן הלחם עד הבוקר – שרוף את הנותר באש, כי אסור לאוכלו לאחר שעבר זמנו.",
  "29_35": "כך תבצע את טקס ההסמכה לאהרן ולבניו במשך שבעה ימים רצופים, כפי שציוויתי אותך.",
  "29_36": "בכל יום משבעת הימים תקריב פר חטאת אחד לכפרה, תטהר את המזבח מחטא בכך שתכפר עליו, ותמשח אותו בשמן כדי לקדשו.",
  "29_37": "שבעה ימים תכפר על המזבח ותקדש אותו; המזבח יהפוך לקודש קדשים, וכל מה שייגע בו יתקדש.",
  "29_38": "וזה מה שעליך להקריב על המזבח באופן קבוע: שני כבשים בני שנה בכל יום תמיד.",
  "29_39": "כבש אחד תקריב בבוקר, ואת הכבש השני תקריב בשעות בין הערביים.",
  "29_40": "ולכל כבש תצרף מנחה של עשירית האיפה סולת מעורבבת ברבע הין שמן זית זך, ונסך יין של רבע הין על המזבח.",
  "29_41": "את הכבש השני תקריב בין הערביים עם אותה מנחה ואותו נסך כמו בבוקר, לריח ניחוח הנרצה לה'.",
  "29_42": "זהו קרבן עולת תמיד קבוע לכל דורותיכם בפתח אוהל מועד לפני ה', המקום שבו אפגש איתכם כדי לדבר אליך שם.",
  "29_43": "שם אוועד לבני ישראל, והמקום יתקדש בכבודי ובנוכחותי.",
  "29_44": "אקדש את אוהל מועד ואת המזבח, וגם את אהרן ואת בניו אקדש כדי שישרתו אותי ככהנים.",
  "29_45": "ואשכין את נוכחותי בתוך בני ישראל, ואהיה להם לאלוהים.",
  "29_46": "והם ידעו שאני ה' אלוהיהם, אשר הוצאתי אותם מארץ מצרים כדי לשכון בתוכם; אני ה' אלוהיהם.",
  "30_1": "'הכן מזבח מיוחד להקטרת קטורת סמים (מזבח הזהב הפנימי), ועשה אותו מעצי שיטים'.",
  "30_2": "'אורכו אמה אחת ורוחבו אמה אחת – מבנה מרובע – וגובהו שתי אמות; ארבע קרנותיו בפינות יהיו חלק בלתי נפרד מגופו'.",
  "30_3": "'צפה אותו בזהב טהור: את חלקו העליון, את ארבעה קירותיו סביב ואת קרנותיו; ועשה סביבו עיטור מסגרת מזהב'.",
  "30_4": "'עשה לו שתי טבעות זהב מתחת למסגרת בשני צדיו, שישמשו כבתים להשחלת מוטות הנשיאה שבעזרתם יישאו אותו'.",
  "30_5": "'הכן את מוטות הנשיאה מעצי שיטים, וצפה אותם בזהב'.",
  "30_6": "'הצב את המזבח לפני וילון הפרוכת שמול ארון העדות, מול הכפורת שמעל הלוחות – במקום שבו אוועד איתך'.",
  "30_7": "'אהרן יקטיר עליו קטורת סמים ריחנית בכל בוקר ובוקר, בזמן שהוא מטיב ומנקה את נרות המנורה'.",
  "30_8": "'וגם כאשר אהרן ידליק את הנרות בין הערביים יקטיר את הקטורת; זו תהיה קטורת קבועה לפני ה' לאורך כל הדורות'.",
  "30_9": "'אל תעלו עליו שום קטורת זרה שלא נצטוותה, וגם לא קרבנות עולה, מנחה או נסכי יין; הוא מיועד אך ורק לקטורת'.",
  "30_10": "'פעם אחת בשנה, ביום הכיפורים, יכפר אהרן על קרנות המזבח מדם קרבן החטאת; פעם בשנה יכפר עליו לדורותיכם, כי קודש קדשים הוא לה''.'",
  "30_11": "ה' דיבר אל משה ואמר לו:",
  "30_12": "'כאשר תפקוד ותספור את מספר בני ישראל, כל אדם ייתן סכום כופר נפש לה' בעת המפקד, וכך לא תפרוץ בהם שום מגפה בעת הספירה'.",
  "30_13": "'זה הסכום שייתן כל מי שנכלל במפקד: מחצית השקל (מטבע כסף קבועה לפי תקן המקדש, שערכו עשרים גרה); מחצית השקל הזו תינתן כתרומה לה''.'",
  "30_14": "'כל גבר מגיל עשרים ומעלה שנכלל במפקד ייתן את תרומת ה'.' ",
  "30_15": "'העשיר לא יוסיף מעבר למחצית השקל והעני לא יגרע ממנה; כולם שווים במתן תרומת ה' כדי לכפר על נפשותיכם'.",
  "30_16": "'קח את כספי הכיפורים האלה מאת בני ישראל והקדש אותם לעבודת אוהל מועד (ליציקת בסיסי המשכן ולקניית קרבנות הציבור); והדבר יהיה לבני ישראל לזיכרון ולזכות לפני ה'.' ",
  "30_17": "ה' דיבר עוד אל משה ואמר:",
  "30_18": "'הכן כיור מנחושת עם בסיס מעמד מנחושת לרחצת הכהנים; הצב אותו בין אוהל מועד לבין המזבח, ומלא אותו במים'.",
  "30_19": "'אהרן ובניו ירחצו ממנו את ידיהם ואת רגליהם יחד לפני תחילת עבודתם'.",
  "30_20": "'בכל פעם שהם נכנסים אל אוהל מועד או ניגשים למזבח להקריב קרבן באש לה' – עליהם לרחוץ במים כדי שלא ייפגעו וימותו'.",
  "30_21": "'הם ירחצו את ידיהם ורגליהם כדי להישמר בחיים; וזה יהיה חוק קבוע עבורו ועבור צאצאיו לאורך כל הדורות'.",
  "30_22": "ה' דיבר אל משה ואמר:",
  "30_23": "'קח לך את הבשמים המובחרים והאיכותיים ביותר: בושם מור זך במשקל חמש מאות שקלים, קינמון ריחני במחצית המשקל – מאתיים וחמישים שקלים, וקנה בושם מאתיים וחמישים שקלים'.",
  "30_24": "'וגם קידה ריחנית במשקל חמש מאות שקלים, ושמן זית זך בנפח של הין אחד'.",
  "30_25": "'רקח מכל החומרים האלה שמן משחה קדוש ומיוחד, מעשה מרקחת של בושם מקצועי; שמן זה יהיה קודש קדשים'.",
  "30_26": "'ובאמצעותו תמשח ותקדש את אוהל מועד ואת ארון העדות'.",
  "30_27": "'את שולחן לחם הפנים ואת כל כליו, את המנורה ואת כליה, ואת מזבח הקטורת המוזהב'.",
  "30_28": "'את מזבח העולה החיצוני ואת כל כליו, ואת כיור הרחצה ואת בסיסו'.",
  "30_29": "'תקדש את כולם והם יהיו קודש קדשים; כל מה שייגע בהם יקבל קדושה'.",
  "30_30": "'ואת אהרן ואת בניו תמשח ותקדש כדי שישרתו אותי ככהנים'.",
  "30_31": "'ואל בני ישראל תאמר: שמן משחה קדוש זה יישאר מוקדש לי לכל הדורות'.",
  "30_32": "'אסור למרוח אותו על גופו של אדם רגיל שאינו כהן, ואסור לייצר שום תערובת בושם באותו הרכב ומתכון מדויק; הוא קדוש, ויישאר קדוש עבורכם'.",
  "30_33": "'כל מי שירקח שמן באותו מתכון או ימרח ממנו על אדם זר – ייכרת וייפרד מעם ישראל'.",
  "30_34": "ה' אמר למשה: 'קח לך סממני בושם: נטף (צרי), שחלת (ציפורן) וחלבנה ריחנית, יחד עם לבונה טהורה; מכל אחד מהם תיקח משקל שווה ומדויק'.",
  "30_35": "'והכן מהם קטורת משובחת, מעשה רוקח מקצועי, מעורבבת היטב במלח, טהורה וקדושה'.",
  "30_36": "'כתוש וטחן ממנה אבקה דקה מאוד, ושים ממנה לפני ארון העדות באוהל מועד שבו אפגש איתך; קודש קדשים תהיה הקטורת הזו עבורכם'.",
  "30_37": "'ואת תערובת הקטורת שתכין לפי המתכון הזה – אסור לכם להכין לעצמכם לשימוש פרטי; היא תהיה מוקדשת אך ורק לה''.'",
  "30_38": "'כל אדם שיכין קטורת באותו הרכב כדי להריח אותה להנאתו – ייכרת מתוך עמו'.",
  "31_1": "ה' דיבר אל משה ואמר לו:",
  "31_2": "'ראה, בחרתי וקראתי בשם לבצלאל בן אורי בן חור, משבט יהודה'.",
  "31_3": "'מילאתי אותו ברוח אלוהית, בחוכמה, בהבנה, בדעת עמוקה ובכישרון לכל מלאכת אומנות:'",
  "31_4": "'לתכנן תוכניות אומנותיות מורכבות, ולעבוד בזהב, בכסף ובנחושת'.",
  "31_5": "'לחתוך ולשבץ אבני חן יקרות, לגלף בעץ, ולבצע כל סוג של מלאכת מחשבת'.",
  "31_6": "'ולצידו מיניתי את אהליאב בן אחיסמך משבט דן; ובלב כל בעלי המלאכה המוכשרים נטעתי חוכמה יתרה, כדי שיוכלו לבנות את כל מה שציוויתי אותך:'",
  "31_7": "'את אוהל מועד, את ארון הברית והכפורת שעליו, ואת כל כלי המשכן'.",
  "31_8": "'את השולחן ואת כליו, את המנורה הטהורה ואת כל כליה, ואת מזבח הקטורת'.",
  "31_9": "'את מזבח העולה ואת כל כליו, ואת כיור הרחצה ואת בסיסו'.",
  "31_10": "'את בגדי השרד המיוחדים, את בגדי הקודש לאהרן הכהן, ואת בגדי הכהונה של בניו'.",
  "31_11": "'את שמן המשחה הקדוש, ואת קטורת הסמים הריחנית למקדש; בדיוק כפי שציוויתי אותך – כך הם יעשו'.",
  "31_12": "ה' אמר למשה:",
  "31_13": "'אמור לבני ישראל: למרות מלאכת המשכן החשובה, שמרו בקפדנות את ימי השבת שלי! כי השבת היא אות וסימן ברית ביני לביניכם לכל הדורות, כדי שתדעו שאני ה' המקדש אתכם'.",
  "31_14": "'שמרו את השבת כי היא קדושה עבורכם; מי שמחלל אותה במזיד דינו מוות, וכל מי שעושה בה מלאכה – אותה נפש תיכרת מקרב עמה'.",
  "31_15": "'שישה ימים מותר לעשות מלאכה, אך היום השביעי הוא שבת מנוחה מוחלטת המוקדשת לה'; כל מי שעושה מלאכה ביום השבת יומת'.",
  "31_16": "'בני ישראל ישמרו את השבת ויקיימו אותה לאורך כל דורותיהם כברית נצחית לעולם'.",
  "31_17": "'ביני לבין בני ישראל היא תהיה לאות נצחי, שהרי בשישה ימים ברא ה' את השמיים ואת הארץ, וביום השביעי שבת ממלאכה ונח'.",
  "31_18": "וכאשר סיים אלוהים לדבר עם משה על הר סיני, הוא נתן לו את שני לוחות העדות – לוחות אבן הכתובים ישירות באצבע אלוהים.",
  "32_1": "העם ראה שמשה מתעכב לרדת מן ההר מעבר לזמן שציפו; הם התקהלו סביב אהרן ואמרו לו: 'קום ועשה לנו אלוהים שיצעד לפנינו, כי האיש הזה משה שהעלה אותנו ממצרים – איננו יודעים מה קרה לו!'.",
  "32_2": "אהרן אמר להם (בניסיון לעכב אותם בתקווה שמשה יחזור בינתיים): 'הורידו את נזמי הזהב שבאוזני נשותיכם, בניכם ובנותיכם, והביאו אותם אליי'.",
  "32_3": "כל האנשים הורידו מיד את נזמי הזהב שהיו באוזניהם והביאו אותם אל אהרן.",
  "32_4": "אהרן לקח את הזהב מידיהם, יצק אותו בתבנית ועשה ממנו פסל עגל מסכה מזהב; אז קראו ההמונים: 'אלה אלוהיך ישראל אשר העלו אותך מארץ מצרים!'.",
  "32_5": "אהרן ראה את ההתלהבות ובנה מזבח לפני העגל; הוא הכריז: 'מחר יהיה חג לה'!' (מתוך כוונה לדחות את הפולחן עד שמשה יופיע).",
  "32_6": "למחרת הם השכימו מוקדם בבוקר, הקריבו עולות והביאו שלמים; העם ישב לאכול ולשתות, ואחר כך קמו להשתולל, לרקוד ולפרוק כל עול.",
  "32_7": "ה' אמר למשה: 'רד מיד מן ההר, כי עמך שהעלית מארץ מצרים השחית את דרכו'.",
  "32_8": "'הם סטו מהר מאוד מן הדרך שציוויתי אותם: הכינו לעצמם עגל מסכה מזהב, השתחוו לו, זבחו לו ואמרו: אלה אלוהיך ישראל שהעלו אותך ממצרים'.",
  "32_9": "ה' הוסיף ואמר למשה: 'ראיתי את העם הזה, והנה זהו עם עקשן, מרדן וקשה עורף'.",
  "32_10": "'ועכשיו אל תנסה לעצור אותי; זעמי יבער בהם ואשמיד אותם, וממך אקים עם חדש, גדול ועצום במקומם!'.",
  "32_11": "אך משה התחנן והפציר בכל לבו לפני ה' אלוהיו ואמר: 'למה ה' יבער כעסך בעמך שלך, שאותו הוצאת ממצרים בכוח כה גדול וביד חזקה?!'.",
  "32_12": "'למה שהמצרים יאמרו בלעג: בכוונה רעה הוא הוציא אותם – רק כדי להרוג אותם בהרים ולהשמידם מעל פני האדמה?! שוב מחרון אפך, והתחרט מלהביא את הרעה הזו על עמך'.",
  "32_13": "'זכור לאברהם, ליצחק ולישראל עבדיך, שנשבעת להם בעצמך והבטחת: ארבה את זרעכם כמו כוכבי השמיים, ואת כל הארץ הזו אתן לצאצאיכם והם יירשו אותה לתמיד'.",
  "32_14": "וה' שמע לתפילת משה, ניחם וחזר בו מן הכוונה להשמיד את עמו מיד.",
  "32_15": "משה הסתובב וירד מן ההר כששני לוחות העדות בידיו – לוחות אבן שהיו חרותים וכתובים משני עבריהם, מפה ומפה.",
  "32_16": "והלוחות עצמם היו מעשה ידי אלוהים, והכתב היה כתב אלוהי שנחרט בנס בתוך האבן.",
  "32_17": "יהושע שמע את קולות הצעקה וההמולה של העם במחנה, ואמר למשה: 'יש קול מלחמה במחנה!'.",
  "32_18": "אך משה ענה: 'אין זה קול של מנצחים במלחמה, ואין זה קול של מנוצחים המייבבים בכאב; זהו קול של הוללות, שירה ופריקת עול שאני שומע'.",
  "32_19": "וכאשר משה התקרב למחנה וראה את עגל הזהב ואת הריקודים סביבו, זעמו בער בו; הוא השליך את שני הלוחות מידיו וניפץ אותם לרסיסים לרגלי ההר.",
  "32_20": "הוא לקח את העגל שעשו, שרף אותו באש, טחן אותו לאבקה דקה, פיזר את האבקה על פני המים והשקה בהם את בני ישראל.",
  "32_21": "משה שאל את אהרן בתקיפות: 'מה עשה לך העם הזה, שהבאת עליו חטא כה חמור ונורא?!'.",
  "32_22": "אהרן ענה: 'אל יכעס אדוני; הרי אתה בעצמך מכיר את העם ויודע כמה קל להם להיגרר לרע'.",
  "32_23": "'הם אמרו לי: עשה לנו אלוהים שילך לפנינו, כי משה שהעלה אותנו ממצרים – איננו יודעים מה קרה לו'.",
  "32_24": "'אז אמרתי להם: למי שיש זהב, שיוריד אותו וייתן לי; זרקתי את הזהב לאש, ואיכשהו יצא העגל הזה'.",
  "32_25": "משה ראה שהעם פרוע לחלוטין ואיבד כל רסן, כי אהרן אפשר להם להתפרק לקלון מול כל שונאיהם.",
  "32_26": "משה נעמד בשער המחנה וקרא בקול גדול: 'מי שנאמן לה' – שיבוא אליי!'; וכל בני שבט לוי נאספו מיד סביבו.",
  "32_27": "הוא אמר להם: 'כה אמר ה' אלוהי ישראל: שימו כל אחד את חרבו על ירכו, עברו הלוך ושוב משער לשער במחנה, והרגו כל מי שהוזהר והשתחווה לעגל – אפילו אם מדובר באחיו, בחברו או בקרובו!'.",
  "32_28": "בני לוי פעלו בדיוק כפי שהורה משה, ובאותו יום נהרגו מתוך העם כ-3,000 איש מבין החוטאים הראשיים.",
  "32_29": "משה אמר לבני לוי: 'הקדשתם את עצמכם היום לה' במסירות נפש למען הצדק, אפילו נגד קרובי משפחה שחטאו, ולכן חלה עליכם היום ברכה מיוחדת'.",
  "32_30": "למחרת אמר משה לעם: 'אתם חטאתם חטא נורא וכבד; עכשיו אעלה שוב אל ה', אולי אצליח להשיג סליחה וכפרה על חטאתכם'.",
  "32_31": "משה חזר אל ה' ואמר בכאב: 'אנא ה'! העם הזה חטא חטא גדול ביותר ועשה לעצמו אליל מזהב'.",
  "32_32": "'ועכשיו, אם תוכל למחול ולסלוח לחטאתם – מה טוב; ואם אינך סולח – מחק אותי בבקשה מהספר שכתבת! אינני רוצה להמשיך לחיות אם הם יושמדו!'.",
  "32_33": "ה' ענה למשה: 'רק את מי שחטא נגדי אמחק מספרי'.",
  "32_34": "'ועכשיו לך והנהג את העם אל המקום שהבטחתי לך; הנה מלאכי יצעד לפניך, וביום שבו אפקוד עליהם עונש על חטאים עתידיים – אזכור להם גם את חטא העגל הזה'.",
  "32_35": "וה' הכה את העם במגפה, על כך שדרשו ויצרו את העגל שאותו הכין אהרן.",
  "33_1": "ה' אמר למשה: 'קום ועלה מכאן, אתה והעם שהעלית מארץ מצרים, אל הארץ שנשבעתי לאברהם, ליצחק וליעקב לתת לזרעם'.",
  "33_2": "'אשלח מלאך לפניך, ואגרש את הכנעני, האמורי, החיתי, הפריזי, החיווי והיבוסי'.",
  "33_3": "'עלו אל ארץ שופעת חלב ודבש; אך שכינתי לא תעלה בקרבכם ישירות כי אתם עם עקשן ומרדן, פן אשמיד אתכם בדרך אם תחטאו שוב'.",
  "33_4": "כאשר שמע העם את הבשורה הקשה והמעציבה הזו הם נכנסו לאבל כבד, ואיש לא ענד את תכשיטיו.",
  "33_5": "ה' אמר למשה: 'אמור לבני ישראל: אתם עם קשה עורף; אילו עליתי בקרבכם ישירות לרגע אחד והייתם חוטאים – הייתי משמיד אתכם; לכן הורידו מעליכם את תכשיטיכם, ואז אחליט כיצד לנהוג בכם בהכנעתכם'.",
  "33_6": "ובני ישראל הסירו מעליהם את תכשיטיהם ועטריהם הרוחניים מהר חורב ואילך.",
  "33_7": "ומשה לקח את אוהלו והציב אותו מחוץ למחנה, במרחק רב מן המחנה, וקרא לו 'אוהל מועד'; וכל מי שביקש לפנות אל ה' ולהתפלל יצא אל האוהל שמחוץ למחנה.",
  "33_8": "בכל פעם שמשה היה יוצא אל האוהל, כל העם היו קמים, עומדים ביראת כבוד בפתחי אוהליהם ומביטים במשה עד שנכנס לאוהל.",
  "33_9": "וכאשר משה היה נכנס לאוהל, עמוד הענן היה יורד, עומד בפתח האוהל, וה' היה מדבר עם משה.",
  "33_10": "וכל העם ראה את עמוד הענן ניצב בפתח האוהל; אז כולם היו משתחווים בפתח אוהליהם בהודיה וביראה.",
  "33_11": "וה' דיבר עם משה פנים אל פנים, בבהירות גמורה ובגילוי ישיר כמו שאדם מדבר עם חברו; לאחר מכן משה היה חוזר אל המחנה, בעוד משרתו הצעיר יהושע בן נון לא מש מתוך האוהל.",
  "33_12": "משה אמר לה': 'ראה, אתה אומר לי להוביל את העם הזה, אך לא הבהרת לי את מי תשלח איתי; ואתה אמרת לי: אני מכיר אותך היטב בשמך ומצאת חן בעיניי'.",
  "33_13": "'ועכשיו, אם באמת מצאתי חן בעיניך, למד אותי והודע לי את דרכי הנהגתך כדי שאכיר אותך באמת, וזכור שהאומה הזו היא העם שלך!'.",
  "33_14": "ה' הבטיח לו: 'נוכחותי בעצמי תצעד איתכם, ואני אתן לך שלווה וביטחון'.",
  "33_15": "משה השיב בנחרצות: 'אם נוכחותך אינה הולכת איתנו בעצמה – אל תעלה אותנו מכאן כלל!'.",
  "33_16": "'כי כיצד ייוודע שאני ועמך מצאנו חן בעיניך, אם לא בכך שאתה בעצמך תצעד איתנו?! רק כך נובדל ונתייחד אני ועמך מכל שאר העמים שעל פני כדור הארץ'.",
  "33_17": "ה' ענה למשה: 'גם את הבקשה הזו שביקשת אקיים, כי מצאת חן בעיניי ואני מכיר אותך בשמך'.",
  "33_18": "אז ביקש משה בקשת קודש עליונה: 'הראה לי בבקשה את מלוא כבודך והתגלותך!'.",
  "33_19": "ה' השיב: 'אני אעביר את כל טובי על פניך ואקרא בשם ה' לפניך; ואחון את מי שארצה לחון, וארחם על מי שארצה לרחם'.",
  "33_20": "והוסיף: 'אך לא תוכל לראות את פניי (עצמות כבודי המלאה), כי שום אדם אינו יכול לראות אותי בהיותו בחיים ולהישאר בחיים'.",
  "33_21": "ה' אמר עוד: 'הנה מקום מוכן לידי, והתייצב שם על הסלע'.",
  "33_22": "'וכאשר כבודי יעבור, אשים אותך בנקיק הסלע ואגן עליך בידי עד שאעבור'.",
  "33_23": "'אחר כך אסיר את כפי ותוכל לראות את אחוריי (את עקבותיי והשפעת הנהגתי בעולם), אך פניי ועצמותי לא ייראו'.",
  "34_1": "ה' אמר למשה: 'פסול לך שני לוחות אבן חדשים, בדיוק כמו הלוחות הראשונים ששברת; ואני אכתוב על הלוחות את אותם הדברים שהיו על הלוחות הראשונים'.",
  "34_2": "'והיה מוכן לבוקר; עלה בבוקר אל הר סיני והתייצב לפניי שם על ראש ההר'.",
  "34_3": "'ושום אדם לא יעלה איתך ואיש אל ייראה בכל ההר; אפילו הצאן והבקר לא ירעו מול ההר, בצניעות ובשקט מוחלט'.",
  "34_4": "משה פסל שני לוחות אבן כמו הראשונים, השכים מוקדם בבוקר ועלה אל הר סיני כפי שה' ציווה עליו, כששני לוחות האבן בידיו.",
  "34_5": "ה' ירד בענן והתייצב איתו שם, וקרא בשם ה'.",
  "34_6": "ה' עבר על פניו והכריז את שלוש עשרה מידות הרחמים: 'ה' ה' – אל רחום וחנון, סבלני וארך אפיים, שופע חסד ואמת'.",
  "34_7": "'שומר חסד לאלפי דורות, סולח לעוון, לפשע ולחטא, מנקה לשבים בתשובה; אך פוקד עוון אבות על בנים ובני בנים עד דור שלישי ורביעי – למי שממשיכים בדרכי הרשע של אבותיהם'.",
  "34_8": "משה מיהר להרכין ראש, כרע ארצה והשתחווה בהתרגשות רבה.",
  "34_9": "ואמר: 'אם אכן מצאתי חן בעיניך אדוני, אנא ילך נא אדוני בקרבנו; נכון שזהו עם עקשן, אך סלח לעוונותינו ולחטאנו וקבל אותנו להיות לעם סגולתך!'.",
  "34_10": "ה' השיב: 'הנה אני כורת ברית חדשה: מול כל עמך אעשה ניסים ונפלאות שלא נבראו מעולם בכל העולם ובשום עם; וכל העם שאתה חי בקרבו יראה את מעשה ה' הנהדר והנורא שאני עושה איתך'.",
  "34_11": "'שמור בקפידה את מה שאני מצווה עליך היום: הנה אני מגרש מפניך את האמורי, הכנעני, החיתי, הפריזי, החיווי והיבוסי'.",
  "34_12": "'הישמר לך היטב שלא לכרות שום ברית שלום עם תושבי הארץ שאתה בא אליה, פן יהיו לך למלכודת הרסנית בקרבך'.",
  "34_13": "'אלא נתצו את מזבחותיהם, שברו את מצבות הפולחן שלהם, וכרתו את עצי האשרה שלהם'.",
  "34_14": "'כי אסור לך להשתחוות לשום אל אחר; הרי ה' שמו 'קנא', הוא אל שאינו סובל בגידה והשתתפות עם אלילים'.",
  "34_15": "'היזהרו פן תכרתו ברית עם יושבי הארץ, ואז הם יזנו וילכו אחרי אליליהם, יזבחו להם, יזמינו אתכם ותאכלו מזבחיהם'.",
  "34_16": "'ואז תיקחו מבנותיהם נשים לבניכם, ובנותיהם ימשכו את בניכם ללכת אחרי אליליהן ולחטוא'.",
  "34_17": "'שום אלילי מסכה לא תעשו לכם'.",
  "34_18": "'שמור את חג המצות: שבעה ימים תאכל מצות כפי שציוויתי אותך למועד חודש האביב, כי בחודש האביב יצאת ממצרים'.",
  "34_19": "'כל בכור הפותח רחם שייך לי; וכל ולד זכר בכור במקנך – שור או שה'.",
  "34_20": "'ובכור חמור תפדה בשה, ואם אינך פודה – ערוף את מפרקתו; כל בכור מבין בניך תפדה בכסף, ואל תיראו לפניי במקדש בידיים ריקות'.",
  "34_21": "'שישה ימים תעבוד וביום השביעי תשבות ממלאכה; אפילו בעונות החקלאיות הבוערות ביותר – בעונת החריש ובעונת הקציר – תשבות בשבת'.",
  "34_22": "'וחגוג את חג השבועות עם ביכורי קציר החיטים, ואת חג האסיף בסוף השנה החקלאית'.",
  "34_23": "'שלוש פעמים בשנה יתייצבו כל הגברים לפני האדון ה' אלוהי ישראל'.",
  "34_24": "'כי אגרש עמים מפניכם וארחיב את גבולות ארצכם, ושום אדם לא יחמוד ולא ינסה לכבוש את ארצכם בזמן שתעלו להיראות לפני ה' שלוש פעמים בשנה (הבטחת הגנה ניסית על הבתים בעת העלייה לרגל)'.",
  "34_25": "'אל תשחט את דם קרבן הפסח שלי בעוד שיש אצלך חמץ, ואל תשאיר שום חלק מקרבן חג הפסח לבוקר'.",
  "34_26": "'את המובחר מביכורי אדמתך תביא אל בית ה' אלוהיך; אל תבשל גדי בחלב של אמו'.",
  "34_27": "ה' אמר למשה: 'כתוב לעצמך את הדברים האלה, כי על פי הדברים האלה כרתי ברית איתך ועם ישראל'.",
  "34_28": "משה שהה שם עם ה' ארבעים יום וארבעים לילה; הוא לא אכל לחם ולא שתה מים, וה' כתב על הלוחות את דברי הברית – את עשרת הדיברות.",
  "34_29": "כאשר משה ירד מהר סיני כששני לוחות העדות בידיו, הוא לא ידע שעור פניו קורן באור זוהר ומופלא בעקבות דיבורו עם ה'.",
  "34_30": "אהרן וכל בני ישראל ראו את משה, והנה עור פניו זוהר ומפיץ קרני אור עוצמתיות; והם נרתעו ופחדו לגשת אליו.",
  "34_31": "משה קרא להם להירגע; אז חזרו אליו אהרן וכל מנהיגי העדה, ומשה דיבר איתם.",
  "34_32": "לאחר מכן ניגשו כל שאר בני ישראל, ומשה מסר להם את כל המצוות וההוראות שה' דיבר איתו בהר סיני.",
  "34_33": "כאשר סיים לדבר איתם, שם משה מסווה מגן על פניו.",
  "34_34": "ובכל פעם שמשה היה נכנס לפני ה' לדבר איתו, הוא היה מסיר את המסווה עד צאתו; וכאשר יצא, מסר לבני ישראל את כל מה שנצטווה.",
  "34_35": "ובני ישראל ראו את פני משה כי עור פניו קרן באור זוהר; ומשה שב והניח את המסווה על פניו עד שנכנס שוב לדבר עם ה'.",
  "35_1": "משה כינס את כל קהילת בני ישראל (למחרת יום הכיפורים) ואמר להם: 'אלה הדברים והמצוות שה' ציווה לבצע:'",
  "35_2": "'במשך שישה ימים תעשו מלאכה, אך היום השביעי יהיה עבורכם יום קדוש, שבת של מנוחה מוחלטת לה'; כל מי שיעשה בו מלאכה יומת'.",
  "35_3": "'אל תבעירו שום אש בכל מקומות מגוריכם ביום השבת (אזהרה מיוחדת להבערת אש הדרושה למלאכות המשכן)'.",
  "35_4": "משה פנה שוב אל כל קהילת בני ישראל ואמר: 'זה הדבר שה' ציווה לומר:'",
  "35_5": "'קחו מתוככם תרומה לה'; כל מי שלבו מניע אותו בנדיבות יביא את תרומת ה': זהב, כסף ונחושת'.",
  "35_6": "'חוטי צמר תכלת, ארגמן, שני אדום, בדי פשתן מובחרים (שש), וצמר עיזים'.",
  "35_7": "'עורות אילים צבועים באדום, עורות תחשים מובחרים, ועצי שיטים'.",
  "35_8": "'שמן זית זך למאור המנורה, ובשמים מובחרים לשמן המשחה ולקטורת הסמים הריחנית'.",
  "35_9": "'אבני שוהם יקרות, ואבני חן מובחרות לשיבוץ באפוד ובחושן המשפט'.",
  "35_10": "'וכל בעלי המלאכה והאומנים המוכשרים מביניכם יבואו ויבנו את כל מה שה' ציווה:'",
  "35_11": "'את מבנה המשכן, את אוהלו ומכסהו, את ווי הקרסים שלו, את קרשי קירותיו, את בריחיו, עמודיו ובסיסיו'.",
  "35_12": "'את ארון הברית ומוטות הנשיאה שלו, את מכסה הכפורת, ואת וילון הפרוכת המבדיל'.",
  "35_13": "'את שולחן לחם הפנים, מוטותיו וכל כליו, ואת לחם הפנים הקבוע'.",
  "35_14": "'את מנורת המאור, כליה ונרותיה, ואת שמן המאור הנקי'.",
  "35_15": "'את מזבח הקטורת המוזהב ומוטותיו, את שמן המשחה הקדוש, את קטורת הסמים הריחנית, ואת וילון המסך לפתח המשכן'.",
  "35_16": "'את מזבח העולה מנחושת ואת רשת הנחושת שלו, את מוטותיו וכל כליו, ואת כיור הרחצה ובסיסו'.",
  "35_17": "'את וילונות מתחם החצר, עמודיו ובסיסיהם, ואת וילון המסך לשער החצר'.",
  "35_18": "'את יתדות האוהל והחצר ואת החבלים לקשירתם'.",
  "35_19": "'את בגדי השרד המיוחדים לשרת בקודש – את בגדי הקודש לאהרן הכהן ואת בגדי הכהונה לבניו'.",
  "35_20": "כל קהילת בני ישראל יצאו מנוכחותו של משה כדי להתארגן ולהביא את תרומותיהם.",
  "35_21": "כל אדם שלבו עורר אותו וכל מי שהרגיש נדיבות פנימית באו והביאו את תרומת ה' למלאכת אוהל מועד, לכל כלי עבודתו ולבגדי הקודש.",
  "35_22": "הגברים והנשים הגיעו יחד; כל מי שהיה נדיב לב הביא תכשיטי זהב: עגילים, נזמים, טבעות, צמידים וכל מיני חפצי זהב – כל מי שרצה להניף ולהקדיש תרומת זהב לה'.",
  "35_23": "וכל מי שהיה ברשותו חוטי תכלת, ארגמן, שני, פשתן, צמר עיזים, עורות אילים צבועים באדום או עורות תחשים – הביא אותם בשמחה.",
  "35_24": "כל מי שהרים תרומת כסף או נחושת הביא את תרומת ה'; וכל מי שהיו ברשותו עצי שיטים המתאימים למלאכה – הביא אותם.",
  "35_25": "וכל הנשים המיומנות והמוכשרות טוו בידיהן, והביאו את החוטים שטוו: תכלת, ארגמן, שני ופשתן.",
  "35_26": "ונשים שהצטיינו במומחיות ובכישרון מיוחד טוו את שיער העיזים ישירות בעודן חיות על גבן.",
  "35_27": "ונשיאי ומנהיגי השבטים הביאו את אבני השוהם ואת אבני החן היקרות לשיבוץ באפוד ובחושן.",
  "35_28": "וגם את הבשמים המובחרים ואת שמן הזית הזך למאור, לשמן המשחה ולקטורת הסמים.",
  "35_29": "כל גבר ואישה מקרב בני ישראל שלבם נדב אותם לתרום לכל המלאכה שה' ציווה דרך משה – הביאו תרומה ונדבה מכל הלב לה'.",
  "35_30": "משה אמר לבני ישראל: 'ראו, ה' בחר במפורש בבצלאל בן אורי בן חור, משבט יהודה'.",
  "35_31": "'הוא מילא אותו ברוח אלוהית, בחוכמה, בהבנה, בדעת עמוקה ובכישרון לכל מלאכת אומנות:'",
  "35_32": "'לתכנן תוכניות אומנותיות מורכבות, לעבוד בזהב, בכסף ובנחושת'.",
  "35_33": "'לסגל ולשבץ אבני חן, לגלף בעץ, ולבצע כל מלאכת מחשבת אומנותית'.",
  "35_34": "'והוא גם העניק לו את היכולת ללמד ולהדריך אחרים, לו ולאהליאב בן אחיסמך משבט דן'.",
  "35_35": "'הוא מילא אותם בכישרון רב לעשות כל מלאכת חרש, חושב, רוקם ואורג בחוטי תכלת, ארגמן, שני ופשתן – כאומנים ראשיים המתכננים ומבצעים כל מלאכה'.",
  "36_1": "בצלאל, אהליאב וכל האומנים המוכשרים שה' העניק להם חוכמה וכישרון לדעת כיצד לפעול – ניגשו לבצע את כל מלאכת הקודש בדיוק כפי שה' ציווה.",
  "36_2": "משה קרא לבצלאל, לאהליאב ולכל בעלי המלאכה המוכשרים שלבם ניחן בחוכמה, כל מי שהתנדב מתוך רצון פנימי לגשת אל המלאכה ולעשותה.",
  "36_3": "הם קיבלו מידי משה את כל התרומות שהביאו בני ישראל לצורך עבודת הקודש; והעם המשיך להביא נדבות נוספות בהתלהבות בכל בוקר ובוקר.",
  "36_4": "אז באו כל האומנים שעבדו במלאכת הקודש, כל איש מן העבודה שבה עסק,",
  "36_5": "ואמרו למשה: 'העם מביא הרבה יותר ממה שנחוץ למלאכה שה' ציווה לעשות!'.",
  "36_6": "משה הורה להכריז ברחבי המחנה: 'שום איש או אישה לא יכינו ולא יביאו עוד תרומות למקדש!'; וכך נעצרה הבאת התרומות מן העם.",
  "36_7": "החומרים שכבר נאספו הספיקו בשפע לכל המלאכה, ואף נותר עודף רב.",
  "36_8": "כל האומנים המוכשרים הכינו את עשר יריעות המשכן: שזורות מפשתן מובחר, חוטי תכלת, ארגמן ושני אדום, עם דמויות כרובים באריגה אומנותית.",
  "36_9": "אורך כל יריעה עשרים ושמונה אמות, ורוחבה ארבע אמות; מידה אחידה לכל היריעות.",
  "36_10": "הם חיברו חמש יריעות יחד לרצועה רחבה אחת, וחמש יריעות חיברו יחד לרצועה שנייה.",
  "36_11": "הם עשו לולאות מחוטי תכלת לאורך השפה של היריעה הקיצונית ברצועה האחת, וכך גם בשפת היריעה הקיצונית ברצועה השנייה.",
  "36_12": "חמישים לולאות עשו ברצועה האחת וחמישים לולאות ברצועה השנייה, כך שהלולאות עמדו בדיוק זו מול זו.",
  "36_13": "הם הכינו חמישים ווי קרס מזהב, וחיברו את שתי קבוצות היריעות זו לזו בעזרת הקרסים, וכך הפך כיסוי המשכן ליחידה אחת שלמה.",
  "36_14": "הם הכינו אחת עשרה יריעות משיער עיזים שישמשו כאוהל עליון מעל המשכן.",
  "36_15": "אורך כל יריעת עיזים שלושים אמות, ורוחבה ארבע אמות; מידה אחידה לכל אחת עשרה היריעות.",
  "36_16": "הם חיברו חמש יריעות יחד בנפרד, ואת שש היריעות האחרות חיברו יחד בנפרד.",
  "36_17": "הם עשו חמישים לולאות בשפת הרצועה הראשונה, וחמישים לולאות בשפת הרצועה השנייה.",
  "36_18": "הם הכינו חמישים ווי קרס מנחושת כדי לחבר את האוהל שיהיה גג אחד רצוף.",
  "36_19": "הם הכינו מכסה נוסף לאוהל מעורות אילים צבועים באדום, ומעליו מכסה עליון מעורות תחשים מובחרים.",
  "36_20": "הם הכינו את קרשי הקירות למשכן מעצי שיטים חזקים, כשהם עומדים זקופים.",
  "36_21": "אורכו של כל קרש עשר אמות, ורוחבו אמה וחצי.",
  "36_22": "בכל קרש היו שתי בליטות חיבור (יתדות) מקבילות; כך עשו לכל קרשי המשכן.",
  "36_23": "הם הכינו את הקרשים לקירות: עשרים קרשים עבור הדופן הדרומית.",
  "36_24": "וארבעים בסיסי כסף כבדים (אדנים) הכינו מתחת לעשרים הקרשים – שני בסיסים לכל קרש, אחד לכל בליטה.",
  "36_25": "ועבור הדופן הצפונית של המשכן הכינו גם כן עשרים קרשים.",
  "36_26": "וארבעים בסיסי כסף תחתיהם, שני בסיסים תחת כל קרש.",
  "36_27": "ועבור הקיר המערבי האחורי של המשכן הכינו שישה קרשים.",
  "36_28": "ועוד שני קרשים הכינו עבור הפינות האחוריות של המשכן.",
  "36_29": "קרשי הפינות היו צמודים ומחוברים מלמטה, ומחוברים בראשם בטבעת עליונה; כך עשו לשני קרשי הפינות.",
  "36_30": "בסך הכל היו בקיר המערבי שמונה קרשים ושישה עשר בסיסי כסף תחתיהם, שני בסיסים תחת כל קרש.",
  "36_31": "הם הכינו קורות עץ לחיזוק (בריחים) מעצי שיטים: חמישה בריחים לקיר הדרומי.",
  "36_32": "חמישה בריחים לקיר הצפוני, וחמישה בריחים לקיר המערבי האחורי.",
  "36_33": "והם עשו את הבריח האמצעי כך שיעבור בתוך עובי הקרשים ויחבר את הקיר מקצה לקצה.",
  "36_34": "הם ציפו את הקרשים בזהב, עשו את הטבעות מזהב כדי שישמשו בתים להשחלת הבריחים, וציפו גם את הבריחים בזהב.",
  "36_35": "הם הכינו את וילון הפרוכת מחוטי תכלת, ארגמן, שני ופשתן שזור, באריגה אומנותית עם דמויות כרובים.",
  "36_36": "הם הכינו עבור הפרוכת ארבעה עמודי שיטים וציפו אותם בזהב, הווים שלהם היו מזהב, ויצקו עבורם ארבעה בסיסי כסף.",
  "36_37": "הם הכינו וילון מסך לפתח האוהל מחוטי תכלת, ארגמן, שני ופשתן שזור, ברקמה אומנותית.",
  "36_38": "והעמידו עבורו חמישה עמודים עם ווים, ציפו את ראשיהם וחישוקיהם בזהב, וחמשת בסיסיהם היו עשויים מנחושת.",
  "37_1": "בצלאל הכין את ארון הברית מעצי שיטים: אורכו שתיים וחצי אמות, רוחבו אמה וחצי, וגובהו אמה וחצי.",
  "37_2": "הוא ציפה אותו בזהב טהור מבפנים ומבחוץ, ועשה סביבו עיטור מסגרת מוזהב (זר זהב).",
  "37_3": "הוא יצק עבורו ארבע טבעות זהב בארבע פינותיו: שתי טבעות בצדו האחד, ושתי טבעות בצדו השני.",
  "37_4": "הוא הכין מוטות נשיאה מעצי שיטים, וציפה אותם בזהב.",
  "37_5": "הוא הכניס את המוטות לתוך הטבעות שבצדי הארון, כדי שניתן יהיה לשאת בעזרתם את הארון.",
  "37_6": "הוא הכין מכסה כפורת מזהב טהור: אורכו שתיים וחצי אמות, ורוחבו אמה וחצי.",
  "37_7": "הוא יצר שני כרובים (דמויות מכונפות) מזהב טהור; הוא עיצב אותם במקשה אחת מתוך גוש הזהב של הכפורת, משני קצותיה.",
  "37_8": "כרוב אחד בקצה האחד וכרוב שני בקצה השני; שניהם נחצבו ועוצבו ישירות מגוף הכפורת.",
  "37_9": "הכרובים פרשו כנפיים כלפי מעלה וסוככו על הכפורת, פניהם היו מופנים זה מול זה והביטו מטה אל הכפורת.",
  "37_10": "הוא הכין את השולחן מעצי שיטים: אורכו שתי אמות, רוחבו אמה אחת, וגובהו אמה וחצי.",
  "37_11": "הוא ציפה אותו בזהב טהור, ועשה סביבו עיטור מסגרת מזהב.",
  "37_12": "הוא הכין סביבו מסגרת ברוחב טפח, ועשה עיטור זהב סביב המסגרת.",
  "37_13": "הוא יצק עבורו ארבע טבעות זהב, וחבר אותן לארבע הפינות של ארבע רגליו.",
  "37_14": "הטבעות הותקנו בסמוך למסגרת, כבתים להשחלת מוטות הנשיאה של השולחן.",
  "37_15": "הוא הכין את המוטות מעצי שיטים וציפה אותם בזהב, כדי לשאת בעזרתם את השולחן.",
  "37_16": "הוא הכין מזהב טהור את כל כלי השולחן: את הקערות להנחת הלחם, את הכפות לקטורת, את הקנים ואת העמודים התומכים.",
  "37_17": "הוא הכין את המנורה מזהב טהור; המנורה כולה נעשתה במקשה אחת מגוש זהב אחד – הבסיס, הקנה המרכזי, הגביעים, הכפתורים והפרחים היו כולם יחידה אחת.",
  "37_18": "שישה קנים יצאו מצדי הקנה המרכזי: שלושה קנים מצד אחד, ושלושה קנים מהצד השני.",
  "37_19": "שלושה גביעים דמויי שקדים עם כפתור ופרח היו בכל אחד מששת הקנים היוצאים מן המנורה.",
  "37_20": "ובקנה המרכזי של המנורה היו ארבעה גביעים מעוטרים, יחד עם כפתוריו ופרחיו.",
  "37_21": "כפתור מעוצב היה מתחת לכל זוג קנים שיוצאים מן המנורה, עבור ששת הקנים כולם.",
  "37_22": "הכפתורים והקנים היו חלק בלתי נפרד מגוף המנורה; כולה נעשתה במקשה אחת מגוש זהב טהור.",
  "37_23": "הוא הכין שבעה נרות (כוסיות שמן), ומלקחיים ומחתות מזהב טהור.",
  "37_24": "מכיכר שלמה של זהב טהור הוא הכין את המנורה ואת כל הכלים הנלווים אליה.",
  "37_25": "הוא הכין את מזבח הקטורת מעצי שיטים: אורכו אמה ורוחבו אמה (מרובע), וגובהו שתי אמות; קרנותיו היו חלק בלתי נפרד ממנו.",
  "37_26": "הוא ציפה אותו בזהב טהור: את גגו העליון, את ארבעה קירותיו סביב ואת קרנותיו, ועשה סביבו עיטור מסגרת מזהב.",
  "37_27": "הוא עשה לו שתי טבעות זהב מתחת למסגרת בשני צדיו, שישמשו בתים למוטות הנשיאה.",
  "37_28": "הוא הכין את מוטות הנשיאה מעצי שיטים, וציפה אותם בזהב.",
  "37_29": "הוא הכין את שמן המשחה הקדוש ואת קטורת הסמים הטהורה, מעשה רוקח מקצועי ומדויק.",
  "38_1": "הוא הכין את מזבח העולה מעצי שיטים: אורכו חמש אמות ורוחבו חמש אמות (מרובע), וגובהו שלוש אמות.",
  "38_2": "הוא עשה ארבע קרנות בארבע פינותיו כחלק בלתי נפרד ממנו, וציפה אותו בנחושת.",
  "38_3": "הוא הכין את כל כלי המזבח מנחושת: את הסירים לקליטת האפר, היעים לפינויו, הקערות לקבלת הדם, המזלגות והמחתות.",
  "38_4": "הוא הכין עבור המזבח רשת נחושת מחוררת מתחת לכרכובו מלמטה, שהגיעה עד למחצית גובהו.",
  "38_5": "הוא יצק ארבע טבעות בארבע פינות רשת הנחושת, ששימשו כבתים להשחלת מוטות הנשיאה.",
  "38_6": "הוא הכין את המוטות מעצי שיטים, וציפה אותם בנחושת.",
  "38_7": "הוא השחיל את המוטות לתוך הטבעות שבצדי המזבח כדי לשאת אותו בהם; המזבח נבנה חלול מלוחות עץ.",
  "38_8": "הוא הכין את כיור הרחצה ואת בסיסו מנחושת מובחרת – ממראות הנחושת המלוטשות שתרמו הנשים הצדקניות שהתאספו בפתח אוהל מועד.",
  "38_9": "הוא הקים את מתחם החצר: בצד הדרומי היו וילונות אריג (קלעים) מפשתן שזור מובחר, באורך מאה אמות.",
  "38_10": "עמודיהם היו עשרים עם עשרים בסיסי נחושת, והווים והחישוקים של העמודים היו עשויים מכסף.",
  "38_11": "ובצד הצפוני: וילונות באורך מאה אמות, עשרים עמודים על עשרים בסיסי נחושת, עם ווי כסף וחישוקי כסף.",
  "38_12": "ובצד המערבי: וילונות באורך חמישים אמות, עשרה עמודים על עשרה בסיסי נחושת, עם ווים וחישוקים מכסף.",
  "38_13": "ובצד המזרחי לכיוון הזריחה: חמישים אמות.",
  "38_14": "מצד אחד של השער היו וילונות באורך חמש עשרה אמות, על שלושה עמודים ושלושה בסיסים.",
  "38_15": "וכך גם מהצד השני של שער החצר: וילונות באורך חמש עשרה אמות, על שלושה עמודים ושלושה בסיסים.",
  "38_16": "כל וילונות מתחם החצר מסביב היו עשויים מפשתן שזור מובחר.",
  "38_17": "בסיסי העמודים היו מנחושת, ווי העמודים וחישוקיהם היו מכסף, ראשיהם היו מצופים כסף, וכל עמודי החצר היו מחושקים בכסף.",
  "38_18": "וילון המסך של שער החצר היה ארוג ברקמה מחוטי תכלת, ארגמן, שני ופשתן שזור; אורכו עשרים אמות וגובהו חמש אמות, תואם לגובה וילונות החצר.",
  "38_19": "ארבעת עמודיו וארבעת בסיסיהם היו מנחושת, וויהם היו מכסף, וראשיהם וחישוקיהם היו מצופים כסף.",
  "38_20": "וכל היתדות לתקיעה בקרקע עבור המשכן ועבור מתחם החצר סביב – היו עשויות מנחושת.",
  "38_21": "אלה הם נתוני החשבון המדויקים של המשכן – משכן לוחות הברית – שנערכו על פי פקודת משה, כעבודה שביצעו הלויים בפיקוחו של איתמר בן אהרן הכהן.",
  "38_22": "ובצלאל בן אורי בן חור משבט יהודה ייצר את כל מה שה' ציווה על משה.",
  "38_23": "לצידו עבד אהליאב בן אחיסמך משבט דן, שהיה אומן חרש, מעצב ורוקם בחוטי תכלת, ארגמן, שני אדום ופשתן מובחר.",
  "38_24": "כל הזהב ששימש למלאכת הקודש (שנאסף מתרומות העם) עמד על עשרים ותשעה כיכרי זהב ושבע מאות ושלושים שקלים לפי משקל הקודש (כטון זהב).",
  "38_25": "כמות הכסף שנאספה ממפקד העם הייתה מאה כיכר ואלף ושבע מאות שבעים וחמישה שקלים (כ-3 טונות כסף).",
  "38_26": "זה חושב בדיוק לפי מחצית השקל (בקע) לכל אדם מעל גיל עשרים שעבר במפקד – בסך הכל שש מאות ושלושת אלפים וחמש מאות וחמישים (603,550) גברים.",
  "38_27": "מאה כיכרי הכסף שימשו ליציקת אדני הבסיס של קירות הקודש ושל עמודי הפרוכת: מאה בסיסים ממאה כיכרות, כיכר כסף אחד (כ-30 ק\"ג) לכל בסיס.",
  "38_28": "ומשאר הכסף (1,775 שקלים) ייצר בצלאל את הווים לעמודים, ציפה את ראשי העמודים וחישק אותם בטבעות חישוק.",
  "38_29": "משקל הנחושת שנתרמה עמד על שבעים כיכר ואלפיים וארבע מאות שקלים (מעל שני טונות נחושת).",
  "38_30": "בנחושת הזו יצק את אדני הבסיס לפתח אוהל מועד, את מזבח הנחושת ואת רשת הנחושת שלו ואת כל כלי המזבח.",
  "38_31": "וכן את בסיסי עמודי החצר מסביב, את בסיסי שער החצר, ואת כל יתדות האוהל ויתדות החצר ששימשו לקשירת היריעות.",
  "39_1": "מחוטי התכלת, הארגמן והשני האדום תפרו בגדי שרד מפוארים לשירות במשכן, והכינו את בגדי הקודש עבור אהרן הכהן בדיוק כפי שה' ציווה על משה.",
  "39_2": "הם הכינו את האפוד (סינר הכהן הגדול) מזהב, חוטי תכלת, ארגמן, שני אדום ופשתן שזור מובחר.",
  "39_3": "הם ריקעו ושיטחו לוחיות זהב דקיקות וחתכו מהן חוטים דקים, כדי לשזור אותם באומנות בתוך חוטי התכלת, הארגמן, השני והפשתן.",
  "39_4": "הם תפרו לאפוד שתי רצועות כתפיים מחוברות בקצותיו, כך שיהיה רכוס ושלם.",
  "39_5": "והחגורה המחוברת אליו, שבאמצעותה הידקו אותו, הייתה עשויה מאותו אריג בדיוק: חוטי זהב, תכלת, ארגמן, שני אדום ופשתן שזור, כפי שה' ציווה על משה.",
  "39_6": "הם ליטשו ושיבצו את שתי אבני השוהם במסגרות זהב משובצות, וחרתו עליהן באומנות חותם את שמות שנים עשר שבטי ישראל.",
  "39_7": "משה הניח את האבנים על כתפות האפוד כזיכרון תמידי לבני ישראל לפני ה', בדיוק לפי צו ה'.",
  "39_8": "הם הכינו את חושן המשפט באותה אריגת מחשבת כמו האפוד: מחוטי זהב, תכלת, ארגמן, שני אדום ופשתן שזור.",
  "39_9": "החושן היה מרובע ומקופל לשניים כמעין כיס, אורכו זרת ורוחבו זרת (כ-25 ס\"מ על 25 ס\"מ).",
  "39_10": "הם שיבצו בו ארבעה טורי אבני חן: הטור הראשון כלל אודם (רובי), פטדה (טופז) וברקת (אזמרגד).",
  "39_11": "הטור השני כלל נופך (קרבונקל), ספיר ויהלום.",
  "39_12": "הטור השלישי כלל לשם (אופאל), שבו (אגט) ואחלמה (אמטיסט).",
  "39_13": "והטור הרביעי כלל תרשיש (אקוומרין), שוהם (אוניקס) וישפה (ג'ספר); כולן היו משובצות במסגרות זהב מעוטרות.",
  "39_14": "שתים עשרה האבנים היו מקבילות לשמות בני יעקב, כשעל כל אבן חרות שמו של שבט אחד משבטי ישראל.",
  "39_15": "הם הכינו עבור החושן שרשראות זהב טהור קלועות כחבלים בקצוות.",
  "39_16": "הם הכינו שתי מסגרות זהב ושתי טבעות זהב, וחיברו את שתי הטבעות לשתי הפינות העליונות של החושן.",
  "39_17": "הם השחילו את שני חבלי הזהב הקלועים לתוך שתי הטבעות שבקצוות החושן.",
  "39_18": "את שני הקצוות האחרים של שרשראות הזהב חיברו לשתי מסגרות הזהב שהיו על כתפות האפוד מלפנים.",
  "39_19": "הם הכינו עוד שתי טבעות זהב וחיברו אותן לשתי הפינות התחתונות של החושן, בצד הפנימי הפונה לכיוון האפוד.",
  "39_20": "ועוד שתי טבעות זהב קבעו בחלק התחתון של שתי כתפות האפוד, בדיוק מעל חגורת האפוד.",
  "39_21": "הם קשרו את טבעות החושן לטבעות האפוד בשרוך תכלת חזק, כדי שהחושן יישב בצמוד מעל חגורת האפוד ולא יזוז ממקומו, כפי שה' ציווה על משה.",
  "39_22": "הם ארגו את מעיל האפוד כולו מבד תכלת טהור ואחיד.",
  "39_23": "פתח הצוואר שלו היה באמצע כפתח של שריון, עם שפה תפורה ומחוזקת מסביב כדי שלא ייקרע.",
  "39_24": "על שולי המעיל התחתונים הם חיברו קישוטים בצורת רימונים העשויים מחוטי תכלת, ארגמן ושני אדום שזורים.",
  "39_25": "הם ייצרו פעמונים קטנים מזהב טהור ושילבו אותם בין הרימונים לכל אורך שולי המעיל.",
  "39_26": "פעמון לצד רימון, פעמון לצד רימון לסירוגין על כל שולי המעיל, כדי שישמיעו קול בעת השירות בקודש, כפי שציווה ה'.",
  "39_27": "הם ארגו כותנות פשתן מובחרות עבור אהרן ועבור בניו.",
  "39_28": "וכן את המצנפת המפוארת של אהרן, את מגבעות הכהנים, ואת מכנסי הבד מפשתן שזור לכיסוי הגוף.",
  "39_29": "ואת האבנט (החגורה) רקמו מחוטי פשתן שזור, תכלת, ארגמן ושני אדום, כפי שה' ציווה על משה.",
  "39_30": "הם הכינו את לוחית הזהב הטהור (הציץ) – נזר הקודש – וחרתו עליה בכתב ברור כמו חותם: 'קודש לה''.",
  "39_31": "הם קשרו אליה חוט תכלת כדי להדק אותה מעל מצנפת הפשתן של הכהן הגדול, כפי שה' ציווה.",
  "39_32": "כך הושלמה לחלוטין כל מלאכת משכן אוהל מועד; בני ישראל עשו כל פרט בדיוק כפי שה' ציווה על משה.",
  "39_33": "הם הביאו את כל חלקי המשכן אל משה לבדיקה: את האוהל, את כליו, הקרסים, הקרשים, הבריחים, העמודים והבסיסים.",
  "39_34": "את מכסה עורות האילים הצבועים באדום, את מכסה עורות התחשים, ואת וילון הפרוכת המבדיל.",
  "39_35": "את ארון הברית עם מוטות הנשיאה שלו, ואת מכסה הכפורת עם הכרובים.",
  "39_36": "את שולחן הפנים, את כל כלי השרת שלו, ואת לחם הפנים הקבוע.",
  "39_37": "את מנורת הזהב הטהור, את נרותיה הערוכים, את כל כליה הנלווים, ואת שמן הזית הזך למאור.",
  "39_38": "את מזבח הזהב לקטורת, את שמן המשחה המקודש, את קטורת הבשמים הריחנית, ואת וילון המסך לפתח האוהל.",
  "39_39": "את מזבח הנחושת ואת רשת הנחושת שלו, את מוטותיו וכל כליו, ואת כיור הנחושת עם בסיסו.",
  "39_40": "את וילונות מתחם החצר, עמודיה ובסיסיהם, את מסך שער החצר, את חבלי הקשירה ויתדות הנחושת, ואת כל כלי השירות של אוהל מועד.",
  "39_41": "את בגדי השרד המפוארים לשירות בקודש, את בגדי הקודש לאהרן הכהן הגדול, ואת בגדי הכהונה לבניו.",
  "39_42": "בני ישראל ביצעו את כל העבודה בדיוק מוחלט, בדיוק כפי שה' ציווה על משה.",
  "39_43": "משה סקר ובדק את כל המלאכה, וראה שהם עשו הכל בדיוק לפי הוראות ה'; ומשה בירך אותם באהבה: 'יהי רצון שתשרה שכינת ה' על מעשי ידיכם, ונועם ה' ילווה אתכם תמיד'.",
  "40_1": "ה' דיבר אל משה ואמר לו:",
  "40_2": "'בראש חודש ניסן (החודש הראשון בשנה), תקים ותרכיב את משכן אוהל מועד'.",
  "40_3": "'תכניס פנימה את ארון הברית, ותתלה לפניו את הפרוכת כדי להבדיל בין קודש הקודשים לקודש'.",
  "40_4": "'תכניס את שולחן הפנים ותערוך עליו את שתי מערכות הלחם, תכניס את המנורה ותדליק את שבעת נרותיה'.",
  "40_5": "'תציב את מזבח הזהב לקטורת מול ארון הברית (לפני הפרוכת), ותתלה את וילון המסך בפתח המשכן'.",
  "40_6": "'תציב את מזבח העולה מנחושת בחצר, בדיוק מול פתח משכן אוהל מועד'.",
  "40_7": "'תציב את כיור הרחצה בין אוהל מועד לבין המזבח, ותמלא אותו במים זכים'.",
  "40_8": "'תקים ותרכיב את גדר החצר מסביב, ותתלה את וילון המסך בשער הכניסה לחצר'.",
  "40_9": "'קח את שמן המשחה הקדוש ומשח בו את המשכן ואת כל מה שבתוכו, כדי לקדש אותו ואת כל כליו, והם יהיו קדושים לחלוטין'.",
  "40_10": "'משח את מזבח העולה ואת כל כליו, וקדש את המזבח – והוא יהיה קודש קודשים'.",
  "40_11": "'משח גם את כיור הנחושת ואת בסיסו, וקדש אותו'.",
  "40_12": "'קרב את אהרן ואת בניו אל פתח אוהל מועד, ורחץ אותם במים זכים מהכיור'.",
  "40_13": "'הלבש את אהרן בבגדי הקודש המיוחדים, משח אותו בשמן וקדש אותו, כדי שישרת אותי ככהן גדול'.",
  "40_14": "'לאחר מכן קרב את בניו והלבש אותם בכותנות הכהונה'.",
  "40_15": "'משח אותם כפי שמשחת את אביהם כדי שישרתו אותי ככהנים; משיחה זו תקנה להם ולצאצאיהם מעמד כהונה נצחי לכל הדורות'.",
  "40_16": "משה פעל בדיוק מופתי לפי כל מה שה' ציווה עליו.",
  "40_17": "באחד בניסן, בשנה השנייה ליציאת מצרים, הוקם המשכן לראשונה באופן קבוע.",
  "40_18": "משה הקים את המשכן: הניח את בסיסי הכסף, הציב את קרשי הקירות, השחיל את הבריחים והעמיד את העמודים.",
  "40_19": "הוא פרש את יריעות האוהל מעל המשכן ושם מעליהן את מכסה העורות העליון, כפי שה' ציווה עליו.",
  "40_20": "הוא לקח את שני לוחות הברית ושם אותם בתוך הארון, חיבר את מוטות הנשיאה לארון, והניח את מכסה הכפורת מעל הארון.",
  "40_21": "הוא הכניס את הארון לתוך קודש הקודשים, תלה את וילון הפרוכת והסתיר את ארון הברית, בדיוק כפי שה' ציווה.",
  "40_22": "הוא הציב את שולחן הפנים בתוך אוהל מועד, בצד הצפוני של החדר, מחוץ לפרוכת.",
  "40_23": "הוא סידר עליו שתי שורות של לחם הפנים לפני ה', כפי שה' ציווה.",
  "40_24": "הוא הציב את מנורת הזהב מול השולחן, בצד הדרומי של אוהל מועד.",
  "40_25": "הוא הדליק את הנרות לפני ה', בדיוק לפי מצוות ה'.",
  "40_26": "הוא הציב את מזבח הזהב בתוך אוהל מועד, ממש לפני וילון הפרוכת.",
  "40_27": "הוא הקטיר עליו קטורת בשמים ריחנית, כפי שה' ציווה.",
  "40_28": "הוא תלה את וילון המסך בפתח הכניסה למשכן.",
  "40_29": "הוא העמיד את מזבח העולה מנחושת בפתח החצר לפני המשכן, והקריב עליו את עולת התמיד ומנחתה, כפי שציווה ה'.",
  "40_30": "הוא הציב את כיור הנחושת בין אוהל מועד לבין המזבח, ומילא בו מים לרחצה.",
  "40_31": "משה, אהרן ובניו רחצו משם את ידיהם ואת רגליהם.",
  "40_32": "בכל פעם שנכנסו לאוהל מועד או התקרבו למזבח לשרת בקודש הם רחצו, בדיוק כפי שה' ציווה על משה.",
  "40_33": "הוא הקים את עמודי וילונות החצר מסביב למשכן ולמזבח, ותלה את מסך שער החצר – ובכך סיים משה את כל מלאכת הקמת המשכן.",
  "40_34": "ברגע שנסתיימה המלאכה, כיסה ענן כבוד שמימי את אוהל מועד, ונוכחות כבוד ה' מילאה את כל חלל המשכן.",
  "40_35": "משה אפילו לא היה מסוגל להיכנס לאוהל מועד, כי ענן השכינה שכן עליו במלוא עוצמתו וכבוד ה' מילא את המקום.",
  "40_36": "מעתה והלאה, כאשר התרומם הענן מעל המשכן, ידעו בני ישראל שעליהם לפרק את המחנה ולצאת לדרך בכל מסעיהם.",
  "40_37": "וכל עוד הענן נשאר לרבוץ על המשכן, הם לא נסעו, אלא חנו עד ליום שבו התרומם שוב.",
  "40_38": "כי ענן ה' שכן מעל המשכן ביום, ועמוד אש האיר בו בלילה, לעיני כל עם ישראל בכל מסעיהם ותחנותיהם במדבר."
};
